[272]={"海狮试炼",{"寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。","","在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。","","将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。"}},
