[274]={"水坝危机",{"阿什兰·暗石要你回去见主工程师辛德维尔七世，把有关这种炸药的新发现告诉他。"}},
[275]={"大地上的脓疱",{"杀死12只沼泽爬行者，然后向湿地的绿色守卫者雷希耶尔复命。"}},
[276]={"践踏之爪",{"杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。"}},
[277]={"火焰管制",{"给绿色守卫者雷希耶尔带回9块粗制打火石。"}},
[278]={"水坝危机",{"主工程师辛德维尔七世要你收集一份潜伏者的毒液，一块莫格罗什水晶和一滴鳄鱼的眼泪。"}},
[279]={"海中的鱼人",{"杀掉12个蓝腮鱼人。","","杀掉高布勒尔并砍下它的头。","","将高布勒尔的头颅交给米奈希尔港的卡尔·波兰。"}},
[280]={"水坝危机",{"主工程师辛德维尔七世要你游到水坝底部，找到装着炸药的木桶，然后把拆弹剂放进去，阻止将要发生的爆炸。"}},
[281]={"夺回雕像",{"搜索海边鱼人村落中的木箱和木桶。"}},
[282]={"森内尔的观察站",{"和巡山人萨鲁斯谈一谈。"}},
[283]={"水坝危机",{"拆弹剂看来已经产生了效果。你可以回去向主工程师辛德维尔七世汇报这个好消息了。"}},
[284]={"继续搜寻",{"搜索米奈希尔雕塑。"}},
[285]={"搜寻雕像",{"继续在鱼人村落中搜寻米奈希尔雕像的踪迹。"}},
[286]={"归还雕像",{"将米奈希尔雕像还给卡尔·波兰。"}},
[287]={"霜鬃巨魔要塞",{"侦查霜鬃巨魔要塞，替卡拉诺斯的森内尔·白须杀掉5个霜鬃猎头者。"}},
[288]={"第三舰队",{"为大副菲兹莫斯买一份壶装蜜酒。"}},
[289]={"被诅咒的船员",{"杀死13个被诅咒的水手、5个被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔的大副菲兹莫斯。"}},
[290]={"解除诅咒",{"从哈林多尔船长那里拿到无畏号的保险箱钥匙。","","用钥匙打开无畏号上的保险箱。"}},
[291]={"森内尔的报告",{"把森内尔的报告交给铁炉堡的参议员巴林·红石。"}},
[292]={"帕雷斯之眼",{"把被诅咒的帕雷斯之眼交给戈罗林·钢眉。"}},
[293]={"净化帕雷斯之眼",{"把被诅咒的帕雷斯之眼交给大主教本尼迪塔斯，他就在暴风城的光明大教堂里。"}},
[294]={"奥莫尔的复仇",{"维尔加挖掘场的奥莫尔·铁衣要求你杀死10只杂斑迅猛龙和10只杂斑尖啸龙。"}},
[295]={"奥莫尔的复仇",{"奥莫尔·铁衣要求你杀死10只杂斑刺喉龙和10只杂斑锯齿龙，然后回到维尔加挖掘场向他复命。"}},
[296]={"奥莫尔的复仇",{"维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。"}},
