[331]={"向多伦报告",{"与多伦上尉谈一谈。"}},
[332]={"酒店的广告",{"到加林纳酒店去, 将酒票交给苏泽塔·加林纳以换一瓶免费的酒。"}},
[333]={"哈兰需要供货",{"找到运河裁缝店，并将哈兰·巴格雷的布料订单带给雷玛·施涅德。"}},
