[2379]={"赞杜沙",{"与暗影裂口的赞杜沙谈一谈。"}},
[2380]={"向奥格瑞玛进发！",{"在奥格瑞玛城中的暗影裂口和申苏尔谈谈。"}},
[2381]={"抢劫海盗",{"把南海宝藏带回给棘齿城的卑鄙的维尼克斯。不要忘了从维尼克斯的机械设备中拿取一份大饼干和潜行者工具，你的任务需要使用这两件东西。","","如果你被任何奇怪的鹦鹉攻击，就对它使用大饼干！"}},
