[2440]={"白金圆盘",{"把报酬凭证交给雷霆崖的本娜·冰蹄。"}},
[2458]={"卧底密探",{"到淤泥沼泽北边的风险投资公司塔楼去，联系碎手氏族的卧底费苏勒。","","看到塔楼之后，用信号枪发射信号，向工头费苏勒示意你已经到达。发出两个闪光信号，然后使用碎手军礼和工头费苏勒接头。","","注意，这些步骤必须依次进行，因为费苏勒会攻击并干掉任何他无法识别的人。"}},
[2459]={"噬梦者菲罗斯塔",{"多兰纳尔的塔隆凯·捷根要你杀掉7个瘤背秘法师，并找到遗失的珠宝。"}},
[2460]={"碎手军礼",{"对着申苏尔练习碎手军礼。"}},
[2478]={"基本不可能的任务",{"从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。","","杀掉大工头普兹克·加里维克斯，取了他的首级，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的头颅交给奥格瑞玛的申苏尔，等候进一步的指示。"}},
[2479]={"希诺特的帮助",{"到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。","","要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！"}},
[2480]={"希诺特的帮助",{"等待瑟尔格·希诺特完成解药。"}},
[2498]={"向德纳兰回报",{"雷利亚·绿树要你和奥拉密斯湖的德纳兰谈一谈。"}},
[2499]={"奥肯斯古尔",{"奥拉密斯湖的德纳兰要你去拿到奥肯斯古尔身上的巨大的瘤。"}},
[2500]={"荒芜之地的材料",{"从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。"}},
[2501]={"荒芜之地的材料 II",{"在荒芜之地的守护火龙身上使用空的魔瓶。将这些容器都盛满之后，把它们交给塞尔萨玛的加克。"}},
[2518]={"月神的泪水",{"达纳苏斯月神殿的女祭司艾茉拉让你把萨丝拉的银色丝囊交给她。"}},
[2519]={"月神殿",{"艾奎恩妮让你和月神殿的女祭司艾茉拉谈一谈。"}},
[2520]={"萨丝拉的祭品",{"女祭司艾茉拉让你将萨丝拉的银色丝囊放在大殿的喷泉处，然后回去见她。"}},
[2521]={"为库米沙效力",{"在你探索诅咒之地的旅程中，如果碰巧发现了无暇的德莱尼水晶球，就把它交给收藏家库米沙。","","你要知道，这种宝石是整个艾泽拉斯最珍稀的水晶。诅咒之地上的任何一种生物都有可能带着一颗无暇的德莱尼水晶球。","","每找到一颗，你都会得到相应的酬劳。"}},
[2522]={"库米沙的努力",{"找到一颗无暇的德莱尼水晶球，把它交给收藏家库米沙。"}},
[2541]={"沉睡的德鲁伊",{"将一个萨满巫毒符咒交给班奈希尔兽穴的奥本·怒爪。"}},
[2561]={"利爪德鲁伊",{"奥本·怒爪要求你去杀掉他那失去灵魂的身体，然后对其尸体使用巫毒咒符。"}},
[2581]={"弯牙土狼的颚骨",{"收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"}},
[2582]={"远古之怒",{"收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"}},
[2583]={"野猪的活力",{"收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。"}},
[2584]={"野猪之魂",{"收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。"}},
[2585]={"决定性的打击",{"收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"}},
[2586]={"厚甲蝎盐",{"收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"}},
[2601]={"石化蜥蜴的大脑",{"收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。"}},
[2602]={"清晰的思想",{"收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。"}},
