[3449]={"奥术符文",{"使用绘图工具包获取贝萨玛拉符文、辛耶尔符文、玛科里符文和塞尔哈符文的拓片，然后前往艾萨拉南部半岛外的小岛，把它们交给驾驶员西格斯·熔光。"}},
[3450]={"简单的接收任务",{"与铁炉堡的希格斯·熔火谈一谈。"}},
[3451]={"信号发射器",{"与铁炉堡的希格斯·熔火谈一谈，从他那儿获得一支标准型闪光信号枪。"}},
[3452]={"烈焰之盒",{"找到一个拉格纳罗斯符记，把它交给卡拉然·温布雷。"}},
[3453]={"惩戒火炬",{"等待卡拉然·温布雷完成惩戒火炬。"}},
[3454]={"惩戒火炬",{"拿起惩戒火炬。"}},
[3461]={"向法师泰摩尔回复",{"到铁炉堡去，将法师泰摩尔的绘图工具包还给他。"}},
[3462]={"侍卫玛特拉克",{"与侍卫玛特拉克谈一谈。"}},
[3463]={"烧掉它们！",{"使用惩戒火炬点燃北部、南部、东部和西部的哨塔。"}},
[3481]={"打开箱子…",{"打开箱子。"}},
[3483]={"信号发射器",nil},
[3501]={"多多益善",{"将有瑕疵的德莱尼水晶碎片交给库米沙，你就可以得到相应的回报。"}},
[3502]={"德莱尼的垃圾…",{"将有瑕疵的德莱尼水晶碎片交给库米沙。诅咒之地的任何怪物都有可能携带着这样的碎片。"}},
[3503]={"见到主人",nil},
[3504]={"叛徒",{"把这封给阿格图的密信交给艾萨拉的阿格图·血拳。"}},
[3505]={"叛徒",{"杀死10个血精灵搜寻者和10个血精灵勘测员，并找到大法师雷姆托里的营地。一旦你发现了营地，就去找到某个对她极为重要的东西，以用于激怒她，让她与你战斗。"}},
[3506]={"叛徒",{"摧毁大法师雷姆托里携带的奥术聚焦水晶并杀死她。然后把她的脑袋交给艾萨拉的阿格图·血拳。"}},
[3507]={"叛徒",{"与奥格瑞玛的贝尔戈洛姆·石槌谈一谈。"}},
[3508]={"破坏结界",{"等待洛拉姆斯完成启迪法术。"}},
[3509]={"恶魔之名",{"与艾萨拉的亚考罗克谈一谈。你应该在海边搜索亚考兰神殿。"}},
[3510]={"恶魔之名",{"杀掉赫塔拉，将染血的赫塔拉头颅、破碎的赫塔拉头颅和淤血的赫塔拉头颅交给亚考罗克。"}},
[3511]={"恶魔之名",{"将调剂交给洛拉姆斯·萨里比迪斯。"}},
[3512]={"帮助伊兰尼库斯",{"到冬泉谷的东部地区去，与灵语者阿姆布兰希谈一谈。"}},
[3513]={"符文卷轴",{"将符文卷轴带到贫瘠之地的北部警戒塔去。"}},
[3514]={"部落的示威",{"杀死猛禽洞穴的领袖琳萨瑞尔。"}},
[3517]={"偷窃知识",{"找到贝萨玛拉石板、辛耶尔石板、玛科里石板和塞尔哈石板，把它们交给艾萨拉的杰迪加。"}},
[3518]={"玛加萨的石版",{"将贝萨玛拉石板交给雷霆崖的玛加萨·野性图腾。"}},
[3519]={"需要帮助的朋友",{"与幽影谷的迪兰妮亚·月光谈一谈。"}},
[3520]={"尖啸者的灵魂",{"在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。"}},
[3521]={"埃沃隆的解药",{"在幽影谷中为迪兰妮亚·月光收集7朵紫蓝色蘑菇、4朵月牙百合花和一份树林蜘蛛的脓液。"}},
[3522]={"埃沃隆的解药",{"在5分钟内将埃沃隆的解药交给他。你可以北边的洞穴入口外面找到埃沃隆。"}},
[3523]={"剃刀高地的亡灵天灾",{"如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。"}},
[3524]={"搁浅的巨兽",{"从奥伯丁南面的海岸上收集海洋生物的骨头，然后带着骨头向奥伯丁的温尼斯·布莱葛回复。"}},
[3525]={"封印神像",{"保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。","","当他在进行仪式封印神像时保护他。"}},
[3526]={"地精工程学",{"如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。"}},
[3527]={"摩沙鲁的预言",{"将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。"}},
[3528]={"神灵哈卡",{"将装满的哈卡之卵交给塔纳利斯的叶基亚。"}},
[3541]={"杰斯雷蒙的石版",{"将辛耶尔石板交给奥格瑞玛的杰斯雷蒙。"}},
[3542]={"安德隆·甘特的石版",{"将玛科里石板交给幽暗城的安德隆·甘特。"}},
[3561]={"大法师克希雷姆的石版",{"将塞尔哈石板交给艾萨拉的大法师克希雷姆。"}},
[3562]={"玛加萨的报酬",{"将玛加萨的便笺交给艾萨拉的杰迪加。"}},
[3563]={"杰斯雷蒙的报酬",{"将杰斯雷蒙的便笺交给艾萨拉的杰迪加。"}},
[3564]={"安德隆的报酬",{"将安德隆的便笺交给艾萨拉的杰迪加。"}},
[3565]={"克希雷姆的报酬",{"将克希雷姆的便笺交给艾萨拉的杰迪加。"}},
[3566]={"奥比斯顿",{"杀死黑衣拉索里克和奥比斯顿，带着黑衣拉索里克的头颅和奥比斯顿的心脏回到铁炉堡的索里奥斯那儿。"}},
[3567]={"登高",nil},
[3568]={"堕落之水",{"在艾萨拉的埃达拉斯废墟旁的海潮之池中收集4瓶水，然后回到药剂师科雷那儿。"}},
[3569]={"堕落之水",{"将科雷的药剂交给幽暗城的瑟尔萨·风歌。"}},
[3570]={"堕落之水",nil},
[3601]={"我就是基姆加尔！",{"搜索萨拉斯营地，找到基姆加尔的指南针、望远镜、烧鸡和花生，然后把它们交给艾萨拉的基姆加尔。"}},
[3602]={"艾萨拉水晶",{"在艾萨拉南部收集20块艾萨拉晶体。你可以使用地狱犬协助寻找一些隐藏的矿脉。","","任务完成之后就回到洛拉姆斯那里去。"}},
[3621]={"武器的铸造",{"把货物交给荆棘谷的加尔文。"}},
[3625]={"魔化艾萨拉水晶武器",{"等待加尔文为你锻造武器。"}},
[3626]={"返回诅咒之地",{"回到部落英雄的灵魂那里。"}},
[3627]={"收集破碎的护符",{"杀掉毁灭者戈洛尔、瑟温妮，以及大法师奥利斯塔。从他们到尸体上拿到戈洛尔的护符、瑟温妮的护符和奥利斯塔的护符。","","记住使用你的魔化艾萨拉水晶武器来削弱他们，否则他们是无法被杀死的——你必须小心谨慎地使用你的武器……"}},
[3628]={"恶魔拉瑟莱克",{"消灭污染者拉瑟莱克，将污染者之角交给部落英雄的灵魂。另外你还要把污染者防护结界交给他，这样部落英雄的灵魂就可以消灭它，以避免它落入邪恶势力之手。"}},
[3629]={"地精工程学",{"如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。"}},
[3630]={"侏儒工程学",{"如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。"}},
[3631]={"召唤地狱战马",{"与贫瘠之地棘齿城的斯坦哈德·法尔杉谈一谈。"}},
[3632]={"侏儒工程学",{"如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。"}},
