[4495]={"好朋友",{"在北边的洞穴附近找到埃沃隆。"}},
[4496]={"擒虫先擒王",{"把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。"}},
[4501]={"当心翼手龙",{"杀掉10只翼手龙和15只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。"}},
[4502]={"火山的活动",{"到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。"}},
[4503]={"希兹尔的的飞行器",{"为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。"}},
[4504]={"极度粘稠的沥青",{"帮加基森的特兰雷克收集12块极度粘稠的沥青。"}},
[4505]={"腐化之井",{"从碧火萨特的月亮井中收集一份被腐化的水的样本，把它交给血毒哨所的温娜·哈萨德。"}},
[4506]={"被腐蚀的猫",{"把温娜的小猫带到堕落的月亮井旁边，把猫放出来，然后把它还给温娜。","","当你回到温娜那里之后，点击猫就可以将它还给温娜。"}},
[4507]={"捕捉皇后",{"召唤格里什皇后，然后击败她。","","把格里什皇后的大脑交给加基森的炼金师匹斯特苏格。"}},
[4508]={"临危不惧",{"把匹斯特苏格的安戈洛报告交给达纳苏斯的格拉希娜·灵风。"}},
[4509]={"临危不惧",{"把匹斯特苏格的安戈洛报告交给奥格瑞玛斯的基尔兹宾·鼓眼。"}},
[4510]={"临危不惧",{"把银行赠券交给达纳苏斯银行的伊迪瑞娜。"}},
[4511]={"临危不惧",{"把银行赠券交给奥格瑞玛银行的卡鲁斯。"}},
[4512]={"远方的软泥怪",{"将6瓶被诅咒的软泥怪样本和6瓶被污染的软泥怪样本交给铁炉堡的拉里斯·空轮。"}},
[4513]={"远方的软泥怪",{"将10个纯净样本瓶交给铁炉堡的拉里斯·空轮。","","如果你无法找到它们的话，不妨到拉里斯那里去再打听一些线索。"}},
[4521]={"冬泉谷的枭兽",{"费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀15头狂怒的枭兽和15头蓬毛枭兽。"}},
[4542]={"给乱风岗的紧急信件",{"把紧急信件交给乱风岗的峭壁卫兵图林·长角。"}},
[4561]={"杂质检测 - 安戈洛环形山",nil},
[4581]={"凯尼斯·静风",{"把辛德瑞尔的便笺交给林歌神殿里的凯尼斯·静风。"}},
[4621]={"敬礼，舰队司令！",{"杀死藏宝海湾的舰队指挥官卡拉·海角和大财主里维加兹，然后回到荆棘谷海边的红雾号上去，向舰队指挥官菲尔拉伦复命。"}},
[4641]={"起点",{"与高内克谈一谈。卡尔图克在你的地图上标出了他的位置，并告诉你高内克居住在西边的大兽穴中。"}},
[4642]={"融合软泥怪",{"把一块融合的软泥怪样本交给幽暗城的化学家弗雷。"}},
[4661]={"堕落检测 - 费伍德森林",nil},
[4681]={"搁浅的巨兽",{"在奥伯丁西面海水中的海龟骸骨那里取回海龟残骸，然后与奥伯丁的温尼斯·布莱葛谈一谈。"}},
[4701]={"座狼之源",{"到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。"}},
[4721]={"冬泉谷的枭兽",{"费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀10头狂暴枭兽。"}},
[4722]={"搁浅的海龟",{"把海龟的残骸交给奥伯丁的温尼斯·布莱葛。"}},
[4723]={"搁浅的海洋生物",{"把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。"}},
[4724]={"座狼的首领",{"杀死血斧座狼的领袖，哈雷肯。"}},
[4725]={"搁浅的海龟",{"把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。"}},
[4726]={"雏龙精华",{"将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。"}},
[4727]={"搁浅的海龟",{"把海龟的残骸交给奥伯丁的温尼斯·布莱葛。"}},
