[4740]={"通缉：莫克迪普！",{"找到并杀死名为莫克迪普的鱼人。它守护着位于奥伯丁南部海岸的鱼人营地。","","向奥伯丁的哨兵戈琳达·纳希恩报告莫克迪普的死讯。"}},
[4741]={"冬泉谷的枭兽",{"费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀13头月光枭兽。"}},
[4742]={"晋升印章",{"找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。","","可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。"}},
[4743]={"晋升印章",{"到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。","","此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！"}},
[4761]={"桑迪斯·织风",{"与奥伯丁的桑迪斯·织风谈一谈。"}},
[4762]={"壁泉河",{"到奥伯丁的北面去，沿着壁泉河到达第一个瀑布处，从瀑布下的水潭中取出一份水样。","","将壁泉河水样交给奥伯丁的桑迪斯·织风。"}},
[4763]={"黑木熊怪的堕落",{"在空的净化碗里盛满奥伯丁月亮井的井水。","","在黑木熊怪的北部营地里收集水果、坚果和谷物各一份。","","将水和三种食物混合起来，放置在壁泉河附近的营火边，这样就会召来唤引诱熊怪堕落的萨特。","","取回堕落护符，将它交给奥伯丁的桑迪斯·织风。"}},
[4764]={"末日扣环",{"将末日扣环交给燃烧平原的玛亚拉·布莱特文。"}},
[4765]={"瑞治维尔的箱子",{"将瑞治维尔的箱子交给暴风城的雷明顿·瑞治维尔。"}},
[4766]={"玛亚拉·布莱特文",{"与燃烧平原的玛亚拉·布莱特文谈一谈。"}},
[4767]={"驭风者",{"将10颗双足飞龙的蛋交给乱风岗的艾鲁。"}},
[4768]={"黑暗石板",{"将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。"}},
[4769]={"薇薇安·拉格雷和黑暗石板",{"与卡加斯的暗法师薇薇安·拉格雷谈一谈。"}},
[4770]={"回家",{"护送波卡·雨山走出风巢，然后和白沙岗哨的莫特加·火鬃谈一谈。"}},
[4771]={"黎明先锋",{"将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。"}},
[4781]={"魔化金线血袍",{"将一块金锭交给荆棘谷的希兹克·古斯提。"}},
[4782]={"魔化金线血袍",{"回到贫瘠之地的梅纳拉·沃伦德那里。"}},
[4783]={"魔化金线血袍",{"将10瓶怨怒萨特之血和1块次级地狱火石交给贫瘠之地的梅纳拉·沃伦德。"}},
[4784]={"魔化金线血袍",{"将一些优质金线、2块闷烧煤和一块灵魂碎片交给贫瘠之地的梅纳拉·沃伦德。"}},
[4785]={"优质金线",nil},
[4786]={"完成金线血袍",{"等待梅纳拉·沃伦德织好披风，然后跟她谈一谈。"}},
[4787]={"远古之卵",{"将远古之卵交给塔纳利斯的叶基亚。"}},
[4788]={"最后的石板",{"将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。"}},
