[4805]={"冰草魂精",nil},
[4806]={"霜槌魂精",nil},
[4807]={"枭兽魂精",nil},
[4808]={"菲诺克",{"把丁奇的信交给菲诺克。"}},
[4809]={"冰风奇美拉角",{"将8支完整的冰风奇美拉角交给菲诺克。"}},
[4810]={"返回丁奇身边",{"把菲诺克的包裹交给燃烧平原的丁奇·斯迪波尔。"}},
[4811]={"红色水晶",{"到奥伯丁的东边去，沿着黑海岸东部边界的山脉寻找一颗巨大的红色水晶，然后向奥伯丁的哨兵戈琳达·纳希恩汇报你的发现。"}},
[4812]={"清洗水晶",{"在奥伯丁月亮井中把空水瓶装满，然后调查黑海岸东部山脉的红水晶。"}},
[4813]={"水晶中的碎骨",{"向奥伯丁的哨兵哨兵戈琳达·纳希恩报告你的发现。"}},
[4821]={"异型卵",{"把异型卵交给乱风岗的哈加尔·雷蹄。"}},
[4841]={"清除半人马",{"杀掉12个加拉克斥候、10个加拉克争斗者和6个加拉克逐风者，然后向乱风岗的峭壁卫兵图林·长角复命。"}},
[4842]={"奇怪的源头",{"根据多诺瓦·雪山的指示行动，然后回到她那里报告。"}},
[4861]={"被激怒的枭兽",{"在冬泉谷的南部寻找加隆·石矛的被破坏的营帐，以及他的补给物资。"}},
[4862]={"蜘蛛卵",{"到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。","","听说那些蜘蛛周围有许多这样的卵。"}},
[4863]={"被激怒的枭兽",{"找到加隆·石矛的马车。"}},
[4864]={"被激怒的枭兽",{"从雪地中拾起加隆的补给物资，然后寻找盗取加隆所说的护符的枭兽。","","将加隆的补给物资和蓝色羽毛护符交给冬泉谷的加隆·石矛。"}},
[4865]={"狂热之蛇",{"向莫特加·火鬃汇报你的发现。"}},
[4866]={"蛛后的乳汁",{"你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。"}},
[4867]={"乌洛克",{"阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。"}},
[4881]={"暗杀计划",{"将暗杀计划通知给白沙岗哨的卡纳提·灰云。"}},
[4882]={"守护秘密",{"把蓝羽项链交给血毒岗哨的特鲁尔·法贝恩。"}},
[4883]={"守护秘密",{"把蓝羽项链交给纳拉·蛮鬃。"}},
[4901]={"祭坛守护者",{"在兰莎尔拉尝试激活艾露恩祭坛的过程中保护她。然后将你的发现报告给鲁瑟兰村的艾瑞拉斯·琥珀。"}},
[4902]={"艾露恩的枭兽",{"与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。"}},
[4903]={"高图斯的命令",{"杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。"}},
[4904]={"终获自由",{"护送拉克塔·风歌离开恐怖图腾营地，然后与乱风岗的萨利亚谈一谈。"}},
[4906]={"更深重的堕落",{"费伍德森林的艾瑞丹·蓝风要你去杀掉8个碧火唤魔者、8个碧火背叛者、8个碧火欺诈者和萨瓦里克。任务完成之后回到艾瑞丹那里复命。"}},
[4907]={"丁奇·斯迪波尔",{"与丁奇·斯迪波尔谈一谈。"}},
[4921]={"在战斗中失踪",{"找到曼科里克的妻子，然后回到十字路口找他。"}},
[4941]={"伊崔格的智慧",{"和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。","","你回忆起曾在萨尔的大厅中见过伊崔格。"}},
[4961]={"奥拉赫宝珠的净化",{"杀死宝珠之魔，然后与塔贝萨谈一谈。"}},
[4962]={"地狱犬的灵魂",{"带上地狱犬红宝石到凄凉之地去，用它捕获一只地狱犬的灵魂。成功之后，将地狱犬红宝石和被禁锢的地狱犬灵魂交给贫瘠之地的梅纳拉·沃伦德。"}},
[4963]={"地狱火的灵魂",{"带上地狱火绿宝石到凄凉之地去，用它捕获一个地狱火的灵魂。成功之后，将地狱火绿宝石和被禁锢的地狱火灵魂交给贫瘠之地的梅纳拉·沃伦德。"}},
[4964]={"达奥拉赫宝珠",{"等待梅纳拉·沃伦德完成达奥拉赫宝珠，然后再与她谈一谈。"}},
[4965]={"奥拉赫宝珠",{"与贫瘠之地的梅纳拉·沃伦德谈一谈。"}},
[4966]={"保护卡纳提·灰云",{"保护卡纳提·灰云免受半人马的袭击。"}},
[4967]={"奥拉赫宝珠",{"与贫瘠之地的梅纳拉·沃伦德谈一谈。"}},
[4968]={"奥拉赫宝珠",{"与贫瘠之地的梅纳拉·沃伦德谈一谈。"}},
[4969]={"奥拉赫宝珠",{"与贫瘠之地的梅纳拉·沃伦德谈一谈。"}},
[4970]={"霜刃豹的食物",{"收集5块碎齿熊肉和5块冰风奇美拉肉，把它们交给冬泉谷的雷沃·霜翼。"}},
[4971]={"时间问题",{"在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。","","杀掉15只时光寄生虫，然后将时光置换器还给西瘟疫之地安多哈尔旅店的克罗米。"}},
[4972]={"找回时间",{"在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。"}},
[4973]={"找回时间",{"在安多哈尔城的废墟里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。"}},
[4974]={"为部落而战！",{"去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。"}},
[4975]={"诺奥拉赫宝珠",{"等待梅纳拉·沃伦德完成诺奥拉赫宝珠，然后再与她谈一谈。"}},
[4976]={"归还净化过的宝珠",{"将净化过的地狱火宝珠交给贫瘠之地的梅纳拉·沃伦德。"}},
[4981]={"狡猾的比修",{"到黑石塔去查明比修的下落。"}},
[4982]={"比修的装置",{"找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。"}},
[4983]={"比修的侦察报告",{"把比修的侦查报告交给卡加斯的雷克斯洛特。"}},
[4984]={"大自然的苦楚",{"消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}},
[4985]={"大自然的苦楚",{"消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}},
[4986]={"雕文橡木枝",{"根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给达纳苏斯的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。"}},
[4987]={"雕文橡木枝",{"根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给雷霆崖的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。"}},
[5001]={"比修的装置",{"找到比修的装置并把它们还给她。祝你好运！"}},
[5002]={"给麦克斯韦尔的消息",{"到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。"}},
[5021]={"迟到总比不到好",{"这个女人的幽灵告诉你她要送出一只包裹。她说那只包裹就在她的马旁边。至于马在哪里或者包裹要送到哪里去，她却根本没有说。"}},
[5022]={"迟到总比不到好",{"与暴风城的皇家代理人巴瑟罗尔协商，查找到艾玛·费尔斯通的下落。通常在市政厅里都有一个人口普查官。"}},
[5023]={"迟到总比不到好",{"与幽暗城的皇家管理人巴哈乌斯协商，查找杰雷米亚·费尔斯通的下落。通常在公会注册处附近会有一个人口普查官。"}},
[5041]={"十字路口的补给品",{"找到十字路口的补给箱，把它还给贫瘠之地的索克。"}},
[5042]={"阿迦玛甘的力量",nil},
[5043]={"阿迦玛甘的敏捷",nil},
[5044]={"阿迦玛甘的智慧",nil},
[5045]={"高涨的士气",nil},
[5046]={"野猪之皮",nil},
[5047]={"皮普·急智，为您效劳！",{"与永望镇的玛雷弗斯·暗锤谈一谈。"}},
[5048]={"善良的艾玛",{"找到暴风城的艾玛并弄清她是否就是艾玛·费尔斯通。如果是的话，那么她可能想要拿到詹妮丝·费尔斯通给她的包裹。"}},
[5049]={"杰雷米亚的忧伤",{"在幽暗城找到杰雷米亚·派森并查明他是否就是你要找的杰雷米亚·费尔斯通。如果他是的话，那么他可能会想要拿到詹妮丝·费尔斯通寄给他的包裹。"}},
[5050]={"好运护符",{"把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。"}},
[5051]={"两半合一",{"在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。","","把好运护符交给西瘟疫之地费尔斯通农场的詹妮丝·费尔斯通。"}},
[5052]={"阿迦玛甘的血岩碎片",{"给陶拉祖营地的碎牙带去一块血岩碎片。","","如果你想要他赐予你阿迦玛甘的力量，就搜集更多的血岩碎片。"}},
[5054]={"碎齿熊尤西乌斯",{"永望镇的斯托姆·影蹄想要你去杀死尤西乌斯。"}},
[5055]={"冰风奇美拉布鲁米兰",{"永望镇的斯托姆·影蹄想要你去杀死布鲁米兰。"}},
[5056]={"希洛塔姆",{"永望镇的斯托姆·影蹄想要你去杀死希洛塔姆。"}},
[5057]={"以往的努力",{"把斯托姆·影蹄的徽记交给雷霆崖的梅洛·石蹄。"}},
[5058]={"达尔松夫人的日记",nil},
[5059]={"被锁起来的农夫",nil},
[5060]={"被锁起来的农夫",nil},
[5061]={"水栖形态",{"回到达纳苏斯，让玛斯雷·驭熊者看看你的海狮坠饰。"}},
[5062]={"神圣之火",{"收集10支火岩龙舌兰，然后去找雷霆崖长者高地的玛加萨·野性图腾。"}},
[5063]={"血色学者之帽",{"为了制造血色学者之帽，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，8块奥术水晶，5根魔化红线。","","另外你还必须支付50金币的制作费用。"}},
[5064]={"恐怖图腾的密信",{"在黑云峰拿到三封密信。"}},
[5065]={"失落的摩沙鲁石板",{"把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。"}},
[5066]={"战斗的号角：瘟疫之地！",{"找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"}},
[5067]={"阿卡纳护腿",{"为了制造阿卡纳护腿，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，5块奥金锭，5份莱斯·霜语的防腐液。","","另外你还必须支付50金币的制作费用。"}},
[5068]={"嗜血胸甲",{"为了制造嗜血胸甲，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，10根磨损的憎恶缝合线，5块奥金锭，5块暗影之皮。","","另外你还必须支付50金币的制作费用。"}},
[5081]={"麦克斯韦尔的任务",{"到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。"}},
[5082]={"冬泉熊怪的威胁",{"冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。"}},
[5083]={"冬泉火酒",{"将空的火酒瓶交给冬泉谷的多诺瓦·雪山。"}},
[5084]={"堕落熊怪",{"搜寻费伍德森林北部的死木熊怪的营帐，继续寻找线索。"}},
[5085]={"神秘的粘液",{"将你的发现报告给多诺瓦·雪山。"}},
[5086]={"剧毒之水",{"为冬泉谷的多诺瓦·雪山收集3份剧毒水滴。"}},
[5087]={"冬泉信使",{"找到冬泉信使，阻止他们向冬泉村运送物品。"}},
[5088]={"阿利卡拉",{"杀死阿利卡拉。把她的遗体和火岩粉交给白沙岗哨的莫特加·火鬃作为证明。"}},
[5089]={"达基萨斯将军的命令",{"把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。"}},
[5090]={"战斗的号角：瘟疫之地！",{"找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"}},
[5091]={"战斗的号角：瘟疫之地！",{"找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"}},
[5092]={"扫清道路",{"杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。","","然后向西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特复命。"}},
[5093]={"战斗的号角：瘟疫之地！",{"找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。"}},
[5094]={"战斗的号角：瘟疫之地！",{"找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。"}},
[5095]={"战斗的号角：瘟疫之地！",{"找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。"}},
[5096]={"误导血色十字军",{"到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。","","将亡灵天灾的战旗插在营地中，然后回到西瘟疫之地亡灵壁垒的高级执行官德灵顿那儿。"}},
[5097]={"标记哨塔",{"使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。","","在做完了标记之后，将信号火炬还给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。"}},
[5098]={"标记哨塔",{"使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。","","在做完了标记之后，将信号火炬还给西瘟疫之地亡灵壁垒的高级执行官德灵顿。"}},
[5102]={"达基萨斯将军之死",{"到黑石塔去杀掉达基萨斯将军，完成任务之后就回到麦克斯韦尔元帅那里复命。"}},
[5103]={"火热的死亡",{"世界上一定有人知道关于这副手套的事情，祝你好运！"}},
[5121]={"冬泉酋长",{"冬泉谷的多诺瓦·雪山要你去击败冬泉酋长。"}},
[5122]={"信仰奖章",nil},
[5123]={"最后一片",{"把潦草的日志交给冬泉谷的多诺瓦·雪山。"}},
[5124]={"炽热板甲护手",{"将6块魔化瑟银锭、2份火焰精华和4颗红宝石交给玛雷弗斯·暗锤。另外你还得把未淬火的板甲护手也交给他。"}},
[5125]={"奥里克斯的清算",nil},
[5126]={"罗拉克斯的故事",{"与罗拉克斯谈一谈，听听他要说什么。"}},
[5127]={"恶魔熔炉",{"到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。","","你还必须找到未铸造的符文覆饰胸甲。","","将穿魂长矛和未铸造的符文覆饰胸甲都交给冬泉谷的罗拉克斯。"}},
[5128]={"熊怪酋长的话",{"将潦草的日志交给费伍德森林南部的科雷克·望天。"}},
[5141]={"龙鳞制皮",{"将2套硬化蝎壳胸甲、2套硬化蝎壳手套和10片龙鳞交给艾萨拉的彼得·加林。","","完成这项任务之后，你就可以学到龙鳞制皮技术了。","","同时，你也将永远无法学习元素制皮技术和部族制皮技术，在决定之前先考虑清楚。"}},
[5142]={"小帕米拉",{"找到帕米拉·雷德帕斯。"}},
[5143]={"部族制皮",{"将1件蛮皮外衣和1件蛮皮头盔交给菲拉斯的凯雷希亚·猎月。","","完成这项任务之后，你就可以学到部族制皮技术了。","","同时，你也将永远无法学习元素制皮技术和龙鳞制皮技术，在决定之前先考虑清楚。"}},
[5144]={"元素制皮",{"将2个火焰之心、2个纯水之球、2个大地之核和2个风之气息交给灼热峡谷的萨拉·坦尼。","","一旦你完成这项任务，就可以开始学习元素制皮技艺了。","","同时，你也就无法再学习龙鳞制皮和部落制皮了，在你决定之前要考虑清楚。"}},
[5145]={"龙鳞制皮",{"将2套硬化蝎壳胸甲、2套硬化蝎壳手套和10片龙鳞交给荒芜之地的索卡夫·龙眼。","","完成这项任务之后，你就可以学到龙鳞制皮技术了。","","同时，你也将永远无法学习元素制皮技术和部族制皮技术，在决定之前先考虑清楚。"}},
[5146]={"元素制皮",{"将2个火焰之心、2个纯水之球、2个大地之核和2个风之气息交给阿拉希山脉的布鲁姆·白蹄。","","一旦你完成这项任务，就可以开始学习元素制皮技艺了。","","同时，你也就无法再学习龙鳞制皮和部落制皮了，在你决定之前要考虑清楚。"}},
[5147]={"通缉：阿纳克·恐怖图腾",{"杀死阿纳克·恐怖图腾，并向乱风岗的峭壁卫兵图林·长角出示证据。"}},
[5148]={"部族制皮",{"将1件蛮皮外衣和1件蛮皮头盔交给荆棘谷的瑟伊布。","","完成这项任务之后，你就可以学到部族制皮技术了。","","同时，你也将永远无法学习元素制皮技术和龙鳞制皮技术，在决定之前先考虑清楚。"}},
[5149]={"帕米拉的洋娃娃",{"找到帕米拉的洋娃娃。"}},
[5150]={"达丹加饿了！",nil},
[5151]={"超适应齿轮",{"杀了那头野兽，把超适应齿轮和钥匙交给维兹罗。"}},
[5152]={"玛莱恩姑妈",{"与安多哈尔废墟南边的玛莱恩谈一谈。"}},
[5153]={"古怪的历史学家",{"把约瑟夫的结婚戒指交给安多哈尔的克罗米。"}},
[5154]={"达隆郡的历史",{"把《达隆郡的历史》交给安多哈尔的克罗米。"}},
[5155]={"加德纳尔的势力",{"到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。"}},
[5156]={"验证腐蚀",{"杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。"}},
[5157]={"收集堕落之水",{"把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。"}},
[5158]={"水之魂的帮助",{"把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。"}},
[5159]={"净化过的水",{"把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。"}},
[5160]={"监护者",{"到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。"}},
[5161]={"蓝龙之怒",{"要是你想继续的话，就与哈尔琳谈一谈。"}},
[5162]={"蓝龙之怒",{"与瘟疫之地的耶兹巴交谈。他居住在安多哈尔。"}},
[5163]={"雪怪计划！",{"带着乌米的机械雪人去吓唬她的朋友：","","永望镇的莱加奇（冬泉谷）、加基森的斯普琳科（塔纳利斯），还有马绍尔营地的奎克希尔（安戈洛环形山）。","","当你完成任务之后，把机械雪人还给乌米。"}},
[5164]={"游荡者目录",{"阅读游荡者目录。"}},
[5165]={"熄灭火焰",{"使用净化过的月亮井水熄灭暗影堡内部的四座火盆的火焰，从而破除其保护效果，然后向翡翠圣地的格雷塔·苔蹄复命。"}},
[5166]={"多彩巨龙胸甲",{"为了铸造多彩巨龙胸甲，你必须把以下材料交给雕刻者耶兹巴：","","1块多彩龙鳞。","","10块闪亮的彩色龙鳞。","","10份英雄之血。","","10块磨损的憎恶缝合线。"}},
[5167]={"多彩挑战者腿甲",{"为了铸造多彩挑战者腿甲，你必须把以下材料交给雕刻者耶兹巴：","","1块多彩龙鳞。","","10块闪亮的彩色龙鳞。","","10份英雄之血。","","5块暗影之皮。"}},
[5168]={"达隆郡的英雄",{"把达维的圣契和雷德帕斯之盾交给卡林·雷德帕斯。"}},
[5181]={"达隆郡的恶魔",{"将霍古斯的颅骨和马杜克的破碎之剑交给圣光之愿礼拜堂的卡林·雷德帕斯。"}},
[5201]={"冬泉熊怪的侵扰",{"雷沃·霜翼要你去杀死5个冬泉萨满祭司和5个冬泉巨熊怪。"}},
[5202]={"奇怪的红钥匙",{"搜寻加德纳尔，找出血红钥匙的用途。"}},
[5203]={"逃出加德纳尔",{"护送亚科纳琳到莱弗治和她的装备所在的地方，然后保护她逃离暗影堡。之后，在费伍德森林找杰希尔·月弓，并告诉她刚才发生的事情。"}},
[5204]={"光明的惩戒",{"回到加德纳尔杀了魅魔拉凯雅，然后找到特雷·莱弗治的残骸。"}},
[5206]={"达隆郡的掠夺者",{"把5个共鸣颅骨和神秘水晶交给东瘟疫之地的卡林·雷德帕斯。"}},
[5210]={"卡林·雷德帕斯",{"将《达隆镇全史》交给东瘟疫之地的卡林·雷德帕斯。"}},
[5211]={"达隆郡的保卫者",{"释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。"}},
[5212]={"血肉不会撒谎",{"从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……"}},
[5213]={"活跃的探子",{"到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。"}},
[5214]={"了不起的艾兹拉·格里姆",{"找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。"}},
[5215]={"瘟疫之锅",{"与西瘟疫之地冰风岗的高阶牧师玛多妮尔谈一谈。"}},
[5216]={"目标：费尔斯通农场",{"到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5217]={"返回冰风岗",{"把费尔斯通农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
[5218]={"费尔斯通农场的瘟疫之锅",nil},
[5219]={"目标：达尔松之泪",{"到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5220]={"返回冰风岗",{"把达尔松之泪的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
[5221]={"达尔松之泪的瘟疫之锅",nil},
[5222]={"目标：嚎哭鬼屋",{"到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5223]={"返回冰风岗",{"把嚎哭鬼屋的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
[5224]={"嚎哭鬼屋的瘟疫之锅",nil},
[5225]={"目标：盖罗恩农场",{"到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5226]={"返回冰风岗",{"把盖罗恩农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
[5227]={"盖罗恩农场的瘟疫之锅",nil},
[5228]={"瘟疫之锅",{"与西瘟疫之地亡灵壁垒的暗影牧师范蒂丝谈一谈。"}},
[5229]={"目标：费尔斯通农场",{"到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5230]={"返回亡灵壁垒",{"把费尔斯通农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}},
