[5235]={"目标：盖罗恩农场",{"到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5236]={"返回亡灵壁垒",{"把盖罗恩农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}},
[5237]={"任务完成！",nil},
[5238]={"任务完成！",nil},
[5241]={"卡林叔叔",{"找到卡林·瑞德巴思。"}},
[5242]={"最终一击",{"杀掉米莱恩和萨莉亚，并把暗影领主费尔丹的头颅交给费伍德森林的格雷塔·苔蹄。"}},
[5243]={"神圣之屋",{"到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。"}},
[5244]={"凯斯利尔废墟",{"与坠星村的加隆·石矛谈一谈。"}},
[5245]={"凯斯利尔的怨灵",{"使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。"}},
[5246]={"历史的残片",{"在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。"}},
[5247]={"历史的残片",{"给东瘟疫之地的奥萝拉带去一块魔化瑟银锭、5块恢复水晶，以及一小瓶恐怖之水。"}},
[5248]={"记忆的折磨",{"把辛玛洛水晶带回冬泉谷的凯斯利尔湖，在那里寻找一个会与你讲话的上层精灵。"}},
[5249]={"前往冬泉谷！",{"找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。"}},
[5250]={"坠星村",{"找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。"}},
[5251]={"档案管理员",{"在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。"}},
[5252]={"悔恨的上层精灵",{"和坠星村的维恩德·夜风谈一谈，了解到辛玛洛水晶所在的位置。"}},
[5253]={"辛玛洛水晶",{"将辛玛洛水晶送到达纳苏斯的大德鲁伊范达尔·鹿盔那里。"}},
[5261]={"伊根·派特斯金纳",{"与伊根·派特斯金纳谈一谈。"}},
[5262]={"可怕的真相",{"将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。"}},
[5263]={"超越",{"到斯坦索姆去杀掉瑞文戴尔男爵，把他的头颅交给尼古拉斯·瑟伦霍夫公爵。"}},
[5264]={"玛克斯韦尔·泰罗索斯男爵",{"和玛克斯韦尔·泰罗索斯男爵谈一谈。他就在教堂里面。"}},
[5265]={"银色黎明宝箱",{"打开银色黎明宝箱，拿取你应得的奖励。"}},
[5281]={"永不安息的灵魂",{"找到埃根。你只知道他在斯坦索姆附近。"}},
[5282]={"永不安息的灵魂",{"对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！","","解放15个永不安息的灵魂，然后回到埃根那里去。"}},
[5283]={"铸造护甲的艺术",{"要想成为一名护甲铸造师的话，你必须将下列物品交给格鲁努斯：4顶精制秘银头盔、2双精制秘银战靴和1副精制秘银胸甲。"}},
[5284]={"武器铸造师之道",{"要想成为一名武器铸造师的话，你必须将下列物品交给埃隆努斯·冷钢：4把月钢宽剑、4把巨型铁斧、2把秘银重斧和2把巨型黑色锤。"}},
[5301]={"铸造护甲的艺术",{"要想成为一名护甲铸造师的话，你必须将下列物品交给奥克索斯：4顶精制秘银头盔、2双精制秘银战靴和1副精制秘银胸甲。"}},
[5302]={"武器铸造师之道",{"要想成为一名武器铸造师的话，你必须将下列物品交给伯古什：4把月钢宽剑、4把巨型铁斧、2把秘银重斧和2把巨型黑色锤。"}},
[5305]={"甜美的平静",{"到斯坦索姆去杀死红衣铸锤师。将红衣铸锤师的围裙交给莉莉丝。"}},
[5306]={"沃什加斯的菊石",{"到黑石塔去杀死暗影猎手沃什加斯，将沃什加斯的菊石交给基尔拉姆。"}},
[5307]={"腐蚀",{"在斯坦索姆找到黑衣守卫铸剑师，然后杀死他。将黑色卫士徽记交给亡灵杀手瑟里尔。"}},
[5321]={"昏昏欲睡",{"护送克罗尼亚·恒影到灰谷迈斯特拉岗哨的利拉迪斯·月河那里去。"}},
[5341]={"巴罗夫家族的宝藏",{"到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。"}},
[5342]={"巴罗夫的继承人",{"到冰风岗——联盟的领地——去暗杀维尔顿·巴罗夫。把他的脑袋交给阿莱克斯·巴罗夫。","","要多加小心，联盟也许对维尔顿实施了严密的保护。"}},
[5343]={"巴罗夫家族的宝藏",{"到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。"}},
[5344]={"巴罗夫的继承人",{"去亡灵壁垒——部落的领地——去暗杀阿莱克斯·巴罗夫。把他的脑袋交给维尔顿·巴罗夫。","","要小心，部落也许对阿莱克斯实施了严密的保护。"}},
[5361]={"兄弟",{"将峭壁卫兵图林·长角的报告交给凄凉之地幽灵岗哨的纳塔卡·长角。"}},
[5381]={"埃鲁索斯之手",{"在雷斧堡垒中找到恶魔之盒，把它和恶魔之锄一起交给葬影村的泰迦·慧鬃。"}},
[5382]={"瑟尔林·卡斯迪诺夫教授",{"在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。"}},
[5384]={"传令官基尔图诺斯",{"带着无辜者之血回到通灵学院，将它放在门廊的火盆下面，基尔图诺斯会前来吞噬你的灵魂。","","勇敢地战斗吧，不要退缩！杀死基尔图诺斯，然后回到艾瓦·萨克霍夫那儿。"}},
[5385]={"特雷·莱弗治的残骸",{"将特雷·莱弗治的残骸交给费伍德森林的杰希尔·月弓。"}},
[5386]={"食鱼度日",{"与葬影村的吉纳泽林谈话，然后将2条血肚鱼交给纳塔卡·长角。"}},
[5401]={"银色黎明委任徽章",nil},
[5402]={"爪牙的天灾石",nil},
[5403]={"侵略者的天灾石",nil},
[5404]={"堕落者的天灾石",nil},
