[5535]={"永不安息的灵魂",{"杀掉6个上层精灵的幻影和6个上层精灵鬼巫，然后向艾萨拉的罗哈图复命。"}},
[5536]={"充满仇恨的土地",{"杀掉6个哈达尔萨特、2个哈达尔欺诈者和2个哈达尔魔仆，然后向灰谷与艾萨拉交界处的罗哈图复命。"}},
