[5544]={"腐肉虫",{"在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}},
[5545]={"木材危机",{"收集8捆木材，把它们交给东谷伐木场的管理员莱琳。"}},
[5561]={"诱捕科多兽",{"将科多兽诱引器和5头被驯服的科多兽交给瑟卡布斯库的营地中的斯米德·瑟卡布斯库。"}},
[5581]={"燃烧军团的传送门",{"放逐6个玛诺洛克集会所的传送门，然后回到葬影村的泰迦·慧鬃那里。"}},
