[5721]={"达隆郡的战斗",{"将遗物包裹放在达隆郡的广场中。","","在霍古斯死亡之前，达维必须存活。","","在雷德帕斯队长堕落之前保证他存活。","","击败堕落的雷德帕斯。","","当约瑟夫·雷德帕斯出现在广场中时，与他的灵魂进行交谈，然后回到帕米拉的家中去找帕米拉。"}},
[5722]={"寻找背包",{"在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。"}},
[5723]={"试探敌人",{"在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。"}},
[5724]={"归还背包",{"将恐怖图腾背包交给雷霆崖的拉哈罗。"}},
[5725]={"毁灭之力",{"将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。"}},
[5726]={"隐藏的敌人",{"将军官的徽章交给奥格瑞玛的萨尔。"}},
[5727]={"隐藏的敌人",{"将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。"}},
[5728]={"隐藏的敌人",{"杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。"}},
[5729]={"隐藏的敌人",{"与奥格瑞玛的尼尔鲁·火刃谈一谈。"}},
[5730]={"隐藏的敌人",{"与奥格瑞玛的萨尔谈一谈，告诉他你了解到的东西。"}},
[5741]={"圣光节杖",{"拿到圣光节杖，并将它交给艾瑟雷索塔里的阿佐尔·奥达蒙特。"}},
[5742]={"救赎",{"听听提里奥·弗丁要说什么。"}},
[5761]={"饥饿者塔拉加曼",{"进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。"}},
[5762]={"赫米特·奈辛瓦里",{"将克拉维尔的箱子送到荆棘谷的赫米特·奈辛瓦里那里。"}},
[5763]={"荆棘谷狩猎",{"将鲁恩的科多兽角送到荆棘谷的赫米特·奈辛瓦里那里。"}},
[5781]={"遗忘的记忆",{"到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。"}},
[5801]={"火羽山",{"把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。","","把未完工的骷髅钥匙交给西瘟疫之地冰风岗的化学家阿尔比顿。"}},
[5802]={"火羽山",{"把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。","","把未完工的骷髅钥匙交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。"}},
[5803]={"阿拉基的圣甲虫",{"杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地冰风岗的化学家阿尔比顿。"}},
[5804]={"阿拉基的圣甲虫",{"杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。"}},
[5821]={"雇佣保镖",{"护送基泽尔顿商队通过科卡尔半人马村，然后与瑟卡布斯库的营地中的斯米德谈话以领取你的奖赏。"}},
[5845]={"失落的荣耀",{"到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。"}},
[5846]={"爱与家庭",{"到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。"}},
[5848]={"爱与家庭",{"到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。","","把这幅画还给提里奥·弗丁。"}},
[5861]={"寻找麦兰达",{"到瘟疫之地南部的乌瑟尔之墓去，将提里奥的礼物交给巫女麦兰达。"}},
[5862]={"血色幻象",{"和巫女麦兰达交谈以获得血色幻象的效果。在血色幻象的掩护下深入壁炉谷，将提里奥的礼物交给大领主泰兰·弗丁。","","壁炉谷在北方，泰兰应该在玛登霍尔德城堡里面。"}},
