[5924]={"响应召唤",{"与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。"}},
[5925]={"响应召唤",{"与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。"}},
[5926]={"响应召唤",{"与雷霆崖长者高地上的图拉克·符文图腾谈一谈。"}},
[5927]={"响应召唤",{"与雷霆崖长者高地上的图拉克·符文图腾谈一谈。"}},
[5928]={"响应召唤",{"与雷霆崖长者高地上的图拉克·符文图腾谈一谈。"}},
[5929]={"巨熊之灵",{"到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。"}},
[5930]={"巨熊之灵",{"到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。"}},
[5931]={"返回达纳苏斯",{"回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。"}},
[5932]={"返回雷霆崖",{"回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。"}},
[5941]={"返回克罗米身边",{"将一包遗物交给安多哈尔的克罗米。"}},
[5942]={"隐藏的宝藏",{"用约瑟夫的钥匙打开约瑟夫的箱子。"}},
[5943]={"基泽尔顿车队",{"护送基泽尔顿车队通过玛诺洛克集会所，然后与瑟卡布斯库的营地的斯米德谈一谈，领取你的奖励。"}},
[5944]={"在梦中",{"护送泰兰·弗丁走出壁炉谷。"}},
[5961]={"女妖之王的勇士",{"与东瘟疫之地的纳萨诺斯·凋零者谈一谈。据说他居住在玛瑞斯农场。"}},
[5981]={"狂暴的巨人",{"雷沃·霜翼要你去杀死4个霜槌巨人和4个霜槌保卫者。"}},
[6001]={"身心之力",{"使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。","","任务完成之后，与达纳苏斯的玛斯雷·驭熊者谈一谈。"}},
[6002]={"身心之力",{"使用莫高雷与贫瘠之地交界处的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。","","任务完成之后，与雷霆崖的图拉克·符文图腾谈一谈。"}},
[6004]={"未竟的事业",{"杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。"}},
[6021]={"流亡者塞达尔",{"将塞达尔的头颅交给圣光之愿礼拜堂的护理者奥林。"}},
[6022]={"杀戮的理由",{"到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。"}},
[6023]={"未完的任务",{"杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。"}},
[6024]={"哈米亚的请求",{"杀了渗透者哈米亚，用他的钥匙开启墓室后的一堆泥土。"}},
[6025]={"未完的任务",{"进入壁炉谷并找一处高地，你可以在那里观察整个城镇并估算血色十字军的兵力，然后向西瘟疫之地的科尔斯塔·迪普沙东回报。"}},
[6026]={"狮子大开口",{"烟鬼拉鲁恩要你拿来2块瑟银锭、1根金棒、8颗高爆炸弹和8个不牢固的扳机。","","你需要找铁匠和工程学技师帮忙制作这些东西。"}},
[6027]={"上古之书",{"拿到上古之书，将其交给艾瑟雷索塔中的阿佐尔·奥达蒙特。"}},
[6028]={"永望镇报告",{"把永望镇报告送给西瘟疫地冰风岗的银色黎明军官普尔哈特。"}},
[6029]={"永望镇报告",{"把永望镇报告送给西瘟疫地亡灵壁垒的银色黎明军官加鲁什。"}},
[6030]={"尼古拉斯·瑟伦霍夫公爵",{"将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。"}},
[6031]={"符文布",{"把30块符文布交给木喉要塞的梅罗什。"}},
[6032]={"神圣的月布",{"把2块月布交给木喉要塞的梅罗什。"}},
[6041]={"烟鬼的炸药",{"到圣光之愿礼拜堂西北方的病木林去。在那些有爆炸标记的建筑物中对爆炸标记使用烟鬼的特殊混合物，以此来摧毁8座亡灵天灾建筑。烟鬼已经给通灵塔和屠宰房做上了标记。","","一旦你放置好炸弹，就离那些建筑物远一些，然后尽情欣赏你的杰作吧。","","顺便说一句，烟鬼的特殊混合物相当不稳定……"}},
[6042]={"讨厌的蝙蝠",{"杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。"}},
[6061]={"驯服野兽",{"使用驯兽棒驯服成年陆行鸟。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。"}},
[6062]={"驯服野兽",{"使用驯兽棒驯服可怕的杂斑野猪。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。"}},
[6063]={"驯服野兽",{"使用驯兽棒驯服树林潜伏者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。"}},
[6064]={"驯服野兽",{"使用驯兽棒驯服大型峭壁野猪。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。"}},
[6065]={"猎人之道",{"与血蹄村的雅文·刺鬃谈一谈。"}},
