[6081]={"训练野兽",{"与奥格瑞玛的奥玛克谈一谈。"}},
[6082]={"驯服野兽",{"使用驯兽棒驯服硬甲蝎。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。"}},
[6083]={"驯服野兽",{"使用驯兽棒驯服海浪蟹。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。"}},
[6084]={"驯服野兽",{"使用驯兽棒驯服雪豹。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。"}},
[6085]={"驯服野兽",{"使用驯服兽棒驯服一头冰爪熊。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。"}},
[6086]={"训练野兽",{"与铁炉堡的贝莉亚·雷岩谈一谈。"}},
[6087]={"驯服野兽",{"使用驯兽棒驯服一只草原捕食者。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。"}},
[6088]={"驯服野兽",{"使用驯兽棒驯服一只猛鹫。练习你的技能，然后将驯服法杖交还给血蹄村的雅文·刺鬃。"}},
[6089]={"训练野兽",{"与雷霆崖猎人高地的浩特·雷角谈一谈。"}},
[6101]={"驯服野兽",{"使用驯兽棒驯服一只夜刃捕食者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。"}},
[6102]={"驯服野兽",{"使用驯兽棒驯服一只巨翼恶枭。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。"}},
[6103]={"训练野兽",{"与达纳苏斯塞纳里奥区的祖卡斯特谈一谈。"}},
[6121]={"新的课程",{"到月光林地去，与永夜港的德迪利特·星焰谈一谈。"}},
[6122]={"毒水之源",{"使用空的峭壁之泉取样器在瀑布洞口获得水样。","","将盛满的峭壁之泉取样器送到黑海岸奥伯丁的奥兰达利亚·夜歌那里。"}},
[6123]={"收集解药",{"收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。"}},
[6124]={"消除疾病",{"对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。"}},
[6125]={"解毒之术",{"回到达纳苏斯塞纳里奥区的玛斯雷·驭熊者那里。"}},
[6126]={"新的课程",{"到月光林地去，与永夜港的德迪利特·星焰谈一谈。"}},
[6127]={"毒水之源",{"使用空的鬼雾峰取样器在山顶取水样。","","将盛满的鬼雾峰取样器送到贫瘠之地十字路口的图加·符文图腾那里。"}},
[6128]={"收集解药",{"收集5个地根草和5个科多兽角，把它们交给十字路口的图加·符文图腾，这样他就可以制作解药了。"}},
[6129]={"消除疾病",{"对贫瘠之地北部的10只生病的瞪羚使用动物医疗药膏，以此来治疗它们。在穿过十字路口的那条东西走向的大路北面到处都是生病的蹬羚。"}},
[6130]={"解毒之术",{"回到雷霆崖长者高地的图拉克·符文图腾那里。"}},
[6132]={"救我出去！",{"护送梅丽萨，然后与科多兽坟场的霍恩尼兹谈一谈。"}},
[6133]={"游侠之王的命令",{"到东瘟疫之地的北方边界去找回奎尔萨拉斯名册，这件物品在奎尔林斯小屋的某处。","","另外你还必须杀掉8个游侠、8个巡路者和8个护林者。"}},
[6134]={"幽灵电浆",{"把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。"}},
[6135]={"暗翼蝠",{"找到暗翼蝠并杀掉它。从尸体上取下一块暗翼蝠的皮，并把它交给纳萨诺斯·凋零者。","","据说暗翼蝠游荡在玛瑞斯农场北面的荒原上。"}},
[6136]={"肥大的食腐虫",{"找到东瘟疫之地北方荒原中的淤血虫并消灭它。任务完成之后，向纳萨诺斯·凋零者复命。"}},
[6141]={"安东修士",{"与凄凉之地的安东修士谈一谈。"}},
[6142]={"蚌肉鱼饵",{"找到10块软壳蚌肉，把它们交给葬影村的麦拉斯。"}},
[6143]={"另一种鱼",{"杀死7个滑刃侍从、7个滑刃纳迦，以及5个滑刃巫师，然后与葬影村的杜泽加尔谈谈。"}},
[6144]={"上级的命令",{"到幽暗城去与瓦里玛萨斯谈一谈。"}},
[6145]={"红衣信使",{"返回东瘟疫之地，找到并杀死红衣信使，拿到大十字军的命令。","","把命令交给纳萨诺斯·凋零者，并等待进一步的指示。"}},
[6146]={"纳萨诺斯的计谋",{"到玛瑞斯农场东南方的提尔之手去，抵达那里之后就咬一口烂苹果。在血色十字军伪装的掩护下，把大十字军的命令交给十字军领主瓦德玛尔。"}},
[6147]={"向纳萨诺斯复命",{"带着新情报返回纳萨诺斯·凋零者那里。"}},
[6148]={"血色十字军圣者，德米提雅",{"血色十字军正在从提尔之手到斯坦索姆的路上巡逻，你可以在巡逻队中找到圣者德米提雅和她的随从，找到并杀死她。如果你成功了，就回到纳萨诺斯·凋零者那里去复命。"}},
[6161]={"拉克摩尔的财宝！",{"找到拉克摩尔的银钥匙和金钥匙。找到并打开拉克摩尔的箱子。"}},
[6162]={"最后一战",{"杀死主宰洛尔，把他的爪子交给费伍德森林血毒岗哨的德雷卡苏。"}},
[6163]={"吞咽者拉姆斯登",{"到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的头颅交给纳萨诺斯。"}},
[6164]={"奥古斯图斯的收据册",{"把奥古斯图斯的收据册交给恶蛛隧道中的被感动的奥古斯图斯。"}},
[6181]={"快递消息",{"将刘易斯的便笺交给狮鹫管理员索尔。"}},
[6182]={"第一个和最后一个",{"与暴风城的马迪亚斯·肖尔谈一谈，他住在旧城区的兵营里。"}},
[6183]={"逝者的荣耀",{"如果你愿意接这个任务，就再和马迪亚斯·肖尔谈一谈。"}},
[6184]={"弗林特·沙多摩尔",{"到西瘟疫之地的冰风岗去跟弗林特·沙多摩尔会面。"}},
[6185]={"东部的瘟疫",{"搜寻东瘟疫之地，寻找“凋零者”的线索以及失踪的军情七处密探。如果你找到任何军情七处徽章，就把它们交给冰风岗的弗林特·沙多摩尔。"}},
[6186]={"凋零者",{"回到暴风城，将纳萨诺斯·玛瑞斯的下落报告给伯瓦尔·弗塔根公爵。"}},
[6187]={"重铸秩序",{"组织一支部队，然后到东瘟疫之地去。向纳萨诺斯·凋零者和任何敢于保护他的部落成员发起攻击。","","你要倾尽全力，<name>。部落会不惜一切代价保护他们的游侠领主。"}},
[6261]={"杜加尔·朗德瑞克",{"将奥斯瑞克的箱子交给狮鹫管理员杜加尔·朗德瑞克。"}},
[6281]={"赶赴暴风城",{"从狮鹫管理员索尔那里租用一头狮鹫，然后把刘易斯的便笺交给暴风城的奥斯瑞克·斯图恩。"}},
[6282]={"鹰身人的威胁",{"烈日石居的马格兰要你去杀掉7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。"}},
[6283]={"血怒一族",{"烈日石居的马格兰要你去杀掉血怒撕裂者，然后把她的遗体带回来作为证据。"}},
[6284]={"贝瑟莱斯",{"杀掉贝瑟莱斯，然后把贝瑟莱斯的牙齿交给烈日石居的马格兰。"}},
[6285]={"返回西部荒野",{"从狮鹫管理员杜加尔·朗德瑞克那里租用一头狮鹫飞到哨兵岭，然后将奥斯瑞克的箱子交给哨兵岭的刘易斯。"}},
[6301]={"生生不息",{"烈日石居的塔姆拉·荒原想让你去收集10枚盖亚之种。"}},
[6321]={"瑟伯切尔的补给",{"将博迪瑞格的订单交给卡洛斯·拉佐克。"}},
[6322]={"迈克尔·加勒特",{"将高顿的箱子交给迈克尔·加勒特。"}},
[6323]={"飞往幽暗城",{"从蝙蝠管理员卡洛斯·拉佐克那里租一只蝙蝠飞往幽暗城，然后将博迪瑞格的订单交给幽暗城里的高顿·温德哈姆。"}},
[6324]={"向博迪瑞格回报",{"从蝙蝠管理员迈克尔·加勒特那儿租一只蝙蝠飞往瑟伯切尔，然后将高顿的箱子交给瑟伯切尔的亡灵卫兵博迪瑞格。"}},
[6341]={"泰达希尔的渔业",{"将尼莎的货物交给维斯派塔斯。"}},
[6342]={"飞往奥伯丁",{"从角鹰兽管理员维斯派塔斯那里租用一只角鹰兽飞到奥伯丁，然后将尼莎的货物交给莱尔德。"}},
[6343]={"飞回泰达希尔",{"将莱尔德的回信交给尼莎·影歌。"}},
[6344]={"尼莎·影歌",{"与尼莎·影歌谈一谈。"}},
[6361]={"一捆兽皮",{"带着兽皮去找十字路口的迪弗拉克。"}},
[6362]={"飞往雷霆崖",{"从双足飞龙管理员迪弗拉克那里租一只驭风者飞往雷霆崖，然后将这捆兽皮交给雷霆崖的安哈努。"}},
[6363]={"双足飞龙管理员塔尔",{"将安哈努的皮货交给雷霆崖的塔尔。"}},
[6364]={"向加翰回复",{"从双足飞龙管理员塔尔那里租用一头飞往十字路口的双足飞龙，并把安哈努的皮货交给加翰·鹰翼。"}},
[6365]={"送往奥格瑞玛的肉",{"把扎尔夫的肉品交给十字路口的迪弗拉克。"}},
[6381]={"新的生命",{"将10枚盖亚之种种植在盖亚土堆中，然后与烈日石居的塔姆拉谈一谈。"}},
[6382]={"灰谷狩猎",{"与灰谷碎木哨岗的塞娜尼·雷心谈一谈。"}},
[6383]={"灰谷狩猎",nil},
[6384]={"飞往奥格瑞玛",{"从双足飞龙管理员迪弗拉克那里租一只驭风者飞往奥格瑞玛，然后将扎尔夫的肉品交给奥格瑞玛的格雷什卡。"}},
[6385]={"双足飞龙管理员多拉斯",{"将格雷什卡的信交给奥格瑞玛的多拉斯。"}},
[6386]={"返回十字路口",{"从驭风者管理员多拉斯那里雇一只驭风者前往十字路口，然后将格雷什卡的信交给十字路口的扎尔夫。"}},
[6387]={"荣誉学员",{"将布洛克的名单交给塞尔萨玛的索格拉姆·伯雷森。"}},
[6388]={"格莱斯·瑟登",{"将荣誉锄交给铁炉堡的格莱斯·瑟登。"}},
[6389]={"瘟疫与你",{"使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向西瘟疫之地冰风岗的纳萨尼尔·杜马报告。"}},
[6390]={"瘟疫与你",{"使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向提瑞斯法林地亡灵壁垒的米克·莱文报告。"}},
[6391]={"飞往铁炉堡",{"从狮鹫管理员索格拉姆·伯雷森那里租一只狮鹫飞往铁炉堡，然后将布洛克的名单交给铁炉堡的高尼尔·石趾。"}},
[6392]={"向布洛克回复",{"从狮鹫管理员格莱斯·瑟登那里租用一头飞往塞尔萨玛的狮鹫，然后将荣誉锄交给塞尔萨玛的布洛克·寻石者。"}},
[6393]={"元素战争",{"将10块焚火余烬交给烈日石居的苏纳曼。"}},
[6394]={"塔兹利尔的镐",{"将塔兹利尔的镐还给塔兹利尔。"}},
[6395]={"玛拉的遗愿",{"将塞缪尔·菲普斯的遗骸带到玛拉的坟墓去，然后回到新兵艾尔雷斯那里。"}},
[6401]={"卡雅还活着",{"把这个好消息告诉烈日石居的塔姆拉·荒原。"}},
[6402]={"集合在暴风城",{"前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。"}},
[6403]={"潜藏者",{"跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！"}},
[6421]={"滚岩峡谷",{"深入滚岩峡谷的洞穴中，为烈日石居的摩罗加尔取回10块共鸣水晶以供研究。"}},
[6441]={"萨特之角",{"为碎木哨岗的皮克希尔收集16只萨特的角。"}},
[6442]={"佐拉姆海岸的纳迦",{"将20颗怒尾纳迦的头颅交给佐拉姆海岸的玛鲁凯。"}},
[6461]={"盗窃的蜘蛛",{"玛拉卡金的辛吉拉要求你杀死10只深苔爬行者和7只深苔毒蜘蛛。"}},
[6462]={"巨魔符咒",{"将8个巨魔符咒交给佐拉姆加前哨站的米苏瓦。"}},
[6481]={"土灵的觉醒",{"使用魔化共鸣水晶打开共鸣桶，然后杀死高戈罗克。将这个消息告诉摩罗加尔，并把魔化共鸣水晶还给他。"}},
[6482]={"鲁尔的自由",{"护送鲁尔，然后与慰藉之林的雅玛·雪蹄谈一谈。"}},
[6501]={"巨龙之眼",{"你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。"}},
[6502]={"龙火护符",{"你必须从达基萨斯将军身上取回黑龙勇士之血，你可以在黑石塔的晋升大厅后面的房间里找到他。"}},
[6503]={"灰谷先驱者",{"杀掉9个灰谷先驱者，然后回到碎木哨岗的库莱比那里。"}},
[6504]={"丢失的书页",{"找到丢失的12页伐木机操作指南，把它们合并为第1、2、3章。然后带着这些书页回到碎木岗哨去找古尔达·怒痕。"}},
[6521]={"邪恶的盟友",{"把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。"}},
[6522]={"邪恶的盟友",{"把小卷轴交给幽暗城的瓦里玛萨斯。"}},
[6523]={"保护卡雅",{"护送卡雅·扁蹄回到阿帕拉耶营地，然后到石爪山东南边界附近的玛卡巴·扁蹄那里去复命。"}},
[6541]={"向卡德拉克报到",{"到贫瘠之地北部的卡德拉克那里报到。"}},
[6542]={"向卡德拉克报到",{"到贫瘠之地北部的卡德拉克那里报到。"}},
[6543]={"战歌报告",{"打开报告集，把战歌报告交给战歌斥候、战歌信使和战歌侦查骑兵。把他们的最新报告交给贫瘠之地北部哨塔上的卡德拉克。"}},
[6544]={"托雷克的突袭",{"保护在银翼哨站与杜瑞尔·月火作战的托雷克，然后向慰籍之林的埃尔托格·怒齿汇报胜利的消息。"}},
[6545]={"战歌信使的报告",nil},
[6546]={"战歌侍从的报告",nil},
[6547]={"战歌斥候的报告",nil},
[6548]={"为我的村庄复仇",{"杀掉8个恐怖图腾恶徒和6个恐怖图腾佣兵，然后向石爪山脉东南边界处的玛卡巴·扁蹄复命。"}},
[6561]={"黑暗深渊中的邪恶",{"把梦游者克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。"}},
[6562]={"帮助耶努萨克雷",{"与灰谷的耶努萨克雷谈一谈。"}},
[6563]={"阿库麦尔水晶",{"收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。"}},
[6564]={"上古之神的仆从",{"把潮湿的便笺交给灰谷的耶努萨克雷。"}},
[6565]={"上古之神的仆从",{"杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。"}},
[6566]={"风吹来的消息",{"听萨尔讲话。"}},
[6567]={"部落的勇士",{"按照酋长的指示找到雷克萨。他在石爪山和菲拉斯之间的凄凉之地游荡。"}},
[6568]={"雷克萨的证明",{"把雷克萨的证明交给西瘟疫之地的巫女麦兰达。"}},
[6569]={"黑龙幻象",{"到黑石塔去收集20颗黑色龙人的眼球，完成任务之后回到巫女麦兰达那里。"}},
[6570]={"埃博斯塔夫",{"到尘泥沼泽中的巨龙沼泽去，找到埃博斯塔夫的洞穴。进入洞穴之后戴上龙形护符，然后跟埃博斯塔夫交谈。"}},
[6571]={"战歌氏族的补给品",{"收集战歌氏族的补给品：战歌锯条、伐木绳、战歌之油，还有一箱战歌之斧。"}},
[6581]={"战歌锯条",nil},
[6582]={"龙骨试炼，斯克利尔",{"找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。","","你可以在冬泉谷找到斯克利尔。"}},
[6583]={"龙骨试炼，索姆努斯",{"杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。"}},
[6584]={"龙骨试炼，克鲁纳里斯",{"诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。"}},
[6585]={"龙骨试炼，埃克托兹",{"到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。"}},
[6601]={"晋升……",{"看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找雷克萨，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。"}},
[6602]={"黑龙勇士之血",{"到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。"}},
[6603]={"冬泉谷的麻烦！",{"到冬泉谷的温泉附近去找到多诺瓦·雪山。"}},
[6604]={"被激怒的枭兽",{"与坠星村的加隆·石矛谈一谈。"}},
[6605]={"奇怪的家伙",{"与费伍德森林的温娜·哈萨德谈一谈。"}},
[6607]={"钓鱼专家纳特·帕格",{"纳特·帕格要你钓到以下几种鱼：","","悲伤沼泽芦苇海岸的芦苇海岸大马哈鱼。","","凄凉之地萨瑟里斯海岸的萨瑟里斯虎鱼。","","菲拉斯沃丹提斯河的菲拉斯草鱼。","","荆棘谷野人海岸的野人海岸蓝色叉牙鱼。","","当你钓到这些鱼之后，就可以回到纳特·帕格那里去了！"}},
[6608]={"你真棒！",{"你认为鲁玛克想要告诉你，他已经不能帮你提高钓鱼的技能了。也许你应该去找到他的朋友纳特·帕格，他居住在塞拉摩以南的某个岛屿上，他是一名人类渔夫（至少你认为鲁玛克是这么说的）。"}},
[6609]={"青出于蓝！",{"到卡利姆多大陆的塞拉摩去。从那里向南方出发，找到一座岛屿。纳特·帕格就在岛上等待着你的到来！"}},
[6610]={"蚌肉大餐",{"迪尔格·奎克里弗想要你收集这些原料：","","12只巨蛋。你可以在塔纳利斯的大鹏或是其它大型鸟类那里获得这种蛋。","","10块美味的蚌肉。你可以从任何蚌类身上获得这种原料！","","20块奥特兰克冷酪。去买就是了！","","收集好所有原料，然后把它们交给迪尔格。"}},
[6611]={"加基森之旅！",{"到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。"}},
[6612]={"我认识一个家伙…",{"到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。"}},
[6621]={"污林熊怪之王",{"把卡拉恩的旗子插到污林图腾堆中。不要让熊怪摧毁这面旗子。击败穆戈特酋长，将穆戈特的图腾交给佐拉姆加的卡拉恩·阿玛卡。"}},
[6622]={"救死扶伤",{"使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。","","一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。"}},
[6623]={"部落医疗队",{"到阿拉希高地的落锤镇去，与格里高利·维克托医生谈一谈关于加入部落外科医疗队的事宜。"}},
[6624]={"救死扶伤",{"使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。","","一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。"}},
[6625]={"联盟医疗队",{"到尘泥沼泽的塞拉摩去，与古斯塔夫·范沃森医生谈一谈关于加入联盟外科医疗队的事宜。"}},
[6626]={"邪恶之地",{"杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。"}},
[6627]={"知识试炼",{"成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。"}},
[6628]={"知识试炼",{"成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。"}},
[6629]={"杀死格鲁迪格·暗云",{"杀掉格鲁迪格·暗云和6个恐怖图腾蛮兵，然后向石爪山东南面的玛卡巴·扁蹄复命。"}},
[6641]={"鞭笞者沃尔沙",{"在穆格拉什寻找火盆的过程中保证他的安全。帮助他扑灭火盆，然后在与纳迦作战时保护他。","","如果你成功了，就回到佐拉姆加前哨站去，把鞭笞者沃尔沙的死讯通知给战歌信使。"}},
