[6646]={"兄弟会的好感 - 山脉之血",nil},
[6661]={"捕捉矿道老鼠",{"使用捕鼠者之笛捕获5只矿道老鼠，把它们引到蒙提那儿去。别忘了退还笛子。"}},
[6662]={"我的兄弟，尼普希",{"把装着神秘肉品的纸箱交给暴风城矿道地铁仓库的尼普希。"}},
[6681]={"拉文霍德庄园",{"把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。","","你的智慧将在这次旅途中得到考验。做好准备吧。"}},
[6701]={"辛迪加徽章",nil},
[6721]={"猎人之道",{"与多兰纳尔的达扎拉谈一谈。"}},
[6722]={"猎人之道",{"与多兰纳尔的达扎拉谈一谈。"}},
[6741]={"取之于敌",nil},
[6761]={"新的边疆",{"与达纳苏斯的塞纳里奥区的玛斯雷·驭熊者谈一谈。"}},
[6762]={"拉比恩·萨图纳",{"与月光林地永夜港的拉比恩·萨图纳谈一谈。月光林地在费伍德森林和冬泉谷之间，可以从木喉要塞中的一条通道抵达那里。"}},
[6781]={"护甲碎片",nil},
[6801]={"冰雪之王洛克霍拉",nil},
[6804]={"被囚禁的水元素",{"对东瘟疫之地的被感染的水元素使用海神之水。把12副不谐护腕和海神之水交给艾萨拉的海达克西斯公爵。"}},
[6805]={"雷暴和磐石",{"杀死15个灰尘风暴和15个沙漠奔行者，然后回到艾萨拉的海达克西斯公爵那儿。"}},
[6821]={"艾博希尔之眼",{"将艾博希尔之眼交给艾萨拉的海达克西斯公爵。"}},
[6822]={"熔火之心",{"杀死一个火焰之王、一个熔岩巨人、一个上古熔火恶犬和一个熔岩奔腾者，然后回到艾萨拉的海达克西斯公爵那里。"}},
[6823]={"海达克西斯的使者",{"在海达希亚水元素中达到被尊敬的声望，然后与艾萨拉的海达克西斯公爵谈一谈。"}},
[6824]={"敌人之手",{"将鲁西弗隆之手、萨弗隆之手、基赫纳斯之手和沙斯拉尔之手交给艾萨拉的海达克西斯公爵。"}},
