[6844]={"档案管理员阿姆伯尔",{"将异种蝎粘液包裹的物体交给月光林地永夜港的阿姆伯尔，他是塞纳里奥议会的档案管理员。"}},
[6845]={"发现过去的秘密",{"与月光林地永夜港的拉比恩·萨图纳谈一谈。"}},
[6846]={"展开攻击！",nil},
[6881]={"森林之王伊弗斯",nil},
[6921]={"废墟之间",{"把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。"}},
[6922]={"阿奎尼斯男爵",{"把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。"}},
[6941]={"天空的召唤 - 维波里的空军",nil},
[6942]={"天空的召唤 - 斯里多尔的空军",nil},
