[6982]={"冷齿矿洞的补给",{"把10份冷齿矿洞补给品交给丹巴达尔的联盟军需官。"}},
[6985]={"深铁矿洞的补给",{"把10份深铁矿洞补给品交给霜狼要塞的部落军需官。"}},
[7001]={"补充坐骑",{"找到奥特兰克山谷中的霜狼。使用霜狼口套来驯服它们。被驯服的霜狼会跟随你回到兽栏管理员那里，然后与兽栏管理员谈话以获得你的奖励。"}},
[7002]={"羊皮坐具",nil},
[7003]={"被缩小的巨人",{"使用索尔宾的超级压缩器来缩小菲拉斯的任意种类的巨人，将他们缩小到更容易控制的体积。从缩小过的巨人身上收集15份微缩残渣，把它们交给菲拉斯被遗忘的海岸码头的索尔宾·范达瑟。"}},
[7026]={"山羊坐具",nil},
[7027]={"补充坐骑",{"找到奥特兰克山谷中的山羊。使用雷矛训练颈圈来驯服它们。被驯服的山羊会跟随你回到兽栏管理员那里，然后与兽栏管理员谈话以获得你的奖励。"}},
[7028]={"扭曲的邪恶",{"为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。"}},
[7029]={"维利塔恩的污染",{"在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。","","在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。","","治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。"}},
[7041]={"维利塔恩的污染",{"在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。","","在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。","","治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。"}},
[7044]={"玛拉顿的传说",{"找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。","","然后设法和塞雷布拉斯对话。"}},
[7046]={"塞雷布拉斯节杖",{"帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。","","当仪式完成之后再和他谈谈。"}},
[7064]={"大地的污染",{"杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。"}},
[7065]={"大地的污染",{"杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。"}},
[7066]={"生命之种",{"到月光林地去找到雷姆洛斯，将生命之种交给他。"}},
[7067]={"贱民的指引",{"阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。"}},
[7068]={"暗影残片",{"从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。"}},
[7070]={"暗影残片",{"从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。"}},
[7081]={"奥特兰克山谷的墓地",{"占领一座墓地，然后向丹巴达尔的诺雷格·雷矛中尉复命。"}},
[7082]={"奥特兰克的墓地",{"占领一座墓地，然后向霜狼村的亚斯拉复命。"}},
[7101]={"哨塔和碉堡",{"占领敌方的某座哨塔，然后向霜狼村的提卡·血牙复命。"}},
[7102]={"哨塔和碉堡",{"摧毁敌方的某座哨塔或者碉堡中的旗帜，然后向丹巴达尔的杜尔根·雷矛复命。"}},
[7121]={"军需官",{"与雷矛军需管谈一谈。"}},
[7122]={"占领矿洞",{"占领一座还没有被雷矛部族控制的矿洞，然后向丹巴达尔的雷矛军需官复命。"}},
[7123]={"霜狼军需官",{"与霜狼军需官谈一谈。"}},
[7124]={"占领矿洞",{"占领一座矿洞，然后向霜狼村的霜狼军需官报告。"}},
[7141]={"奥特兰克的战斗",{"进入奥特兰克山谷，击败部落将军德雷克塔尔。然后回到勘查员塔雷·石镐那里。"}},
[7142]={"为奥特兰克而战",{"进入奥特兰克山谷，击败矮人将军范达尔·雷矛。然后回到沃加·死爪那里。"}},
[7161]={"试炼场",{"到主基地东南边的蛮爪洞穴中去找到霜狼军旗，然后把它交给拉格隆德。"}},
[7162]={"试炼场",{"到主基地东南边的冰翼洞穴中去找到雷矛军旗，然后把它交给哈格丁中尉。"}},
