[7366]={"大主教的仁慈",{"你被指派去杀死奥特兰克山谷中的被遗忘者玩家。","","杀死一个被遗忘者，然后把一枚被遗忘者的精华交给指挥官卡尔·菲利普（他一般在伐木场和矿井之间徘徊）。"}},
[7381]={"科尔拉克归来",{"如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。","","将科尔拉克的徽记交给霜狼要塞的拉格隆德。"}},
[7382]={"永生的科尔拉克",{"如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。","","将科尔拉克的徽记交给丹巴达尔的哈格丁中尉。"}},
[7383]={"大地之冠",{"用月亮井的水装满紫水晶瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。"}},
