[7507]={"诺斯特罗的屠龙技术纲要",{"将《诺斯特罗的屠龙技术纲要》还回图书馆。"}},
[7508]={"铸造奎尔塞拉",{"把黯淡的精灵剑交给博学者莱德罗斯。"}},
[7509]={"铸造奎尔塞拉",{"你必须设法让奥妮克希亚对这把未淬火的的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。","","在把它给我拿回来之前的最后一步是杀掉那条龙，并将加热过的上古之刃插入她的尸体中。","","完成这些之后，奎尔塞拉就是你的了。"}},
[7541]={"为部落效力",nil},
[7562]={"莫苏尔·召血者",{"与燃烧平原的莫苏尔·召血者谈一谈。"}},
[7563]={"血之狂暴",{"把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。"}},
[7564]={"戈瑟奇·邪眼",{"把血箱交给燃烧平原的戈瑟奇·邪眼。"}},
[7581]={"监牢之链",{"到菲拉斯的厄运之槌去，从扭木广场的荒野萨特身上找到15份萨特之血，然后把它们交给腐烂之痕的戴奥。"}},
[7582]={"监牢之壁",{"到冬泉谷的暗语峡谷去，从盘踞在峡谷中的赫达琳恶魔身上找到5块赫达琳之泪。完成任务之后回到腐烂之痕的戴奥那里。"}},
[7583]={"压制",{"在腐烂之痕中找到一个末日守卫指挥官。","","对其使用光芒水晶监牢。你要做好承受疯狂攻击的准备，那个恶魔会拼命挣扎试图逃脱。","","如果你成功了，就把被囚禁的末日守卫交给腐烂之痕的戴奥。"}},
[7601]={"尼比的助手",{"与费伍德森林的伊普斯谈一谈。"}},
[7602]={"无暇的恶魔精华",{"费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。","","艾萨拉的雷加斯萨特、费伍德森林的加德纳尔军团士兵和诅咒之地的地狱卫士斥候分别拥有一种无暇的恶魔精华。"}},
[7603]={"克罗苏斯的恶魔之核",{"在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。","","把克罗苏斯的恶魔之核交给费伍德森林的尼比。"}},
[7604]={"瑟银兄弟会契约",{"如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。"}},
[7621]={"警示",nil},
[7622]={"光与影的平衡",{"在总计有15个农夫被杀死之前拯救50个农夫。完成任务之后与艾瑞斯·哈文法谈谈。","","你可以通过浏览死亡布告来了解自己拯救了多少农夫。"}},
[7623]={"魔王贝恩霍勒",{"从燃烧平原的戈瑟奇那里购买暗影药水。","","使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。"}},
[7624]={"背叛者乌拉泰克",{"找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。"}},
[7625]={"克索诺斯星尘",{"从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。"}},
[7626]={"达斯莫拉之铃",{"把10瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。"}},
[7627]={"黑暗战车之轮",{"把6份大块魔光碎片和25块黑铁矿石交给燃烧平原的戈瑟奇·邪眼。"}},
[7628]={"末日蜡烛",{"把35块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。"}},
[7629]={"瓶中的小鬼",{"把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。"}},
[7630]={"奥金锭",{"把3块奥金锭交给燃烧平原的戈瑟奇·邪眼。"}},
[7631]={"克索诺斯恐惧战马",{"阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。"}},
[7632]={"远古石叶",{"找到远古石叶的主人。祝你好运，<name>。这个世界是很大的。"}},
[7633]={"介绍",nil},
[7634]={"龙筋箭袋",{"费伍德森林的古树哈斯塔特要求你带回一块成年蓝龙的肌腱。"}},
[7635]={"合适的弓弦",{"费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。"}},
[7636]={"古树的手杖",{"你必须找到并干掉下列4个恶魔：","","迷人的西蒙妮。","","疯狂的克林弗兰。","","S屠杀者索伦诺尔。","","摧毁者阿托留斯。","","杀掉这些恶魔，然后回到费伍德森林的古树瓦特鲁斯那里去。","","根据你背包中的石化树皮来找到它们所在位置的线索。","","你必须独自完成这个任务。"}},
[7637]={"牺牲精神",{"到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。"}},
[7638]={"格雷森·沙东布瑞克公爵",{"与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。"}},
[7639]={"圣骑士的审判",{"把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。"}},
[7640]={"恐惧谷的灵魂",{"使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。"}},
[7641]={"格瑞曼德·艾尔默",{"与暴风城矮人区的格瑞曼德·艾尔默谈一谈。"}},
[7642]={"收集材料",{"把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。"}},
[7643]={"上古圣马之魂",{"你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。","","到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。"}},
[7644]={"被祝福的奥金马铠",{"将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。"}},
[7645]={"魔法粮草",{"把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。","","你还需要给她50金币来对她进行安抚。"}},
[7646]={"预言水晶球",{"把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。"}},
[7647]={"审判和救赎",{"在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。","","把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。"}},
[7648]={"艾尔默的手艺",{"把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。"}},
[7649]={"魔化瑟银板甲：第一卷",{"将这本典籍交给它的主人。"}},
[7650]={"魔化瑟银板甲：第二卷",{"将这本典籍交给它的主人。"}},
[7651]={"魔化瑟银板甲：第三卷",{"将这本典籍交给它的主人。"}},
[7652]={"君王板甲的设计图",nil},
[7653]={"君王板甲腰带",nil},
[7654]={"君王板甲战靴",nil},
[7655]={"君王板甲护腕",nil},
[7656]={"君王板甲护胸",nil},
[7657]={"君王板甲头盔",nil},
[7658]={"君王板甲护腿",nil},
[7659]={"君王板甲护肩",nil},
[7666]={"重回尸骨储藏所",nil},
[7667]={"收集材料",{"如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。"}},
[7669]={"重回尸骨储藏所",nil},
[7670]={"格雷森·沙东布瑞克公爵",{"与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。"}},
[7701]={"悬赏：工头玛托留斯",{"那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。","","杀死工头玛托留斯，将他的头颅交给灼热峡谷的侦查队长洛洛尔以换取你的奖励。"}},
[7703]={"戈多克食人魔的事务",{"找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。","","根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。"}},
[7721]={"压缩器的动力",{"从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取10块水元素核心，把它们交给码头附近的索尔宾·范达瑟。"}},
[7722]={"绝密配方！",{"在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。"}},
[7723]={"该死的手指头！",{"汉瑟尔·重拳让你杀掉20个重型作战傀儡。","","重型作战傀儡就在灼热峡谷的大熔炉附近。当你杀死足够多的傀儡后，就回去找汉瑟尔·重拳。"}},
[7724]={"熔岩蜘蛛的威胁！",{"汉瑟尔·重拳要你杀死灼热峡谷中的20只巨型熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池里找到巨型熔岩蜘蛛。","","当你杀死足够的巨型熔岩蜘蛛之后，回到汉瑟尔·重拳那里复命。"}},
[7725]={"更多被缩小的巨人！",{"使用索尔宾的超级压缩器来缩小菲拉斯的任意种类的巨人，将他们缩小到更容易控制的体积。从缩小过的巨人身上收集10份微缩残渣，把它们交给菲拉斯被遗忘的海岸码头的索尔宾·范达瑟。"}},
[7726]={"补充动力",{"从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取6块水元素核心，把它们交给码头附近的索尔宾·范达瑟。"}},
[7727]={"熏火龙",{"汉瑟尔·重拳让你去杀掉20个熏火龙。","","熏火龙侵占了熔渣之池中的那些岩浆池。熔渣之池就在灼热峡谷的大熔炉中。","","当你杀死足够数量的熏火龙后，就回去找汉瑟尔·重拳。"}},
[7728]={"被盗：鼓风机和望远镜",{"找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。","","你所知道的关于这些物品的惟一信息是：它们肯定是被黑铁矮人偷走的。冶炼鼓风机是铁匠用的锻造工具，侦查员的望远镜是侦查员所需的侦查工具。"}},
[7729]={"工作机会：肃清竞争对手",{"杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。"}},
[7730]={"祖卡什的入侵",{"把20块祖卡什虫壳交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}},
[7731]={"毒刺鞭笞者",{"击败痛苦深渊中的毒刺鞭笞者，把它的腺体交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}},
[7732]={"祖卡什报告",{"把莫沙彻营地祖卡什报告交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。"}},
[7733]={"更高的品质",{"把10块怒痕雪人的毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。"}},
[7734]={"更高的品质",{"把10块怒痕雪人的毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。"}},
[7735]={"原始雪人毛皮",{"把原始雪人毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。"}},
[7736]={"炽热助熔剂的补给：皇血草",nil},
[7737]={"获得信任",nil},
[7738]={"完美的雪人毛皮",{"把完美的雪人毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。"}},
[7761]={"黑手的命令",{"真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。","","你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。"}},
[7781]={"黑石之王",{"将奈法利安的头颅交给暴风城的伯瓦尔·弗塔根公爵。"}},
[7782]={"黑石之王",{"回到暴风城的英雄谷，与艾法希比元帅谈一谈。"}},
[7783]={"黑石之王",{"将奈法利安的头颅交给奥格瑞玛的萨尔。"}},
[7784]={"黑石之王",{"和奥格瑞玛的萨鲁法尔大王谈谈。他在力量谷等你。"}},
[7785]={"复生之瓶",{"查看复生之瓶，然后回到德米提恩那里去。"}},
[7786]={"逐风者桑德兰",{"如果你想要把逐风者桑德兰从监牢里释放出来，你就必须找到左右两块逐风者禁锢之颅，10块源质锭，以及火焰之王的精华，把它们交给德米提恩。"}},
[7787]={"觉醒吧，雷霆之怒！",{"把风吻之刃交给德米提恩。"}},
