[7815]={"钳嘴龟！",{"辛特兰恶齿村的钓鱼者卡图姆要你去杀掉15只海水钳嘴龟。完成任务之后回到他那里去复命。"}},
[7816]={"加莫里塔！",{"辛特兰恶齿村的钓鱼者卡图姆要你去杀掉加莫里塔，并从它的尸体上找到卡图姆的超级鱼饵。","","卡图姆说加莫里塔和其它海龟都在海岸附近活动。"}},
