[7828]={"银鬃捕猎者",{"辛特兰恶齿村的猎户马克霍尔要求你去杀掉15头银鬃捕猎者和15头银鬃嗥狼。完成任务之后就回到他那里复命。","","马克霍尔说过那些狼都躲在辛特兰的野外。"}},
[7829]={"野蛮的枭兽",{"辛特兰恶齿村的猎户马克霍尔要求你去杀掉20头野蛮的枭兽。完成任务之后就回到他那里复命。","","马克霍尔说过那些野蛮的枭兽都躲在辛特兰的野外。"}},
[7830]={"死者的复仇",{"辛特兰恶齿村的猎户马克霍尔要求你杀掉一头翱翔的锋喙狮鹫，并将它的狮鹫长羽拿回去交给他。","","马克霍尔说过那些翱翔的锋喙狮鹫就躲在辛特兰的野外。"}},
