[8276]={"夺回希利苏斯",{"与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。"}},
[8277]={"沙漠中的剧毒",{"希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。"}},
[8278]={"诺格的最后一线希望",{"希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你给他带去3个石鞭巨钳蝎之刺、3个石鞭掠夺者之刺和3个石行蜘蛛的牙齿。"}},
[8279]={"暮光词典",{"把暮光词典的三个章节交给希利苏斯的隐士奥泰尔。"}},
[8280]={"保护补给线",{"希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。"}},
[8281]={"确保安全",{"希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。"}},
[8282]={"诺格的背包",{"从希利苏斯南部山中找到诺格的背包，然后将它交给塞纳里奥要塞中的诺格。"}},
[8283]={"通缉：死亡弯钩",{"将死亡弯钩的蝎钳交给卫兵队长维斯·库鲁兹。"}},
[8284]={"暮光的秘密",{"希利苏斯塞纳里奥要塞的地质学家拉克斯班要你去收集8块暮光石板碎片。"}},
[8285]={"沙漠隐士",{"把复原的石板带给希利苏斯的隐士奥泰尔。"}},
[8286]={"明天的希望",{"前往塔纳利斯的时光之穴寻找诺兹多姆的子嗣，阿纳克洛斯。"}},
[8287]={"摆脱困境",{"把解密石板碑文交给指挥官玛尔利斯。"}},
[8288]={"唯一的领袖",{"到黑石山中的奈法利安巢穴去，杀死勒什雷尔，并带回它的头颅。","","将勒什雷尔的头颅交给希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯。"}},
[8301]={"正义之路",{"为流沙守望者巴里斯托尔斯收集200块异种蝎壳碎片。"}},
[8302]={"正义之手",{"为流沙守望者巴里斯托尔斯收集200块异种蝎壳碎片。"}},
[8303]={"阿纳克洛斯",{"到塔纳利斯的时光之穴去寻找阿纳克洛斯。"}},
[8304]={"亲爱的纳塔莉亚",{"希利苏斯塞纳里奥要塞的指挥官玛尔利斯想要你询问铜须营地的矮人。你可以在塞纳里奥要塞以南找到铜须营地。","","一旦你收集到有用的信息，就回到指挥官玛尔利斯那儿。"}},
[8305]={"久远的记忆",{"找到希利苏斯的水晶之泪，并凝视它。"}},
[8306]={"深入疯狂之口",{"希利苏斯塞纳里奥要塞的指挥官玛尔利斯想要你找到他心爱的纳塔莉亚。你收集到的信息表明纳塔莉亚·玛尔利斯可能在南面的雷戈虫巢。","","在你赶往虫巢之前，记得去铜须营地拜访一下那儿的矮人，他们或许会给你提些建议。","","<name>，记住指挥官的话：做你应该做的……"}},
[8307]={"沙漠食谱",{"前往塞纳里奥要塞以西的暮光之锤营地，调查沙虫的烹饪方法。"}},
[8308]={"布莱恩·铜须的信",{"将布莱恩·铜须的信件带往希利苏斯南部的铜须营地。"}},
[8309]={"追查雕文",{"希利苏斯铜须营地的鲁特加尔·雕石想要你前往亚什虫巢、佐拉虫巢和雷戈虫巢，从虫巢中的雕文水晶上取下拓文。","","使用地质学家的抄录工具包获取古老雕文的摹本。完成任务后回到鲁特加尔·雕石那儿。"}},
[8310]={"破译密码",{"希利苏斯铜须营地的弗兰卡·石桥想让你取回一个亚什异种虫脑、一个佐拉异种虫脑和一个雷戈异种虫脑。完成任务后回到弗兰卡那儿。"}},
[8313]={"分享知识",{"将破碎的食谱交给塞纳里奥要塞旅店中的卡兰德拉斯。"}},
[8314]={"揭开秘密",{"铜须营地的鲁特加尔·雕石想让你将雕文水晶棱柱交给希利苏斯塞纳里奥要塞的地质学家拉克斯班。"}},
[8315]={"召唤",{"希利苏斯塞纳里奥要塞的地质学家拉克斯班想让你从其拉虫人使者那里取回水晶分解装置。","","你已经奉命将召唤雕文带往塞纳里奥要塞以南的格拉卡洛之骨处，将它们从沙中引出。一旦其拉虫人使者露面，就杀死它，获得水晶分解装置。成功之后回到地质学家拉克斯班那儿去。","","你必须召集一支强大的军队来完成这项任务，<name>！"}},
