[8464]={"冬泉熊怪的活动",{"萨尔法要你去杀死8个冬泉萨满祭司、8个冬泉巢穴守卫和8个冬泉巨熊怪。萨尔法就站在冬泉谷的木喉要塞入口处。"}},
[8465]={"与萨尔法交谈",{"穿过木喉要塞去冬泉谷。和萨尔法谈谈，他就在木喉要塞另一头的出口处。"}},
