[8470]={"死木仪祭图腾",{"把死木仪祭图腾拿到木喉要塞去，看看是否有熊怪想要研究一下它。只有当你在木喉要塞的声望达到中立或者更高级别的时候，木喉要塞的熊怪才会和你说话。"}},
[8471]={"冬泉仪祭图腾",{"把冬泉仪祭图腾拿到木喉要塞去，看看是否有熊怪想要研究一下它。只有当你在木喉要塞的声望达到中立或者更高级别的时候，木喉要塞的熊怪才会和你说话。"}},
[8481]={"万恶之源",{"把恶魔召唤火炬放在寒水村的冬泉酋长的洞穴入口处。击败召唤出来的恶魔，然后把沙迪维尔斯精华交给木喉要塞的独眼高恩。"}},
[8484]={"重铸和平",{"将木喉和平契约交给铁炉堡的国王麦格尼·铜须。"}},
[8485]={"重铸和平",{"将木喉和平契约交给奥格瑞玛的萨尔。"}},
[8496]={"战场上的绷带",{"把30根厚符文布绷带、30根厚魔纹绷带和30根厚丝质绷带交给唤风者梅恩·长角。你还必须随身带着后勤任务简报 X才能完成这个任务。"}},
[8497]={"沙漠生存包",{"把4份纯水之球、4份特效抗毒药剂和4份沙漠肉丸子交给希利苏斯塞纳里奥要塞的卡兰德拉斯。你还必须随身带着后勤任务简报 I才能完成这个任务。"}},
[8498]={"暮光作战命令",{"拿到暮光作战命令，把它交给希利苏斯塞纳里奥要塞的指挥官玛尔利斯。"}},
[8501]={"目标：亚什毒蝎",{"击杀30只亚什毒蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 XII才能完成这个任务。"}},
[8502]={"目标：亚什工蝎",{"击杀30只亚什工蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 III才能完成这个任务。"}},
[8507]={"战地任务",{"向佐拉虫巢外的铁炉堡军团报到，从布莱卡维尔上尉那里拿到签过字的战地任务文件，把它交给希利苏斯塞纳里奥要塞的唤风者卡尔东。","","注意：给铁炉堡军团的士兵治疗或者施放增益法术会打开你的PvP标志。"}},
[8508]={"战地任务文件",nil},
[8519]={"往日的回忆",{"了解所以可以的过去的事情，然后和塔纳利斯时光之穴的阿纳克洛斯谈谈。"}},
[8534]={"佐拉虫巢侦查报告",{"在佐拉虫巢内找到塞纳里奥斥候艾泽奈尔，然后把佐拉虫巢侦查报告交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着战术任务简报 VI才能完成这个任务。"}},
[8535]={"苍白圣殿骑士",{"召唤并杀死一名苍白圣殿骑士，然后向塞纳里奥要塞的鲍尔·蛮鬃复命。你还必须随身带着战术任务简报 III才能完成这个任务。"}},
[8536]={"土色圣殿骑士",{"召唤并杀死一名土色圣殿骑士，然后向塞纳里奥要塞的鲍尔·蛮鬃复命。你还必须随身带着战术任务简报 III才能完成这个任务。"}},
