[8538]={"四个公爵",{"设法召唤并击杀灰烬公爵、深渊公爵、微风公爵和碎石公爵，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须随身带着战术任务简报 V才能完成这个任务。"}},
