[8540]={"卫兵的靴子",{"把3双精制秘银战靴交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 II才能完成这个任务。"}},
[8541]={"卫兵的砂轮",{"把10块致密砂轮、10块坚固的砂轮和10块重砂轮交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 III才能完成这个任务。"}},
