[8730]={"奈法里奥斯的腐蚀",{"杀死奈法利安，并拿到红色节杖碎片。把红色节杖碎片交给塔纳利斯时光之穴入口处的阿纳克洛斯。你必须在5小时之内完成这个任务。"}},
[8731]={"战地任务",{"向雷戈虫巢外的奥格瑞玛军团报到，从克鲁格·碎颅那里拿到签过字的战地任务文件，把它交给希利苏斯塞纳里奥要塞的唤风者卡尔东。","","注意：给奥格瑞玛军团的士兵治疗或者施放增益法术会打开你的PvP标志。"}},
[8732]={"战地任务文件",nil},
[8733]={"伊兰尼库斯，梦境之暴君",{"到达纳苏斯的城墙外去找到玛法里奥的亲信。"}},
[8734]={"泰兰德和雷姆洛斯",{"到月光林地去，和守护者雷姆洛斯谈一谈。"}},
[8735]={"腐蚀梦魇",{"到艾泽拉斯世界的四个翡翠梦境入口去，分别收集该处的腐蚀梦魇的碎片。当你任务完成之后，就回到月光林地的守护者雷姆洛斯那里。"}},
[8736]={"噩梦显现",{"保护永夜港免受伊兰尼库斯的伤害。不要让守护者雷姆洛斯死亡。不要杀掉伊兰尼库斯。保护好你们自己。等待泰兰德。"}},
[8737]={"碧蓝圣殿骑士",{"召唤并杀死一名碧蓝圣殿骑士，然后向塞纳里奥要塞的鲍尔·蛮鬃复命。你还必须随身带着战术任务简报 I才能完成这个任务。"}},
[8738]={"雷戈虫巢侦查报告",{"在雷戈虫巢内找到塞纳里奥斥候兰迪奥，然后把雷戈虫巢侦查报告交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着战术任务简报 VII才能完成这个任务。"}},
[8739]={"亚什虫巢侦查报告",{"在亚什虫巢内找到塞纳里奥斥候佳莉亚，然后把亚什虫巢侦查报告交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着战术任务简报 VIII才能完成这个任务。"}},
[8740]={"暮光掠夺者",{"杀死暮光掠夺者莫娜和5个暮光掠夺者。任务完成之后就回去向唤风者梅恩·长角报告。你还必须随身带着战术任务简报 IX才能完成这个任务。"}},
[8741]={"勇士归来",{"把绿色节杖碎片交给塔纳利斯时光之穴的阿纳克洛斯。"}},
[8742]={"卡利姆多的力量",{"一千年过去了，正如命中注定的那样，一位勇士站在了我的面前。这位勇士将会带领他的人民走向新的纪元","","上古之神在颤抖，<name>。是的，它在你坚定的信念面前恐惧地颤抖着。打破克苏恩的预言吧。","","它知道你会到来的，勇士―它还知道卡利姆多的力量与你同在。当你做好准备之后，请通知我，我将把流沙权杖赐予你。"}},
[8745]={"时光之王的财宝",{"你好，勇士。我是神圣之锣和青铜龙军团的永恒观察者，乔纳森。","","你好，勇士。我是神圣之锣和青铜龙军团的永恒观察者，乔纳森。"}},
