[8989]={"瓦塔拉克饰品的右瓣",{"使用召唤火盆召唤出莫尔·灰蹄的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克公爵的饰品还给黑石山里的伯德雷。"}},
