[8991]={"瓦塔拉克饰品的右瓣",{"使用召唤火盆召唤出亚雷恩和索托斯的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克公爵的饰品还给黑石山的伯德雷。"}},
[8992]={"瓦塔拉克饰品的右瓣",{"使用召唤火盆召唤出库尔莫克的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克公爵的饰品还给黑石山的伯德雷。"}},
[8994]={"最后的准备",{"从黑石塔的兽人那儿收集40副黑石护腕，把它们和一瓶超级能量合剂一起交给黑石山的伯德雷。"}},
[8995]={"瓦塔拉克公爵",{"在比斯巨兽的房间里使用召唤火盆，召唤瓦塔拉克公爵。杀死他，对尸体使用瓦塔拉克的饰品。然后将瓦塔拉克的饰品还给瓦塔拉克公爵之魂。"}},
[8996]={"向伯德雷回复",{"回到黑石山的伯德雷那里去，把召唤火盆交给他。"}},
