[9015]={"挑战",{"到黑石深渊的竞技场去，在你被裁决者格里斯通宣判之后将挑战之旗插在场地中央。杀死塞尔德林和他的角斗士，然后将瓦塔拉克饰品第一部分交给东瘟疫之地的安泰恩·哈尔蒙。"}},
[9016]={"告别安泰恩",{"带上一双野性之心长靴、一条野性之心褶裙和一副野性之心肩甲，回去向奥格瑞玛的莫克瓦尔复命。"}},
