[9034]={"无畏胸甲",{"如果你将1件被玷污的胸甲、25块板甲碎片、4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一件无畏胸甲。"}},
