[9229]={"拉玛兰迪的命运",{"进入纳克萨玛斯的宫殿，找到拉玛兰迪的下落。"}},
[9230]={"拉玛兰迪的寒冰之握",{"东瘟疫之地圣光之愿礼拜堂的科尔法克斯要1个冰冻符文、1块蓝宝石和1块奥金锭。"}},
[9232]={"我只会唱这一首歌……",{"将2个冰冻符文、2个水之精华、2块蓝宝石和30金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9233]={"奥玛里恩的手册",{"将奥玛里恩的手册交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9234]={"破冰护手",{"将5个冰冻符文、12块瑟银锭、2块奥金锭、2个水之精华和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9235]={"破冰护腕",{"将4个冰冻符文、12块瑟银锭、2块奥金锭、2个水之精华和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9236]={"破冰胸甲",{"将8个冰冻符文、16块瑟银锭、2块奥金锭、4个水之精华和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。"}},
[9237]={"冰川披风",{"将5个冰冻符文、4个符文布卷、2个水之精华、4个铁网蛛丝和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。"}},
[9238]={"冰川护腕",{"将4个冰冻符文、2个符文布卷、2个水之精华、2个铁网蛛丝和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9239]={"冰川手套",{"将5个冰冻符文、4个符文布卷、4个水之精华、2个铁网蛛丝和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9240]={"冰川外衣",{"将8个冰冻符文、8个符文布卷、6个水之精华、4个铁网蛛丝和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。"}},
[9241]={"北极护腕",{"将4个冰冻符文、12个魔化皮、3个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9242]={"北极手套",{"将5个冰冻符文、12个魔化皮、3个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9243]={"北极外套",{"将8个冰冻符文、16个魔化皮、5个水之精华、5个熟化毛皮和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。"}},
[9244]={"寒鳞护腕",{"将4个冰冻符文、16片厚蝎鳞、5个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9245]={"寒鳞护手",{"将5个冰冻符文、16片厚蝎鳞、5个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}},
[9246]={"寒鳞胸甲",{"将8个冰冻符文、24片厚蝎鳞、7个水之精华、5个熟化毛皮和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。"}},
[9248]={"谦卑的馈赠",{"将一根深渊节杖交给希利苏斯塞纳里奥要塞的奥蕾尔·金叶。你在塞纳里奥议会的声望必须达到尊敬。"}},
[9250]={"埃提耶什之杖",{"看看有谁能帮你找到法杖的最后两个部分，并且净化邪恶的力量。"}},
[9251]={"埃提耶什，被玷污的传说之杖",{"塔纳利斯时光之穴的阿纳克洛斯要你找到埃提耶什的法杖顶部和埃提耶什的杖柄末端。"}},
[9257]={"埃提耶什，守护者的传说之杖",{"塔纳利斯时光之穴的阿纳克洛斯要你前往斯坦索姆，在神圣之地上使用埃提耶什，守护者的传说之杖。击败被驱赶出法杖的生物，然后回到阿纳克洛斯那里去。"}},
[9259]={"血帆海盗的叛徒",nil},
[9266]={"痛改前非",nil},
[9267]={"抚平旧伤",nil},
