[9272]={"海盗的制服",nil},
[9338]={"塞纳里奥议会的盟友",nil},
[9362]={"军阀克雷利安",{"为大法师克希雷姆夺回虹彩贝壳。大法师克希雷姆就居住在艾萨拉北部悬崖上的一座塔中。"}},
[9364]={"魔法的碎片",{"对艾萨拉的恶鞭纳迦使用变形术，然后杀死几秒钟后出现的相似体。当你杀了50个相似体后，回去向大法师克希雷姆复命。"}},
[9415]={"向布鲁沃尔元帅报告",{"与佐拉虫巢附近联盟营地的布鲁沃尔元帅谈一谈。"}},
[9416]={"向吉里卡将军报到",{"与雷戈虫巢附近部落营地的吉里卡将军谈一谈。"}},
[9419]={"横扫沙漠",{"找到一份水晶尘，将其送到水晶尘萃取器那里，然后向佐拉虫巢外联盟营地的布鲁沃尔元帅复命。"}},
[9422]={"横扫沙漠",{"找到一份水晶尘，将其送到水晶尘萃取器那里，然后向雷戈虫巢外部落营地的吉里卡将军复命。"}},
[9664]={"建立新据点",{"夺取东瘟疫之地的皇冠哨塔、东墙哨塔、北地哨塔和病木林哨塔，然后向圣光之愿礼拜堂的白须大使复命。"}},
[9665]={"加强防御",{"夺取东瘟疫之地的皇冠哨塔、东墙哨塔、北地哨塔和病木林哨塔，然后向圣光之愿礼拜堂的高莫克大使复命。"}},
[65593]={"爱人的徽记",{"把阿薇丽娜·莉莉和艾萨克·皮尔森的徽记带给诅咒神殿的凯伦丁·哈加尔。"}},
[65597]={"束缚",{"使用情人的徽记，召唤并征服一只夜魔，然后将情人的徽记还给幽暗城魔法区诅咒神庙里的凯伦丁·哈加尔。"}},
[65601]={"要爱就会受伤害",{"和奥格瑞玛的玛加尔谈一谈。"}},
[65602]={"爱是什么？",{"取得木雕，把它交给暴风城法师区里的黑暗缚灵者加科因。"}},
[65603]={"束缚",{"使用木雕召唤并制服一个夜魔，然后将木雕还给已宰的羔羊旅店的黑暗缚灵者加科因。"}},
[65604]={"束缚",{"使用皱缩头巾召唤并征服一只夜魔，然后皱缩头巾还给奥格瑞玛的甘鲁尔·血眼。"}},
[65610]={"希望你还在",{"调查灰谷的坠星湖并将你的发现告诉奥格瑞玛的甘鲁尔·血眼。"}},
}]=])())
