MUI_EncounterJournalDB:Localize(loadstring([=[return {
instances={[226]={name="怒焰裂谷",desc="怒焰裂谷深入奥格瑞玛的地下。野蛮的穴居人和狡诈的燃刃信徒曾在这些熔岩洞穴中肆虐一时。但现在，这里又出现了新的威胁：黑暗萨满。虽然加尔鲁什·地狱咆哮酋长最近召集了一批萨满，准备以元素为武器来对付联盟，但洞中的这些新居民似乎都是变节者。报告表明，这些阴暗的家伙正在集结一支足以毁灭奥格瑞玛的灼热大军。"},[240]={name="哀嚎洞穴",desc="几年前，著名的德鲁伊纳拉雷克斯及其追随者走进了阴暗的哀嚎洞穴。这座洞穴的裂隙中会喷出蒸汽，其声酷似悲伤的哭号。哀嚎洞穴因此而得名。纳拉雷克斯打算利用地下温泉使荒芜的贫瘠之地恢复生机。可进入翡翠梦境之后，他却发现自己的复兴计划变成了一个活生生的噩梦，至今仍在洞中作祟。"},[63]={name="死亡矿井",desc="曾经有人称死亡矿井的黄金乃是暴风城国库储备的三分之一。在第一次大战的混乱中，矿井遭到了遗弃，闹鬼不断、无人问津，直到迪菲亚兄弟会的到来——他们曾经是一群工人，如今却成了强盗，他们将这迷宫变成了自己的行动基地，来实施对暴风城的破坏活动。"},[64]={name="影牙城堡",desc="在银松森林南部悬崖的焚木村上，影牙城堡犹如一道黑影矗立。从前这里是疯狂大法师阿鲁高狼人们的居所，如今它的废墟被罪恶的力量所占据。席瓦莱恩男爵阴魂不散，高弗雷勋爵和他的幕僚，往昔的吉尔尼斯贵族阴谋对付他们的敌人，无论对方是生者还是亡灵。"},[227]={name="黑暗深渊",desc="人们原本以为曾被奉献给暗夜精灵女神艾露恩的黑暗深渊已经在大分裂中被彻底摧毁并永远沉入了大海。数千年后，暮光之锤的邪教徒被邪恶的低语和梦境引入了神殿。在献祭了无数的无辜者之后，这个教派得到了一个新的任务：保护上古之神最珍视的生物之一，一头仍需喂养的宠物，直至它对世界释放出自己的黑暗力量。"},[231]={name="诺莫瑞根",desc="建于丹莫罗群山深处的奇迹之城诺莫瑞根曾是侏儒智慧与工业技术的象征。但当主城遭到穴居人入侵时，侏儒大工匠却遭到了他的顾问，希科·瑟玛普拉格的背叛。最终，若莫瑞根遭辐射污染，大部分居民遇害。幸存的侏儒逃离了这里，但他们誓言将回到这里并重夺家园。"},[238]={name="监狱",desc="建于暴风城运河下方的暴风城监狱是一座守卫森严的监狱。典狱官塞尔沃特看守着这座监狱和那些以此为家的危险罪犯。最近，这里的囚犯发生了暴动，他们打倒守卫并使监狱陷入了混乱。"},[234]={name="剃刀沼泽",desc="传说，半神阿迦玛甘倒下时，他的鲜血催生出了巨大的荆棘藤蔓。许多野猪人就居住在最大的一片荆棘丛，剃刀沼泽中。他们称这里是阿迦玛甘的安息之地。"},[316]={name="血色修道院",desc="十字军的疯狂领袖们把信徒引进了位于血色修道院中心位置的血色大教堂。这个守卫森严的处所成为了十字军的总指挥部，一些最为狂热和偏执的十字军成员则徘徊在这曾经的神圣之地。"},[239]={name="奥达曼",desc="奥达曼是一座深埋地下的远古泰坦宝库。据说，泰坦们在那里封印了一个失败的实验，并开始了有关矮人起源的新实验。有关蕴藏伟大知识的宝藏的传说引诱着宝藏猎人来发掘奥达曼的秘密。但潜伏在这座失落之城中的岩石守卫、野蛮穴居人、黑铁入侵者以及其他威胁令这个任务变得危险重重。"},[233]={name="剃刀高地",desc="传说，半神阿迦玛甘倒下时，他的鲜血催生出了巨大的荆棘藤蔓。最近，有斥候报告说发现有亡灵在该地区出没，令人不禁担心是不是恐怖的天灾军团打算来征服卡利姆多了。"},[232]={name="玛拉顿",desc="传说，塞纳留斯之子，扎尔塔和土元素公主瑟莱德丝公主生下了野蛮的半人马种族。半人马诞生后不久，这些粗野的生物就谋杀了他们的父亲。据说，悲痛欲绝的瑟莱德丝将爱人的灵魂囚禁在玛拉顿中并腐化了这一地区。如今，邪恶的半人马鬼魂和扭曲的元素爪牙充斥着这座杂乱洞穴的每一个角落。"},[241]={name="祖尔法拉克",desc="祖尔法拉克曾是塔纳利斯沙漠中的一颗明珠，由狡诈的沙怒部族守护。尽管巨魔们顽强不屈，但这支孤立无援的部落还是在漫长的历史近程中逐渐丧失了大量领土。现在，祖尔法拉克的居民们似乎正在制造一支由巨魔亡灵组成的恐怖大军，试图靠它们征服周围的地区。还有一些令人不安的流言称，这座城市里沉睡着一头古老的生物。一旦它被唤醒，死亡和毁灭就会降临塔纳利斯。"},[246]={name="通灵学院",desc="想要驾驭亡者之力的学徒们都对通灵学院这个名字并不陌生，这是位于凯尔达隆地下黑暗恐怖墓穴中的一所专修亡灵之术的邪恶学院。近些年来，学院更换了几位导师，但教学制度仍在黑暗院长加丁的牢牢掌控之下，他是一位极其施虐成性、阴险狡诈的亡灵法术研习者。"},[228]={name="黑石深渊",desc="静静燃烧的黑石深渊是黑铁矮人和他们的皇帝，达格兰·索瑞森的家园。和他的前任一样，达格兰服从炎魔拉格纳罗斯的铁腕统治。这个残忍的生物是数个世纪前被召唤到这个世界的。混乱的元素活动将暮光之锤的邪教徒引到了这片山区。他们与拉格纳罗斯的仆人一起将矮人逼向毁灭的边缘，这最终也将导致全艾泽拉斯的毁灭。"},[237]={name="阿塔哈卡神庙",desc="数千年前，一支强大的牧师教派，阿塔莱试图在艾泽拉斯召唤出其血腥神灵，噬魂者哈卡的化身。这令古拉巴什帝国被陷入了内战。古拉巴什人民将阿塔莱流放到悲伤沼泽。阿塔莱牧师们就在这里建造了阿塔哈卡神庙。绿龙军团的守护巨龙伊瑟拉将神庙沉入了沼泽之下，并派出守卫以阻止任何人再次进行召唤仪式。"},[229]={name="黑石塔下层",desc="这座雄伟的堡垒一直深入黑石山的熔火地心之中，几个世纪来一直代表着黑铁部落实力。最近，黑龙奈法利安和他的子嗣夺取的堡垒的上层高塔并对矮人们发动了残酷的战争。龙族大军与大酋长雷德·黑手及其伪部落结成了盟友。这支联军在塔中为所欲为，进行可怕的实验以扩充军队，试图一举覆灭多管闲事的黑铁矮人。"},[230]={name="厄运之槌 - 中心花园",desc="数千年前，作为收藏卡多雷奥术秘密的殿堂，埃雷萨拉斯曾盛极一时。而如今，它已成为一片废墟，到处翻滚着诡异、扭曲的力量。许多势力都曾争夺过厄运之槌的堕落力量的控制权，但最终他们达成了脆弱的停战协议，在各自的实力范围内研究着当地的能量，而不再全面开战。"},[1276]={name="厄运之槌 - 扭木广场",desc="数千年前，作为收藏卡多雷奥术秘密的殿堂，埃雷萨拉斯曾盛极一时。而如今，它已成为一片废墟，到处翻滚着诡异、扭曲的力量。许多势力都曾争夺过厄运之槌的堕落力量的控制权，但最终他们达成了脆弱的停战协议，在各自的势力范围内研究着当地的能量，而不再全面开战。"},[236]={name="斯坦索姆 - 正门",desc="斯坦索姆曾是北洛丹伦的一颗明珠，但如今的人们只会记得它那悲惨的衰亡史。阿尔萨斯王子就是在这里拒绝了高贵的圣骑士光明使者乌瑟尔的帮助，屠杀了无数据信感染了可怕的亡灵瘟疫的居民。从那时起，受到诅咒的斯坦索姆就被死亡、背叛和绝望彻底毁灭了。"},[1277]={name="厄运之槌 - 戈多克议会",desc="数千年前，作为收藏卡多雷奥术秘密的殿堂，埃雷萨拉斯曾盛极一时。而如今，它已成为一片废墟，到处翻滚着诡异、扭曲的力量。许多势力都曾争夺过厄运之槌的堕落力量的控制权，但最终他们达成了脆弱的停战协议，在各自的势力范围内研究着当地的能量，而不再全面开战。"},[1292]={name="斯坦索姆 - 仆从入口",desc="斯坦索姆曾是北洛丹伦的一颗明珠，但如今的人们只会记得它那悲惨的衰亡史。阿尔萨斯王子就是在这里拒绝了高贵的圣骑士光明使者乌瑟尔的帮助，屠杀了无数据信感染了可怕的亡灵瘟疫的居民。从那时起，受到诅咒的斯坦索姆就被死亡、背叛和绝望彻底毁灭了。"},[741]={name="熔火之心",desc="熔火之心位于黑石深渊的最底部。这里是黑石山的心脏，很久以前，索瑞森大帝为了扭转矮人内战的战局而孤注一掷，正是在这里将元素火焰之王拉格纳罗斯召唤到了这个世界。尽管火焰之王无法远离炽热的熔火之心，但据信他的元素仆从正在指挥黑铁矮人，而黑铁矮人正忙于用活化的岩石打造军队。拉格纳罗斯沉睡的燃烧之湖是一道连接火焰位面的裂隙，恶毒的元素生物可以借此通过。管理者埃克索图斯是拉格纳罗斯手下最重要的仆从——因为只有这个狡猾的元素生物才能将火焰之王从沉睡中唤醒。"},[760]={name="奥妮克希亚的巢穴",desc="奥妮克希亚是强大的巨龙死亡之翼的女儿，也是黑石塔之王、诡计多端的奈法利安的妹妹。据说奥妮克希亚喜欢通过干涉凡人种族的政治事务来腐蚀他们。为此，人们相信她会化身为各种人形，利用她的魅力和力量来影响不同种族之间的微妙事务。有人认为奥妮克希亚甚至使用了她父亲曾经用过的化名——普瑞斯托贵族家族的头衔。在不干涉凡人事务的时候，奥妮克希亚居住在黑龙谷下方的一个炽热洞穴中，黑龙谷是尘泥沼泽中一片阴暗的沼泽。在那里，她由她的族人——阴险的黑龙军团的残余成员——守护着。"},[742]={name="黑翼之巢",desc="黑翼之巢位于黑石塔的最高处。在这座山峰顶端的黑暗深处，奈法利安已经开始实施其计划的最后阶段：彻底消灭拉格纳罗斯，并率领他的军队成为凌驾于艾泽拉斯所有种族之上、无可争议的霸主。"},[76]={name="祖尔格拉布",desc="丛林巨魔古拉巴什一度控制着南方的大片丛林，祖尔格拉布就是他们的首都。妖术师金度曾在这里将夺灵者哈卡召唤到了艾泽拉斯世界。近来，古拉巴什和赞达拉巨魔结成了同盟，为建立一个统一的巨魔帝国而挑起了新的战火。"},[743]={name="安其拉废墟",desc="在流沙之战的最后时刻，暗夜精灵与四大巨龙军团的联军将战火一直推进到了其拉帝国的心脏——要塞之城安其拉。然而在城门前，卡利姆多的军队遭遇了前所未有的庞大异种蝎战斗工虫群。最终，异种蝎和它们的其拉主人并没有被击败，只是被囚禁在了一道魔法屏障之内，而这场战争使这座被诅咒的城市化为一片废墟。自那天起已经过去了一千年，但其拉的军队并未就此沉寂。一支可怕的新军队已经从虫巢中诞生，安其拉废墟中再一次挤满了成群的异种蝎和其拉虫人。这一威胁必须被消除，否则整个艾泽拉斯都可能倒在新其拉大军恐怖的力量之下。"},[744]={name="安其拉神殿",desc="安其拉的中心坐落着一座古老的神殿群。它建于有史可考之前，既是不可名状之神的纪念碑，也是其拉大军的巨大繁殖地。自从一千年前流沙之战结束以来，其拉帝国的双子皇帝一直被困在他们的神殿之中，仅凭青铜龙阿纳克洛斯和暗夜精灵所竖立的魔法屏障勉强将其困住。如今流沙节杖已被重新组合，封印也已被打破，通往安其拉内部圣殿的道路已经敞开。在虫巢中蠕动的疯狂之外，在安其拉神殿的下方，成群结队的其拉虫人正在准备发动入侵。必须不惜一切代价阻止他们，以免他们再次向卡利姆多释放贪婪的虫族大军，引发第二次流沙之战！"},[754]={name="纳克萨玛斯",desc="漂浮在瘟疫之地上空的浮空城纳克萨玛斯，是巫妖王麾下最强大的将领之一——恐怖的巫妖克尔苏加德的居所。随着巫妖王的仆从准备发动进攻，过去的恐怖和尚未释放的新威胁正在浮空城中聚集。天灾军团很快将再次进军……"}},
encounters={[11517]={name="奥格弗林特",creatures={[1]="奥格弗林特"}},[11520]={name="饥饿者塔拉加曼",creatures={[1]="饥饿者塔拉加曼"}},[11518]={name="祈求者耶戈什",creatures={[1]="祈求者耶戈什"}},[11519]={name="巴扎兰",creatures={[1]="巴扎兰"}},[3671]={name="安娜科德拉",desc="当纳拉雷克斯自作主张地派人前往贫瘠之地时，绯叶是第一个自告奋勇的人。在心智被主人的噩梦彻底粉碎后，这位年轻的侍僧便将自己的名姓丢诸脑后，现在正酝酿着艾泽拉斯邪恶阴险的未来。",creatures={[1]="安娜科德拉"}},[3670]={name="皮萨斯",desc="作为纳拉雷克斯的儿时玩伴，战士阿里恩在德鲁伊之道上有着过人的天赋。尽管受过严格训练，但这位侍僧却仍无力对抗令他丧失理智的腐化。阿里恩改名换姓，以皮萨斯的新身份将自己超凡的近战能力与德鲁伊的学识合二为一，粉碎一切入侵者。",creatures={[1]="皮萨斯"}},[3669]={name="考布莱恩",desc="加拉克斯拉驾驭动物形态的能力，为他在塞纳里奥议会的德鲁伊间赢得了威名。然而，哀嚎洞穴的腐化却扭曲了他的特殊能力。现在，加拉克斯拉已将一种致命的毒蛇形态演练得出神入化，为自己冠以考布莱恩的新名字，以体现他那全新的邪恶力量。",creatures={[1]="考布莱恩"}},[3653]={name="克雷什",desc="这只巨龟是哀嚎洞穴的古老住民，终日在地下洞穴间游荡，他顽强的心智丝毫没有受到纳拉雷克斯无情噩梦的影响。别被他乐天的性情给骗了，克雷什已经将许多妄图偷取他巨大龟壳的冒险者打得落荒而逃。",creatures={[1]="克雷什"}},[3674]={name="斯卡姆",desc="斯卡姆原本只是为了逃避贫瘠之地的恶劣环境才前往哀嚎洞穴的。与洞内的许多其它住民一样，他也很快就遭到腐化。如今在他周身流淌着黑暗能量，他已经无可挽回地变成了一只强大凶残的野兽。",creatures={[1]="斯卡姆"}},[3673]={name="瑟芬迪斯",desc="毒牙德鲁伊的领袖曾是纳拉雷克斯最出色的学生。他的悲剧源自于他想要成为大导师，也就是“荣誉导师”的热望，想要和纳拉雷克斯比肩。疯狂在他心中生根发芽，瑟芬迪斯将他的兄弟们召集在一起，成立了这个名叫毒牙德鲁伊的组织。",creatures={[1]="瑟芬迪斯"}},[5775]={name="永生者沃尔丹",desc="在纳拉雷克斯来到哀嚎洞穴之前，人们对这只生物了解甚少。永生者沃尔丹被看作是洞穴的原始守护者，没能逃过降临在自己家园的腐化。沃尔丹与其他疯狂的德鲁伊结为盟友，对那些擅自闯入的不速之客保持着高度警惕。",creatures={[1]="永生者沃尔丹"}},[3654]={name="吞噬者穆坦努斯",desc="从纳拉雷克斯扭曲心灵最为阴暗的角落里，席卷翡翠梦境的腐化之力已体现在德鲁伊的死敌——鱼人的身上。名叫穆坦努斯的怪物来到这个清醒的世界上，吞噬任何想要将纳拉雷克斯从梦魇中解救出来的人。",creatures={[1]="吞噬者穆坦努斯"}},[644]={name="拉克佐",desc="身为迪菲亚兄弟会安排在死亡矿井的首席工头，拉克佐负责监督和“鼓励”手下的劳工。他的手段并不传统，但卓有成效。",creatures={[1]="拉克佐"}},[643]={name="斯尼德",desc="残酷无情的效率为斯尼德赢得了伐木主管的岗位。他的目标非常简单：以尽可能低廉的成本建造一艘无畏舰。凭借自己建造的伐木机，他在生产作业中一马当先，做出了迅速而惊人的成绩。",creatures={[1]="斯尼德"}},[1763]={name="基尔尼格",desc="天才工程师基尔尼格是迪菲亚兄弟会行动体系中的冶炼主管。他负责为无畏舰装配充足的火炮和弹药，不完成使命便誓不罢休。",creatures={[1]="基尔尼格"}},[646]={name="重拳先生",desc="作为绿皮船长的大副，重拳负责管束好手下的船员。他是一名战技出众的武器大师，精通刀剑劈砍和拳打脚踢，偶尔也会展示自己的枪法。",creatures={[1]="重拳先生"}},[647]={name="绿皮船长",desc="来自藏宝海湾的绿皮是正在修造的无畏舰的船长，曾经统率过一整支海盗的舰队。",creatures={[1]="绿皮船长"}},[639]={name="艾德温·范克里夫",desc="范克里夫原本是石工协会的领袖，在与贵族产生纠纷后毅然离开了暴风城，成立了迪菲亚兄弟会。范克里夫随后夺取了死亡矿井，将这里作为行动基地，开始建造用于复仇大业的无畏舰。",creatures={[1]="艾德温·范克里夫"}},[645]={name="曲奇",desc="除了艾德温·范克里夫，没人知道曲奇怎么稀里糊涂地成了随船的厨子。不过对海盗而言，有饭吃就不错了。",creatures={[1]="曲奇"}},[3914]={name="雷希戈尔",creatures={[1]="雷希戈尔"}},[3886]={name="屠夫拉佐克劳",creatures={[1]="屠夫拉佐克劳"}},[3887]={name="席瓦莱恩男爵",creatures={[1]="席瓦莱恩男爵"}},[4278]={name="指挥官斯普林瓦尔",creatures={[1]="指挥官斯普林瓦尔"}},[4279]={name="盲眼守卫奥杜",creatures={[1]="盲眼守卫奥杜"}},[4274]={name="吞噬者芬鲁斯",creatures={[1]="吞噬者芬鲁斯"}},[3927]={name="狼王南杜斯",creatures={[1]="狼王南杜斯"}},[4275]={name="大法师阿鲁高",creatures={[1]="大法师阿鲁高"}},[4887]={name="加摩拉",creatures={[1]="加摩拉"}},[4831]={name="萨利维丝",creatures={[1]="萨利维丝"}},[6243]={name="格里哈斯特",creatures={[1]="格里哈斯特"}},[4832]={name="梦游者克尔里斯",creatures={[1]="梦游者克尔里斯"}},[4830]={name="瑟拉吉斯",creatures={[1]="瑟拉吉斯"}},[4829]={name="阿库麦尔",creatures={[1]="阿库麦尔"}},[7361]={name="格鲁比斯",desc="在城内弥漫的放射性气体本是为了激怒穴居人，杀死侏儒，而瑟玛普拉格的凶残计划也实施得天衣无缝。但有一只穴居人却对这种物质产生了奇怪的反应——格鲁比斯长啊，长啊，越长越大。这是令希科始料未及的副作用，可他从来都不是一个会浪费珍贵（且危险）资源的人。这只体型庞大的穴居人如今就在诺莫瑞根的隧道中巡视。他忠实的蜥蜴宠物咀嚼者则帮助格鲁比斯嗅探气体泄漏，寻找美味的真菌，甚至是可口的入侵者。",creatures={[1]="格鲁比斯"}},[7079]={name="粘性辐射尘",desc="诺莫瑞根那原本恢弘优雅的复杂水道，现在被辐射得乌烟瘴气，到处都是毒性泥浆怪。有个曾住在侏儒蓄水层中的孤单水元素被污染困住，污染物将它的纯净形态腐化得面目全非。它现在愤怒而痛苦地游荡在诺莫瑞根的殿堂间，成为了瑟玛普拉格背叛留下的邪毒液体化身。",creatures={[1]="粘性辐射尘"}},[6235]={name="电刑器6000型",desc="机械师瑟玛普拉格不是个有耐心的侏儒。他不喜欢通过一次次的实验去验证发明的安全性和有效性，而是急于将其投入使用，并将注意力转移到下一个项目上。电刑器6000型是他首次尝试通过超能机械坦克将电能作为武器的产物。“霹雳裤”汤姆·克兰科中尉是唯一一位驾驶过电刑器的幸存士兵，现在成了麻风侏儒里的大英雄。",creatures={[1]="电刑器6000型"}},[6229]={name="群体打击者9-60",desc="在诺莫瑞根的全盛时期，发明家们会相互比试自己的发明，以此提升自己的地位。工程师奥格索普·奥布诺提斯研制出了一个无敌机器人，这为他在大工匠协会中赢得了尊重。希科·瑟玛普拉格盗取了奥布诺提斯的蓝图，然后造出了一个巨版机器人。他任由自己的伪造品肆虐，引发了严重的后果，无辜的奥布诺提斯因此遭到了管理委员会的驱逐。群体打击者9-60至今仍是瑟玛普拉格最倾心的（剽窃）发明之一。",creatures={[1]="群体打击者9-60"}},[7800]={name="机械师瑟玛普拉格",desc="杀人犯、叛徒、自我加冕的侏儒国王，机械师希科·瑟玛普拉格用破绽百出的铁腕手段统治着诺莫瑞根的放射性殿堂。他的臣民数量众多，邪恶疯狂，足以保护自己的疯王免受任何来自地上世界的侵袭。正是瑟玛普拉格的疯狂使他变得极其危险——他有着摧毁身边万物的狡诈，且丝毫不顾自身安危。难怪就连诺莫瑞根里的怪物都对他望而生畏。",creatures={[1]="机械师瑟玛普拉格"}},[1696]={name="可怕的塔格尔",creatures={[1]="可怕的塔格尔"}},[1666]={name="卡姆·深怒",creatures={[1]="卡姆·深怒"}},[1717]={name="哈姆霍克",creatures={[1]="哈姆霍克"}},[1716]={name="巴基尔·斯瑞德",creatures={[1]="巴基尔·斯瑞德"}},[1663]={name="迪克斯特·瓦德",creatures={[1]="迪克斯特·瓦德"}},[1720]={name="布鲁高·铁拳",creatures={[1]="布鲁高·铁拳"}},[6168]={name="鲁古格",creatures={[1]="鲁古格"}},[4424]={name="阿格姆",creatures={[1]="阿格姆"}},[4428]={name="亡语者贾格巴",creatures={[1]="亡语者贾格巴"}},[4420]={name="主宰拉姆塔斯",creatures={[1]="主宰拉姆塔斯"}},[4422]={name="暴怒的阿迦赛罗斯",creatures={[1]="暴怒的阿迦赛罗斯"}},[4421]={name="卡尔加·刺肋",creatures={[1]="卡尔加·刺肋"}},[3983]={name="审讯员韦沙斯",creatures={[1]="审讯员韦沙斯"}},[4543]={name="血法师萨尔诺斯",creatures={[1]="血法师萨尔诺斯"}},[3974]={name="驯犬者洛克希",creatures={[1]="驯犬者洛克希"}},[6487]={name="奥法师杜安",creatures={[1]="奥法师杜安"}},[3975]={name="赫洛德",creatures={[1]="赫洛德"}},[3976]={name="血色十字军指挥官莫格莱尼",creatures={[1]="血色十字军指挥官莫格莱尼"}},[3977]={name="大检察官怀特迈恩",creatures={[1]="大检察官怀特迈恩"}},[4542]={name="大检察官法尔班克斯",creatures={[1]="大检察官法尔班克斯"}},[6910]={name="鲁维罗什",desc="在铁炉堡颇富威信的探险者协会里，有杰出人士提出，在其族人和穴居人之间存在着某种古老的联结，并指出，穴居人贮存的泰坦神器，正彰显着矮人自身对这种神奇装置的崇拜。假如果真如此，这位名叫鲁维罗什的穴居人就应该被看作是穴居人中的考古学家，尽管任何略有历史概念的冒险者在遇到他时，都会更愿意把他称作小偷。",creatures={[1]="鲁维罗什"}},[6906]={name="失落的矮人",desc="为了名望，更为了财富，埃瑞克、奥拉夫和巴尔洛戈这三兄弟与探险者协会签订了合约，到奥达曼的殿堂中一探究竟，并为身后的研究人员扫清道路。但对这三位矮人来说，“扫清道路”却不幸地演变成了“在古老的迷宫中绝望地迷失方向”。可他们毕竟是骄傲的矮人，他们英勇战斗，决不让奥达曼与探险者协会的秘密落在部落的手里。",creatures={[1]="失落的矮人"}},[7228]={name="艾隆纳亚",desc="泰坦并没有直接建造奥达曼，而是让诸多仆从共同缔造了这一巨石筑成的华丽殿堂。万神殿委托看守者艾隆纳亚监管奥达曼的建造和维护，可随着时间的流逝，曾经令人惊叹的宫殿变成了废墟。在地图厅里，艾隆纳亚静待了数千年，苦苦分析由卡兹格罗斯起草的原始蓝图，设法将这一恢弘建筑复原到最初的风貌。",creatures={[1]="艾隆纳亚"}},[7206]={name="远古巨石卫士",desc="远古巨石卫士是驻守和看管伟大泰坦殿堂的众多魔像之一，也是介于看守者与众多仆从之间的中间角色。在黑曜石哨兵的腐化发生后，远古巨石卫士成了它群体中的最后一位，尽自己最大努力守护泰坦的秘密，直到自己也倒下为止。",creatures={[1]="远古巨石卫士"}},[7291]={name="加加恩·火锤",desc="在铜须矮人发现奥达曼后，黑铁部族迅速做出反应，对这座地下宝库发起入侵，以防那些强大的神器落入先祖敌人之手。加加恩·火锤——来自暗炉城的参议员，被派去监督奥达曼的挖掘工作，以确保皇帝能利用神器的毁灭性潜能消灭黑铁部族的敌人。",creatures={[1]="加加恩·火锤"}},[4854]={name="格瑞姆洛克",desc="在穴居人社会中，块头最大、最强壮且最为凶狠的穴居人，常常会通过展示实力成为酋长。格瑞姆洛克相对而言是个天才，他通过威慑和某种意义上的心理战术，维持着对石窟穴居人的统治。他训练了一只致命的蜥蜴，用这野兽的石化手段令任何妄图谋逆的宵小不敢造次。",creatures={[1]="格瑞姆洛克"}},[2748]={name="阿扎达斯",desc="在奥达曼深处有间密室，里面藏有泰坦最伟大的财宝之一，由诺甘农亲自缔造。然而，至今为止还没有哪位冒险家拿到过这件圣物，因为任何动静都会激活强大的看守者阿扎达斯，这是一位体型庞大的护卫，凭借有力的攻击与名副其实的仆从大军，将对财宝怀有不轨企图的宵小之徒轻松消灭。由采自奥达曼深处的远古坚石塑造而成，阿扎达斯是位既古老又可怕的对手。",creatures={[1]="阿扎达斯"}},[7355]={name="图特卡什",creatures={[1]="图特卡什"}},[7357]={name="火眼莫德雷斯",creatures={[1]="火眼莫德雷斯"}},[8567]={name="暴食者",creatures={[1]="暴食者"}},[7356]={name="腐烂的普雷莫尔",creatures={[1]="腐烂的普雷莫尔"}},[7354]={name="拉戈斯诺特",creatures={[1]="拉戈斯诺特"}},[7358]={name="寒冰之王亚门纳尔",creatures={[1]="寒冰之王亚门纳尔"}},[13282]={name="诺克赛恩",desc="诺克赛恩是腐化的活化身。瑟莱德丝命她的同伴维利塔恩造出这个腐烂的元素，充当强大的仆从和忠实的宠物，来化解公主心中的孤寂。诺克赛恩将自己的剧毒精华散播到玛拉顿尚未受到瑟莱德丝邪恶影响的其它区域。",creatures={[1]="诺克赛恩"}},[12258]={name="锐刺鞭笞者",desc="创造锐刺鞭笞者的初衷是为了让它在玛拉顿里陪伴诺克赛恩。随着时间的推移，这一全新造物却成了公主最珍爱的仆从之一。锐刺鞭笞者与诺克赛恩并肩在洞穴里游荡，用长满尖刺的卷须将所能找到的任何未受污染的植物撕成碎片。",creatures={[1]="锐刺鞭笞者"}},[13601]={name="工匠吉兹洛克",desc="工匠吉兹洛克与其它五位宝石猎人溜进了玛拉顿，前去采集异常珍贵的水晶。但当其它队友都被萨特屠戮殆尽，仅有吉兹洛克一人幸存时，他才明白他们的计划全盘落空了。这位地精被困在洞穴里，濒临疯狂的边缘，将自己视作这个地下王国的新统治者。",creatures={[1]="工匠吉兹洛克"}},[12236]={name="维利塔恩",desc="萨特领主维利塔恩在闻听玛拉顿遭到腐化的消息后，便动身前往玛拉顿深处。瑟莱德丝起初对这位少言寡语的恶魔颇有戒心，但维利塔恩用行动证明了自己的价值，他为公主造出了许多邪恶的仆从，如诺克赛恩和锐刺鞭笞者。",creatures={[1]="维利塔恩"}},[12225]={name="被诅咒的塞雷布拉斯",desc="在闻听叔叔的悲惨命运后，高尚的塞雷布拉斯立誓解救扎尔塔的灵魂。可当这位林地守护者在玛拉顿的阴暗廊道间遭逢恐惧时，他全然没有做好准备。塞雷布拉斯很快就被四处弥漫的黑暗能量席卷，心中充满了不可控制的愤怒。",creatures={[1]="被诅咒的塞雷布拉斯"}},[12203]={name="兰斯利德",desc="多年以来，名叫兰斯利德的古老山巨人都在玛拉顿料理着璀璨的水晶花园，但自打瑟莱德丝来此定居的那天起，兰斯利德便深深地被她吸引住了。这位曾经清心寡欲的巨人现今生活的唯一目的就是为他残暴的新主人效力。",creatures={[1]="兰斯利德"}},[13596]={name="洛特格里普",desc="有传闻说，洛特格里普已经在玛拉顿的地下水域中居住了上千年。大名鼎鼎的矮人猎手赫米特·奈辛瓦里有一次宣称无人能找到这野兽，于是就有许多业余追踪者接受挑战，立志寻找这只传说中的生物。结果全都有去无回。",creatures={[1]="洛特格里普"}},[12201]={name="瑟莱德丝公主",desc="土元素瑟莱德丝——石母塞拉赞恩的独生女，住在玛拉顿的内室深处。由于受到上古之神的影响，这位公主将她的家园变成了充满腐化与痛苦的窝巢。有人认为，她的邪恶力量是与她已故爱人扎尔塔的灵魂紧密联系在一起的。假如果真如此，那么解放这位陨殁的林地守护者，也许是净化玛拉顿的唯一希望所在。",creatures={[1]="瑟莱德丝公主"}},[7272]={name="殉教者塞卡",desc="许久以前，殉教者塞卡在其拉与巨魔间爆发的激烈战争中不幸殒命。由于他的英勇牺牲，祖尔法拉克仍然屹立不倒。即便是在死后，他仍警惕地守护着自己挚爱的城市，据说，那些害死他的虫人战士们都受到了诅咒，化身为无脑圣甲虫，在殉道者身边奔来跑去。",creatures={[1]="殉教者塞卡"}},[7795]={name="水占师维蕾萨",desc="和大部分沙怒巨魔不同，水占师维蕾萨踏遍了世界各地，搜集学识与神器，希望能够掌控祖尔法拉克的圣水。虽然水占师的行径树敌无数，但她觉得只要掌控了不可思议的力量，就能为过去犯下的累累恶行正名。",creatures={[1]="水占师维蕾萨"}},[8127]={name="安图苏尔",desc="安图苏尔希望自己的苏利萨斯蜥蜴们长得又壮又凶残。他对待这些周身长满鳞片的野兽如同家人一般，任何人——哪怕是巨魔，如果胆敢伤害他的宝贝孩子们，都会遭到他的无情痛击。安图苏尔不会给对手留下全尸，而是允许蜥蜴们对那些自己送上门来的倒霉蛋大快朵颐。",creatures={[1]="安图苏尔"}},[7271]={name="巫医祖穆拉恩",desc="强大的守护者邦桑迪照看着暗矛巨魔的灵魂，可许多沙怒部族亡故成员的灵魂却没能得到这样的庇佑。这些饱受折磨的灵魂服从于祖穆拉恩，这是一位残忍的巫医，用黑暗魔法迫使城中的亡者无止无休地为自己效命。",creatures={[1]="巫医祖穆拉恩"}},[7273]={name="加兹瑞拉",desc="相传，加兹瑞拉是上古之神心爱的宠物，甚至她自身就是一位半神。不论真相如何，沙怒巨魔都对这只多头蛇有着长达数千年的崇拜历史。由于对这野兽的寒冰怒火心怀惧意，巨魔们只会在祭品丰裕时才会唤醒加兹瑞拉，让它大快朵颐。",creatures={[1]="加兹瑞拉"}},[7796]={name="耐克鲁姆和塞瑟斯",desc="耐克鲁姆在寿命终结后，继续以不可思议的方式存活着，他日渐腐烂的身体仍能对塞瑟斯提供帮助。这两位巨魔共同为沉睡在城市中心的神秘巨兽加兹瑞拉搜罗祭品。许多巨魔追随者都迫不及待地等待着这只可怖怪物的苏醒，为了亲眼观看仪式不惜付出任何代价。",creatures={[1]="耐克鲁姆和塞瑟斯"}},[7267]={name="乌克兹·沙顶",desc="乌克兹·沙顶沉迷于为自己的部族寻获往日的荣光。在他的成长过程中，早已对那些辉煌时代的传奇故事耳熟能详。那时，巨魔们在其古老的土地上称王称霸，完全没有地精、侏儒、海盗、食人魔以及其它外来入侵者的滋扰。沙顶邀请他的挚友卢兹鲁帮他一同书写沙顶历史的新篇章，用自己部族仅有的方式——追风掣电且目空一切的暴力，重振雄风。",creatures={[1]="乌克兹·沙顶"}},[10506]={name="传令官基尔图诺斯",creatures={[1]="传令官基尔图诺斯"}},[10503]={name="詹迪斯·巴罗夫",creatures={[1]="詹迪斯·巴罗夫"}},[11622]={name="血骨傀儡",creatures={[1]="血骨傀儡"}},[10433]={name="马杜克·布莱克波尔",creatures={[1]="马杜克·布莱克波尔"}},[10432]={name="维克图斯",creatures={[1]="维克图斯"}},[10508]={name="莱斯·霜语",creatures={[1]="莱斯·霜语"}},[10505]={name="讲师玛丽希亚",creatures={[1]="讲师玛丽希亚"}},[11261]={name="瑟尔林·卡斯迪诺夫教授",creatures={[1]="瑟尔林·卡斯迪诺夫教授"}},[10901]={name="博学者普克尔特",creatures={[1]="博学者普克尔特"}},[10507]={name="拉文尼亚",creatures={[1]="拉文尼亚"}},[10504]={name="阿雷克斯·巴罗夫",creatures={[1]="阿雷克斯·巴罗夫"}},[10502]={name="伊露希亚·巴罗夫",creatures={[1]="伊露希亚·巴罗夫"}},[1853]={name="黑暗院长加丁",creatures={[1]="黑暗院长加丁"}},[9018]={name="审讯官格斯塔恩",desc="暮光之锤邪教徒格斯塔恩向来沉湎于对生活品质的不懈追求：异国料理，靓衣华服，就连刑具都是由宝石镶嵌而成。囚徒那令人毛骨悚然的哭号声日夜在黑铁部族声名狼藉的禁闭室中回响。格斯塔恩骄傲地宣称，这骇人的声音是她谱写的尖叫交响曲，而她则时刻渴望在这和声中加入新的音色。",creatures={[1]="审讯官格斯塔恩"}},[9025]={name="洛考尔",desc="洛考尔对火元素诡计多端、尔虞我诈的本性感到深恶痛绝。为了能远离在熔火之心中效力的其它同类，这个强大的生物故意惹得火焰之王大发雷霆。洛考尔为自己的危险之举付出了代价——他被逐出了熔火之心，被迫孤绝地守卫黑石深渊。",creatures={[1]="洛考尔"}},[9319]={name="驯犬者格雷布玛尔",desc="格雷布玛尔·蚤须的猎犬是他唯一的家人。早在许久以前，这个矮人孤儿就开始繁育幼犬，把它们当做同伴和看门狗。要是驯犬者没有带上他的忠实跟班在黑石深渊里巡逻，那他通常就是在黑铁酒吧里喂它们喝上好的黑铁啤酒。",creatures={[1]="驯犬者格雷布玛尔"}},[10096]={name="秩序竞技场",desc="对黑铁矮人犯下罪行的人只会受到一种惩罚，那就是死亡。根据古老的传统，有罪之人要在秩序竞技场中对抗来自艾泽拉斯的各种凶残生物，付出鲜血的代价。迄今为止，没人知道是否有在这残忍酷刑中侥幸生还的幸运儿。",creatures={[1]="秩序竞技场"}},[9024]={name="控火师罗格雷恩",desc="罗格雷恩曾是大地之环中一位饱受尊敬的成员，后来却以不为人知的原因加入了暮光之锤。他最后来到了黑石深渊，突然对著名黑铁建筑师弗兰克罗恩·铸铁有了兴趣。他眼下究竟意欲何为，我们不得而知，但罗格雷恩始终忠于他的教派，任何反对教派的人都是他不共戴天的仇敌。",creatures={[1]="控火师罗格雷恩"}},[9017]={name="伊森迪奥斯",desc="迦顿男爵教伊森迪奥斯驾驭自己的破坏力，可男爵怎么也没有想到，这位仆从竟会带来如此大的威胁。对伊森迪奥斯篡权的担忧日滋夜长，迦顿终于决定将这炽热元素逐出熔火之心，命其守卫黑铁矮人传奇的黑铁砧。",creatures={[1]="伊森迪奥斯"}},[9041]={name="典狱官斯迪尔基斯",desc="在对索瑞森大帝尽忠多年后，这位名叫斯迪尔基斯的狡诈法师赢得了大帝的信任，奉命看守其部族在黑色宝库中的宝箱。挚友驯犬者格雷布玛尔将一条凶犬——维雷克送给了这位忠心耿耿的矮人，以表达祝贺之情。法师对其善加利用，随时将它带在身边，以吓退那些擅闯宝库的贼人。",creatures={[1]="典狱官斯迪尔基斯"}},[9056]={name="弗诺斯·达克维尔",desc="首席建筑师弗诺斯·达克维尔将其它更具天赋泥瓦匠的创意据为己有，并因此声名鹊起。他的傲慢与心计使长眠地下的前辈——弗兰克罗恩·铸铁心生怨愤。这位已故首席建筑师的鬼魂想要从达克维尔手中夺回他那把威力无比的铁胆之锤，以防它被用来作恶。",creatures={[1]="弗诺斯·达克维尔"}},[9016]={name="贝尔加",desc="可怕的熔岩巨人贝尔加在黑铁大道上隆隆缓行，黑铁大道是筑于黑石深渊内部的矮人工程学建筑奇迹。拉格纳罗斯将这巨人从火焰之地的中心地带引来这里，命他看守位于大道尽头的封印重门。相传，只有火焰领主和黑铁氏族最德高望重的成员才知道在那扇神秘的大门背后，究竟藏着什么。",creatures={[1]="贝尔加"}},[9033]={name="怒炉将军",desc="经过毕生钻研，怒炉将军已成为矮人军事历史与用兵学的行家里手。他最近撰写了一篇抨击部族过往败绩的严苛文章，引得达格兰·索瑞森大帝大发雷霆。抛开这个政治错误不提，怒炉本质上还是个够格的黑铁矮人。为保护自己的人民与皇帝，他甘愿流血，乃至牺牲。",creatures={[1]="怒炉将军"}},[8983]={name="傀儡统帅阿格曼奇",desc="阿格曼奇毕生对长生不死的追求，使他按自己的样貌造出了魔法替身。有传闻说，他甚至使用了某种形式的黑暗魔法，当这位傀儡统帅的血肉之躯遭到毁坏时，他的新造物便能成为他灵魂的容器。",creatures={[1]="傀儡统帅阿格曼奇"}},[9537]={name="霍尔雷·黑须",desc="如果仅把黑须说成是黑铁酒吧的常客，那也太轻描淡写了。在过去十年间，这个搞怪的酒鬼只离开过酒吧一次，还是去偷雷霆啤酒的绝密配方。黑须偶尔也会清醒一阵子，亲自动手调制这美酒，并宣称喝下此酒的人能获得难以想象的力量与勇气。",creatures={[1]="霍尔雷·黑须"}},[9502]={name="法拉克斯",desc="在黑铁酒吧里几乎每天都上演着酒后滋事的戏码，直到最近才有所改观。酒吧老板普拉格派法拉克斯出马，大大降低了酒徒们闹事的频率，这是一个强大的魔像保镖，负责维持酒吧里的秩序，用极端暴力手段赶走那些无事生非的顾客。",creatures={[1]="法拉克斯"}},[9499]={name="普拉格",desc="他们说，在黑铁酒吧里，人人都知道彼此的名字。这种亲密无间的友爱之情都是普拉格的功劳，他是一位在诺莫瑞根陷落后来黑石深渊开创新生活的麻风侏儒。虽然他过去是个与魔鬼打交道的术士，但现在却对自己酒吧老板的身份引以为傲，确保让顾客的酒杯里永远美酒满溢。",creatures={[1]="普拉格"}},[9156]={name="弗莱拉斯总大使",desc="由于对拉格纳罗斯无比忠诚，弗莱拉斯以大使的尊贵身份被派往黑铁部族。这个卑鄙的家伙起初对他的矮人盟友们不屑一顾，但渐渐地对他们嗜好破坏的性格心生尊敬。为了展示团结，弗莱拉斯担负起守卫魔法之厅的重任，这是矮人们用来强化武器的圣所。",creatures={[1]="弗莱拉斯大使"}},[9039]={name="黑铁七贤",desc="几个世纪以前，巫王索瑞森和他麾下七位最强大的黑铁同伴误打误撞地将拉格纳罗斯召唤进了艾泽拉斯，并致使自己的整个部族都惨遭奴役。尽管七贤在仪式中死亡，但他们不得安息的灵魂却一直在黑石深渊徘徊，被迫为自己的元素主人和现在的黑铁统治者效命。",creatures={[1]="黑铁七贤"}},[9938]={name="玛格姆斯",desc="弗莱拉斯大使让熔火巨人玛格姆斯守卫达格兰·索瑞森大帝的王座厅，但这一做法也没能让这位黑铁统治者放下忧虑。由于惧怕暗杀，大帝甚至允许玛格姆斯控制位于他王室门外的众多喷火雕像。",creatures={[1]="玛格姆斯"}},[9019]={name="达格兰·索瑞森大帝",desc="达格兰·索瑞森大帝与敌对铜须部族的茉艾拉公主共掌统治大权。没人知道新娘究竟是受到了大帝的迷惑，还是自愿与他作伴。但不论真相如何，索瑞森的继续存在，始终会对他部族的未来造成不良影响。只要他还活着，黑铁矮人就仍是拉格纳罗斯的马前卒，也是艾泽拉斯各个王国的致命威胁。",creatures={[1]="达格兰·索瑞森大帝"}},[8443]={name="哈卡的化身",desc="哈卡惯于把追随者当成祭品，因此声名狼藉。千万年前，他命阿塔莱建造祭坛，将从活人身上汲取的鲜血进献给它。阿塔莱祭司现在想对这一仪式略作修改，以献祭绿龙的方式供奉哈卡祭坛。一旦阿塔莱成功了，哈卡祭坛便会复现，艾泽拉斯将在劫难逃。",creatures={[1]="哈卡的化身"}},[5710]={name="预言者迦玛兰",desc="迦玛兰是阿塔莱的现任领袖，这是一个由疯狂崇拜哈卡的祭司组成的极端教派。在深度冥想中，迦玛兰收到了指示，得知可用哈卡宿敌——绿龙的鲜血使其复活。迦玛兰和他的亡灵侍卫——可悲的奥戈姆，决心消灭任何胆敢阻止哈卡回归的叛逆之徒，但这位先知的行动很可能会让更为可怕的翡翠梦魇笼罩艾泽拉斯。",creatures={[1]="预言者迦玛兰"}},[5312]={name="梦境守望者",desc="四条前途光明的幼龙随伊兰尼库斯一同进入了阿塔哈卡神庙，急于证明自己能为伟大强力的飞龙助上一臂之力。结果却一个接一个遭到了翡翠梦魇的囚禁和腐化，现在终日在沉没的神庙里游荡，朝那些胆敢打扰自己清梦的不速之客发泄怒气。",creatures={[1]="梦境守望者"}},[5709]={name="伊兰尼库斯的阴影",desc="伊兰尼库斯——梦境之神伊瑟拉从前的配偶，被派去守卫阿塔哈卡遗迹，阻止哈卡现身。进入神庙之后，他和随从便遭到了黑暗力量的腐化，伊兰尼库斯变成了阴影，在翡翠梦境与真实界域间饱受撕扯。但腐化并未抹除伊兰尼库斯的所有记忆，他还能凭借自己身为绿龙的力量，朝敌人喷吐腐蚀酸液，或使其陷入沉睡。",creatures={[1]="伊兰尼库斯的阴影"}},[9196]={name="欧莫克大王",desc="欧莫克以铁腕手段统治着塔内的食人魔。许多下属都提出过跟他单挑，希望借此夺取大王的头衔，但全都无一例外地倒地落败，根本碰不到他。这个神秘的现象引发了传言，说有黑暗魔法在保护着欧莫克。",creatures={[1]="欧莫克大王"}},[9236]={name="暗影猎手沃什加斯",desc="沃什加斯以她的美貌和神经病倾向在巨魔间享有盛名。作为深谙暗影猎手之道的大师，她精通妖术、诅咒与治疗魔法。",creatures={[1]="暗影猎手沃什加斯"}},[9237]={name="指挥官沃恩",desc="在第二次战争期间，沃恩率奇袭小队深入高等精灵的腹地深处，执行英勇的任务。这个狡诈的巨魔之所以选择加入落败的部落，是为了要成为首席战略家，而并非认同黑手的价值观。在沃恩眼中，这卑微阵营的成员无异于丧家之犬，他乐于逾越不可克服的障碍，并享受因此获得的满足感。",creatures={[1]="指挥官沃恩"}},[10596]={name="烟网蛛后",desc="几个世纪前，黑铁矮人钻入了烟网蛛后的巢穴，将这只巨型蜘蛛放进了尖塔的殿堂。从那时起，蛛后就在塔内大量繁衍蛛群，甚至就连黑手军团都不敢在烟网蛛后的地盘上随意穿行。",creatures={[1]="烟网蛛后"}},[10584]={name="尤洛克·暗嚎",desc="尤洛克是尖塔食人魔的真正领袖。这个阴险的家伙用邪恶魔法魅惑了他信赖的助手——欧莫克大王，让他代替自己控制麾下的爪牙。他不遗余力地保持着这份深居幕后的神秘感，残忍地将那些胆敢质疑欧莫克统治的食人魔尽数消灭。",creatures={[1]="尤洛克·暗嚎"}},[9736]={name="军需官兹格雷斯",desc="在第一次战争结束后，兽人猎手兹格雷斯因儿戏般地追捕和屠杀暴风城难民而变得臭名昭著。他厌恶黑石塔内幽闭恐怖的殿堂，但他相信，自己终有一天能在露天的战场上再次展开猎杀。",creatures={[1]="军需官兹格雷斯"}},[10220]={name="哈雷肯",desc="哈雷肯来自以残忍和忠诚著称的伟大座狼家族。多年以来，由这位狼群之母繁育出的凶蛮后代数量惊人。有传言称，她是燃烧军团某位深渊领主送给雷德·黑手的恶魔猎犬。",creatures={[1]="哈雷肯"}},[10268]={name="奴役者基兹鲁尔",desc="在黑暗部落里很少有人见过避世隐居、神出鬼没的基兹鲁尔。只有当配偶哈雷肯发出召唤时，这只巨兽才会从他那阴暗的巢穴中钻出来。这两只可怕的怪物已经生出了不少又大又凶残的座狼，载入了兽人繁育座狼的史册。",creatures={[1]="奴役者基兹鲁尔"}},[9568]={name="维姆萨拉克",desc="黑色龙兽维姆萨拉克管理着黑石塔下层的军队，随时准备向矮人发动全面攻势。他对落败的部落及其凶残的成员并无好感，为了保护自己的主人奈法利安，就算要牺牲多少黑手军团的爪牙也在所不惜。",creatures={[1]="维姆萨拉克"}},[11489]={name="特迪斯·扭木",desc="特迪斯·扭木是埃雷萨拉斯的忠诚守护者，他的内心坚定地与这座城市的命运紧紧联系在一起。当大分裂使这片土地变得支离破碎时，他的决心也从未动摇过分毫，但当腐化之力在接下来的一万年间渗入废墟，这位先祖的灵魂也未能幸免于难。",creatures={[1]="特迪斯·扭木"}},[11488]={name="伊琳娜·暗木",desc="伊琳娜·暗木与她忠实的伙伴费拉，曾经是托塞德林王子最得力的猎手，后来，她因拒绝执行领袖的命令，不肯处死自己的伙伴而遭到重罚。托塞德林王子杀死了伊琳娜和她的熊，而且还用恶魔之力将他们的灵魂束缚在躯体上，责罚他们以亡灵守护者的身份继续留在厄运之槌。",creatures={[1]="伊琳娜·暗木"}},[11487]={name="卡雷迪斯镇长",desc="当托塞德林王子下令处死大部分臣民时，他最忠心的中尉们负责执行他的意志。卡雷迪斯镇长不假思索地杀死了许多毫无戒备的辛德拉精灵，但在这群厄难临头的精灵中，却有一位在混战中对他造成了致命伤。但凡躯虽死，卡雷迪斯的灵魂却仍在厄运之槌游荡，继续为托塞德林保驾护航。",creatures={[1]="卡雷迪斯镇长"}},[11496]={name="伊莫塔尔",desc="当永恒之井被摧毁后，辛德拉精灵为重获往日的力量与不死之身，将魔鬼召进了厄运之槌的西翼，并将他禁锢在力场之内，用虚空恐魔的能量强化自己的法术。伊莫塔尔在将近一万年间无力回击，甚至动弹不得，只能眼巴巴地等待自己挣脱束缚的那一天，将囚禁者大卸八块。",creatures={[1]="伊莫塔尔"}},[11486]={name="托塞德林王子",desc="在永恒之井遭到毁灭后，托塞德林王子将一只恶魔囚禁在埃雷萨拉斯的废墟间，继续统治幸存的辛德拉精灵，并让自己的臣民从中汲取力量。恶魔之力扭曲了托塞德林的心智，而当那恶魔力量衰退时，王子便下令处死了许多民众，只有他和那些最狂热的追随者们才能继续享用腐化能量。",creatures={[1]="托塞德林王子"}},[14327]={name="蕾瑟塔蒂丝",desc="厄运之槌的扭曲能量将蕾瑟塔蒂丝从远方吸引而来，令对奥术魔法有着无尽渴求的她看到了希望。她用献祭牺牲者的肌肉和韧带制出了特殊的网，从东翼虹吸腐化之力。让她高兴的是，她发现这个装置能收集并贮存势不可当的强大力量，足以送所有敌人归西。",creatures={[1]="蕾瑟塔蒂丝"}},[13280]={name="海多斯博恩",desc="当名叫瑟雷姆·刺蹄的萨特想要控制厄运之槌的元素时，在他祭坛下方池塘中平静居住的海多斯博恩引起了他的注意力。在他进行邪恶的献祭仪式时，元素突然变得暴怒不安，出水攻击刺蹄的恶魔爪牙。一晃许多年过去了，刺蹄不断用牺牲者的能量激起海多斯博恩的狂怒，渐渐使他甘心接受自己的命令。",creatures={[1]="海多斯博恩"}},[11490]={name="瑟雷姆·刺蹄",desc="为了向燃烧军团证明自己的价值，瑟雷姆·刺蹄告诉他的主人，他能奴役那些仍在厄运之槌徘徊的强大先祖。当他意识到自身力量的不足时，刺蹄就开始从其它生灵身上寻找额外的能量，将他们在祭坛上杀死，在其苦痛难耐的临终之际收集他们的精魄。",creatures={[1]="瑟雷姆·刺蹄"}},[11492]={name="荒野变形者奥兹恩",desc="荒野变形者奥兹恩毕生最大的追求就是彻底腐化菲拉斯，但当他在厄运之槌中发现艾德雷斯神殿以前，他没有取得丝毫成功。现在，被奴役先祖的力量任他指挥，奥兹恩将附近森林的生命之力悉数汇聚到自己的巢穴中，随意支配。",creatures={[1]="荒野变形者奥兹恩"}},[10558]={name="弗雷斯特恩",desc="净化斯坦索姆的行动，夺去了无数无辜者的性命，他们唯一的罪行就是不该待在这座厄难临头的城市里。旅行歌手兼短笛演奏者弗雷斯特恩就是其中一位牺牲者。他在死后继续在城市中游荡，无法接受自己的悲剧命运。",creatures={[1]="弗雷斯特恩"}},[10516]={name="不可宽恕者",desc="莉莉娅曾是他族人间的正义之刃。在阿尔萨斯率军净化城市后，莉莉娅亲眼目睹无数无辜者死在她的手上，这使她丧失了理智。她选择挥剑逃避身边的疯狂，而现在，她则以鬼魂的身份存在，所犯下的恶行永远都不会得到赦免。",creatures={[1]="不可宽恕者"}},[11143]={name="邮差马龙",desc="马龙凭借自己对邮件无微不至的关照而当上了邮差。即使沦为如今的境地，他依然勤勤恳恳地维护着邮政系统。如果这一系统遭到干扰，乃至濒临瓦解，马龙就只好亲自出手摆平了。",creatures={[1]="邮差马龙"}},[10808]={name="残忍的提米",desc="提米森因在战场上的凶蛮而臭名远播。有人推测，他的病态性格是源自童年时期不断被欺负的经历。现在他已经以天灾怪物的身份重生，心智破碎，饱受过往记忆的煎熬，只要有人唤起那个曾令他深恶痛绝的名字——提米，他就会应声而来。",creatures={[1]="残忍的提米"}},[11032]={name="指挥官玛洛尔",desc="玛洛尔与其他几位勇敢的战士们甘愿冒一切风险守护血色十字军堡垒，使其免受亡灵的亵渎。但可悲的是，他们失败了。巴纳扎尔将这名无惧的指挥官腐化成了他的仆从，使这名狂热者不得不与自己生前最憎恨的仇敌同流合污。",creatures={[1]="指挥官玛洛尔"}},[10997]={name="希望破坏者威利",desc="巴纳扎尔愉快地发现，炮手威利在变成了亡灵之后仍能驾驭他那极具破坏性的力量，于是他给这位得力仆从起了个好名字——希望破坏者。恐惧魔王恣意扭曲威利和其他血色十字军成员的灵魂，把这些生时对亡灵恨之入骨的人，变成他的无脑爪牙。",creatures={[1]="希望破坏者威利"}},[10811]={name="档案管理员加尔福特",desc="加尔福特曾经将看管十字军珍贵文献的工作视作莫大荣耀。但在临死前，他却惊恐地看着那些被他视如珍宝的书卷被付之一炬。巴纳扎尔用这痛苦的记忆为他的仆从注入了生时令他不得安宁的炽热力量。",creatures={[1]="档案管理员加尔福特"}},[10813]={name="巴纳扎尔",desc="巴纳扎尔从没体会过真正的死亡，但他却尝过失败的苦果。在世界被大灾变破坏之后，他杀死了斯坦索姆中的血色十字军成员，并将他们变成了自己曾经憎恨的亡灵生物。这位恐惧魔王如今正在酝酿着对艾泽拉斯复仇的诡计。",creatures={[1]="巴纳扎尔"}},[14326]={name="卫兵摩尔达",desc="摩尔达是戈多克食人魔中的狂热忠诚守卫。他说服戈多克大王赏给他一副施了魔法的手套，使他在族人间连续六年荣膺掰腕子大赛的冠军。事实上，戈多克大王是把这强大的护甲丢弃了，摩尔达只不过是第一个捡到它的人而已。",creatures={[1]="卫兵摩尔达"}},[14322]={name="践踏者克雷格",desc="鬼祟的刺客们不止一次因打翻克雷格的酒杯而惨遭毒手。尽管他总是会在当值时喝得酩酊大醉，但是只要一听到杯中美酒洒在石头地面上的声音，这位食人魔就会立即醒来，勃然大怒。",creatures={[1]="践踏者克雷格"}},[14321]={name="卫兵芬古斯",desc="自从观察者克鲁什告诉他，说他能在执勤时遇见命中注定的伴侣，芬古斯便时刻打起十二万分精神在戈多克领土上巡逻。",creatures={[1]="卫兵芬古斯"}},[14323]={name="卫兵斯里基克",desc="有些人也许会认为斯里基克只是小心谨慎，可他其实也懒得很。他不愿与戈多克大王正面交锋，而是希望凭借陷阱和又老又破的魔法装置，不费吹灰之力地对其造成致命打击。",creatures={[1]="卫兵斯里基克"}},[14325]={name="克罗卡斯",desc="即便是在食人魔当中，克罗卡斯的火爆脾气也是臭名昭著，谁要是胆敢冒犯他或戈多克大王，就绝对没有好果子吃。他凶残地镇压那些与他意见相左的人，不过，总有人乐此不疲地散播他早年与一只豺狼人的热恋绯闻，对于这类造谣生事者，他更没有耐心。",creatures={[1]="克罗卡斯"}},[14324]={name="观察者克鲁什",desc="克鲁什并没有既定立场，但当乌尔洛克掌权后，他的力量显然已经变得不可动摇。国王很快便任命克鲁什担任他的首席顾问，相信他的双头一定能带来令普通食人魔望尘莫及的双倍睿智。",creatures={[1]="观察者克鲁什"}},[11501]={name="戈多克大王",desc="谁要是想统治戈多克食人魔，只须站出来自封为王……然后消灭所有心怀异议的人即可。戈多克大王——当时人称乌尔洛克——就是劝服了十二位族中最为强大的战士，同时挑战国王，以此巩固自己的力量。一场疯狂混战过后，比试者死的死伤的伤，乌尔洛克手起刀落，不费吹灰之力就结果了那些幸存者和被战斗搞得疲累交加的国王。时至今日，每当戈多克食人魔提及“血战之日”时，还是只敢低声窃语。",creatures={[1]="戈多克大王"}},[10436]={name="安娜丝塔丽男爵夫人",desc="安娜丝塔丽在世时，就会为了占有心仪之物不惜任何代价。死亡也没能让她转性。安娜丝塔丽的灵魂被剥离出身体，变成了女妖。她不再追求名贵的饰品，而是将热情倾注在更为邪恶的东西上面。",creatures={[1]="安娜丝塔丽男爵夫人"}},[10437]={name="奈鲁布恩坎",desc="奈鲁布恩坎在蜘蛛大战中是一位可怕的战士。最后，她却因伤势过重而屈服，化身成为不死族，变成了天灾军团听话的爪牙。现在这位蛛魔正在斯坦索姆凶狠地守卫着一座通灵塔，如同用生命捍卫自己的家园。",creatures={[1]="奈鲁布恩坎"}},[10438]={name="苍白的玛勒基",desc="玛勒基是第一批加入诅咒神教的，在应对墓穴的阴寒方面表现出了过人的天资。对力量永无止境的渴求驱使这位法师热忱地磨练自己对黑暗魔法的驾驭能力，时刻准备迎接化身巫妖的那一天。",creatures={[1]="苍白的玛勒基"}},[10435]={name="巴瑟拉斯镇长",desc="巴瑟拉斯是在阿尔萨斯及其军团净化斯坦索姆的行动中惨遭洗劫的众多无辜者之一。巫妖王最终从墓里唤醒了这位昔日的镇长，并命令这只巨大的亡灵怪物守卫他被毁灭的家园。",creatures={[1]="巴瑟拉斯镇长"}},[10439]={name="吞咽者拉姆斯登",desc="拉姆斯登是天灾军团最臭名昭著的憎恶之一，是由许多具尸体缝合而成的可怕怪物，还有着永不满足的食欲。当天灾军团侵入斯坦索姆时，这只怪物对无数无辜者的灵魂犯下了令人发指的暴行。",creatures={[1]="吞咽者拉姆斯登"}},[10917]={name="奥里克斯·瑞文戴尔领主",desc="奥里克斯竟在陡然间一堕千丈。与他遭到腐化的父亲——瑞文戴尔男爵一样，生前是位圣骑士，死后却不得安宁。他悲惨地沦为了天灾军团的工具，为他誓死铲除的邪恶力量效命。",creatures={[1]="奥里克斯·瑞文戴尔领主"}},[12118]={name="鲁西弗隆",creatures={[1]="鲁西弗隆"}},[11982]={name="玛格曼达",creatures={[1]="玛格曼达"}},[12259]={name="基赫纳斯",creatures={[1]="基赫纳斯"}},[12057]={name="加尔",creatures={[1]="加尔"}},[12264]={name="沙斯拉尔",creatures={[1]="沙斯拉尔"}},[12056]={name="迦顿男爵",creatures={[1]="迦顿男爵"}},[12098]={name="萨弗隆先驱者",creatures={[1]="萨弗隆先驱者"}},[11988]={name="焚化者古雷曼格",creatures={[1]="焚化者古雷曼格"}},[12018]={name="管理者埃克索图斯",creatures={[1]="管理者埃克索图斯"}},[11502]={name="拉格纳罗斯",creatures={[1]="拉格纳罗斯"}},[10184]={name="奥妮克希亚",creatures={[1]="奥妮克希亚"}},[12435]={name="狂野的拉佐格尔",creatures={[1]="狂野的拉佐格尔"}},[13020]={name="堕落的瓦拉斯塔兹",creatures={[1]="堕落的瓦拉斯塔兹"}},[12017]={name="勒什雷尔",creatures={[1]="勒什雷尔"}},[11983]={name="费尔默",creatures={[1]="费尔默"}},[14601]={name="埃博诺克",creatures={[1]="埃博诺克"}},[11981]={name="弗莱格尔",creatures={[1]="弗莱格尔"}},[14020]={name="克洛玛古斯",creatures={[1]="克洛玛古斯"}},[11583]={name="奈法利安",creatures={[1]="奈法利安"}},[14507]={name="高阶祭司温诺希斯",creatures={[1]="高阶祭司温诺希斯"}},[14517]={name="高阶祭司耶克里克",creatures={[1]="高阶祭司耶克里克"}},[14510]={name="高阶祭司玛尔里",creatures={[1]="高阶祭司玛尔里"}},[11382]={name="血领主曼多基尔",creatures={[1]="血领主曼多基尔"}},[15114]={name="加兹兰卡",creatures={[1]="加兹兰卡"}},[14509]={name="高阶祭司塞卡尔",creatures={[1]="高阶祭司塞卡尔"}},[14515]={name="高阶祭司娅尔罗",creatures={[1]="高阶祭司娅尔罗"}},[11380]={name="妖术师金度",creatures={[1]="妖术师金度"}},[14834]={name="哈卡",creatures={[1]="哈卡"}},[15082]={name="格里雷克",creatures={[1]="格里雷克"}},[15083]={name="哈扎拉尔",creatures={[1]="哈扎拉尔"}},[15084]={name="雷纳塔基",creatures={[1]="雷纳塔基"}},[15085]={name="乌苏雷",creatures={[1]="乌苏雷"}},[15348]={name="库林纳克斯",creatures={[1]="库林纳克斯"}},[15341]={name="拉贾克斯将军",creatures={[1]="拉贾克斯将军"}},[15340]={name="莫阿姆",creatures={[1]="莫阿姆"}},[15370]={name="吞咽者布鲁",creatures={[1]="吞咽者布鲁"}},[15369]={name="狩猎者阿亚米斯",creatures={[1]="狩猎者阿亚米斯"}},[15339]={name="无疤者奥斯里安",creatures={[1]="无疤者奥斯里安"}},[15263]={name="预言者斯克拉姆",creatures={[1]="预言者斯克拉姆"}},[15511]={name="安其拉三宝",creatures={[1]="安其拉三宝"}},[15516]={name="沙尔图拉",creatures={[1]="沙尔图拉"}},[15510]={name="顽强的范克瑞斯",creatures={[1]="顽强的范克瑞斯"}},[15299]={name="维希度斯",creatures={[1]="维希度斯"}},[15509]={name="哈霍兰公主",creatures={[1]="哈霍兰公主"}},[15276]={name="双子皇帝",creatures={[1]="双子皇帝"}},[15517]={name="奥罗",creatures={[1]="奥罗"}},[15727]={name="克苏恩",creatures={[1]="克苏恩"}},[15956]={name="阿努布雷坎",creatures={[1]="阿努布雷坎"}},[15953]={name="黑女巫法琳娜",creatures={[1]="黑女巫法琳娜"}},[15952]={name="迈克斯纳",creatures={[1]="迈克斯纳"}},[15954]={name="药剂师诺斯",creatures={[1]="药剂师诺斯"}},[15936]={name="肮脏的希尔盖",creatures={[1]="肮脏的希尔盖"}},[16011]={name="洛欧塞布",creatures={[1]="洛欧塞布"}},[16061]={name="教官拉苏维奥斯",creatures={[1]="教官拉苏维奥斯"}},[16060]={name="收割者戈提克",creatures={[1]="收割者戈提克"}},[16065]={name="天启四骑士",creatures={[1]="天启四骑士"}},[16028]={name="帕奇维克",desc="帕奇维克要跟你玩！",creatures={[1]="帕奇维克"}},[15931]={name="格罗布鲁斯",creatures={[1]="格罗布鲁斯"}},[15932]={name="格拉斯",creatures={[1]="格拉斯"}},[15928]={name="塔迪乌斯",creatures={[1]="塔迪乌斯"}},[15989]={name="萨菲隆",creatures={[1]="萨菲隆"}},[15990]={name="克尔苏加德",creatures={[1]="克尔苏加德"}}},
sections={[11517001]={title="顺劈斩",text="奥格弗林特挥舞武器划出一道宽阔的弧线，对其前方的所有敌人造成额外的物理伤害。"},[11520002]={title="上钩拳",text="塔拉加曼施展一记凶猛的上钩拳，造成大量物理伤害并将目标击退。"},[11520001]={title="火焰新星",text="塔拉加曼爆发出一圈火焰新星，对附近的所有敌人造成火焰伤害。"},[11518002]={title="虚弱诅咒",text="耶戈什用虚弱诅咒他的目标，降低其造成的物理伤害。"},[11518001]={title="献祭",text="耶戈什用火焰吞没一名敌人，立即造成火焰伤害，并在一段时间内造成额外的火焰伤害。"},[11519002]={title="毒药",text="巴扎兰的刀刃上涂有毒药，对被他击中的目标造成持续的自然伤害。"},[11519001]={title="邪恶攻击",text="巴扎兰发动一次邪恶攻击，造成额外的物理伤害。"},[4957]={title="治疗之触",text="安娜科德拉治疗一名盟友。"},[4956]={title="荆棘光环",text="安娜科德拉的荆棘对所有近战攻击她的玩家造成自然伤害。"},[4955]={title="德鲁伊的睡眠",text="安娜科德拉催眠一名玩家，持续15秒。任何伤害行为都将唤醒目标。"},[4954]={title="闪电箭",text="安娜科德拉对当前目标射出一支闪电箭，对其造成自然伤害。"},[4968]={title="雷霆一击",text="皮萨斯对10码范围内的所有玩家造成自然伤害，使其攻击间隔延长43%，并降低其移动速度，持续10秒。"},[4967]={title="治疗之触",text="皮萨斯治疗一名盟友。"},[4966]={title="德鲁伊的睡眠",text="皮萨斯催眠一名玩家，持续15秒。任何伤害行为都将唤醒目标。"},[4965]={title="闪电箭",text="皮萨斯对当前目标射出一支闪电箭，对其造成自然伤害。"},[4962]={title="考布莱恩：毒蛇",text="当考布莱恩的生命值降至45%时，他将会变成一条毒蛇。"},[4964]={title="中毒",text="考布莱恩使一名玩家中毒，每3秒对其造成一次自然伤害，持续30秒。"},[4963]={title="毒蛇形态",text="考布莱恩变成一条毒蛇，近战伤害提高50点，但攻击间隔延长43%。"},[4958]={title="考布莱恩：毒牙之王",text="考布莱恩以暗夜精灵形态迎战敌人，以验证其战斗能力。"},[4961]={title="治疗之触",text="考布莱恩治疗一名盟友。"},[4960]={title="德鲁伊的睡眠",text="考布莱恩催眠一名玩家，持续15秒。任何伤害行为都将唤醒目标。"},[4959]={title="闪电箭",text="考布莱恩对当前目标射出一支闪电箭，对其造成自然伤害。"},[4969]={title="毁灭撕咬",text="克雷什撕咬当前目标，降低其护甲值。"},[4970]={title="闪电链",text="斯卡姆用闪电箭攻击一名玩家，其在击中目标后继续弹射向附近的其他玩家，造成自然伤害。闪电链的最大影响范围为3码。"},[4973]={title="治疗之触",text="瑟芬迪斯治疗一名盟友。"},[4972]={title="德鲁伊的睡眠",text="瑟芬迪斯催眠一名玩家，持续15秒。任何伤害行为都将唤醒目标。"},[4971]={title="闪电箭",text="瑟芬迪斯对当前目标射出一支闪电箭，对其造成自然伤害。"},[4974]={title="缠绕之藤",text="永生者沃尔丹用藤蔓缠住10码范围内的所有玩家，造成物理伤害，将其击倒，并使其无法移动，持续10秒。"},[4977]={title="雷霆震裂",text="吞噬者穆坦努斯对10码范围内的所有玩家造成自然伤害，使其昏迷2.5秒。"},[4976]={title="恐吓",text="吞噬者穆坦努斯恐吓一名玩家，使其因恐惧而逃跑，持续4秒。"},[4975]={title="纳拉雷克斯的梦魇",text="吞噬者穆坦努斯催眠一名玩家，持续15秒。任何敌对行动都将唤醒目标。"},[29777]={title="旋风斩",text="拉克佐进入旋转狂暴状态，像旋风一般攻击附近的敌人。在狂暴期间，拉克佐对附近敌人造成物理伤害并将其击退。"},[29112]={title="拉克佐猛击",text="拉克佐野蛮地重殴当前目标，造成64到86点物理伤害并使其昏迷3秒。"},[29804]={title="斯尼德",text="一旦伐木机被摧毁，斯尼德就会亲自上阵解决问题。"},[29805]={title="缴械",text="斯尼德缴械其目标，使其在6秒内无法使用武器。"},[29778]={title="斯尼德的伐木机",text="斯尼德驾驶着一台致命的伐木机。"},[29802]={title="顺劈斩",text="斯尼德用他的伐木机划出一道巨大的弧线，对其前方的目标造成物理伤害。"},[29803]={title="扰乱之痛",text="斯尼德向目标发射一枚锋利的刀片，造成物理伤害并使其急速降低35%，持续15秒。"},[29801]={title="惊骇",text="斯尼德恐吓一名敌人，使其惊慌地逃跑，持续4秒。"},[29809]={title="召唤遥控傀儡",text="基尔尼格呼唤工人魔像攻击一个随机目标。"},[29812]={title="遥控傀儡",text="该傀儡会随机攻击一个目标，并无视嘲讽。"},[29808]={title="熔化矿石",text="基尔尼格用熔火矿石覆盖附近的敌人，每1秒造成7点火焰伤害，并使其移动速度降低40%，持续20秒。该效果可叠加。"},[29807]={title="熔铁之水",text="基尔尼格投掷熔融金属，每3秒对一名敌人造成火焰伤害，使其攻击间隔时间延长54%，移动速度降低50%，持续15秒。"},[29813]={title="现在我生气了",text="当生命值降至35%时，重拳先生会重踏地面使所有玩家昏迷，随后装备上他强大的锤子，使其伤害输出提升，但攻击速度降低50%。"},[29825]={title="手枪射击",text="重拳先生用手枪射击一个远处的目标，造成物理伤害。"},[29827]={title="重拳猛击",text="重拳先生挥下巨锤砸向当前目标，造成50点物理伤害，并使目标昏迷3秒。"},[29823]={title="我得随机应变",text="当生命值降至70%时，重拳先生会重踏地面使所有玩家昏迷。随后他双手各装备一把斧子，使其造成的伤害提高并获得额外攻击次数。"},[29826]={title="手枪射击",text="重拳先生用手枪射击一个远处的目标，造成物理伤害。"},[29818]={title="我们决斗吧",text="重拳先生装备好了他的盗贼之刃，准备与入侵者决斗。"},[29822]={title="手枪射击",text="重拳先生用手枪射击一个远处的目标，造成物理伤害。"},[29821]={title="迅捷反射",text="在近战时，重拳先生有几率使招架几率提升75%，持续8秒。"},[29830]={title="手枪射击",text="绿皮用手枪射击一个远处的目标，造成物理伤害。"},[29829]={title="顺劈斩",text="绿皮对其前方的敌人造成物理伤害。"},[29828]={title="毒性鱼叉",text="绿皮向其目标投掷一支浸毒鱼叉，造成自然伤害，并在之后的1分钟内持续造成伤害。"},[29834]={title="范克里夫的盟友",text="当生命值降至50%时，范克里夫会呼唤附近潜伏在阴影中的暴徒前来援助。"},[29835]={title="迪菲亚恶棍",text="范克里夫的暴徒会围攻任何反对兄弟会的人。"},[29831]={title="破裂",text="黑卫刺向其目标，在10秒内每2秒造成15点物理伤害。"},[29832]={title="暗影步",text="范克里夫潜入暗影，在一名随机敌人身后重新出现并对其进行背刺。范克里夫会锁定其目标。"},[29836]={title="破裂",text="范克里夫刺向其目标，每2秒造成15点物理伤害，持续10秒。"},[29839]={title="酸液溅射",text="曲奇向他的目标丢出一瓶毒药，每5秒对其造成自然伤害，持续30秒。"},[29837]={title="烹制甜点",text="曲奇喝了一口昨天的汤，恢复了部分生命值。"},[3914001]={title="灵魂消耗",text="雷希戈尔吸取当前目标的灵魂，汲取其生命并使其被定身10秒。"},[3886001]={title="屠夫吸取",text="拉佐克劳以凶残的攻击屠戮敌人，吸取他们的活力，并按自身造成伤害的一定比例为自己恢复生命值。"},[3887001]={title="暗影迷雾",text="席瓦莱恩男爵用暗影之雾笼罩一名玩家，使其受到的所有治疗效果降低75%，持续15秒。"},[4278002]={title="制裁之锤",text="指挥官斯普林瓦尔以正义之力重击当前目标，使其昏迷4秒。"},[4278001]={title="圣光术",text="指挥官斯普林瓦尔引导圣光，为自己或一名受伤的盟友恢复大量生命值。"},[4279001]={title="嚎叫之怒",text="当奥杜受伤时——生命值降至75%、50%和25%时——他会陷入嚎叫之怒，体型变大并提高其造成的伤害。每达到一个阈值，狂乱都会加剧。"},[4274001]={title="毒性唾液",text="芬鲁斯将毒性唾液涂满一名玩家全身，每6秒造成自然伤害，持续2分钟。"},[3927001]={title="狼群的召唤",text="狼王南杜斯召唤他的狼群前来助战，先后唤出灰色座狼、被奴役的座狼，最后是一只暗牙恐狼，以压倒入侵者。"},[4275004]={title="暗影传送",text="在整场战斗中，阿鲁高会在一阵暗影漩涡中消失，然后出现在房间中的另一个有利位置，调整站位后继续发起攻击。"},[4275003]={title="雷霆震荡",text="阿鲁高在自身周围释放自然能量冲击，造成自然伤害，击退附近的玩家并使其昏迷5秒。"},[4275002]={title="阿鲁高的诅咒",text="阿鲁高诅咒一名玩家，将其变成受他控制的影牙暴食者，持续10秒。"},[4275001]={title="虚空箭",text="阿鲁高向目标投掷一支虚空能量箭，造成大量暗影伤害。"},[4887001]={title="践踏",text="加摩拉践踏周围的敌人，对附近的所有敌人造成物理伤害。"},[4831003]={title="减速术",text="萨利维丝使一名敌人减速，降低其攻击速度和移动速度。"},[4831002]={title="冰霜新星",text="萨利维丝以冰霜冲击附近的敌人，将其冻结在原地一小段时间。"},[4831001]={title="叉状闪电",text="萨利维丝施放叉状闪电，对她面前锥形区域内的敌人造成自然伤害。"},[6243001]={title="投网",text="格里哈斯特用网缠住一名敌人，使其被定身在原地，无法逃脱。"},[4832002]={title="心灵震爆",text="克尔里斯攻击一名玩家的心灵，造成暗影伤害。"},[4832001]={title="催眠术",text="梦游者克尔里斯使附近的敌人陷入沉睡，使其失去行动能力，直到受到伤害时才会醒来。"},[4830001]={title="吸血脉冲",text="瑟拉吉斯释放出吸取能量的脉冲，吸取附近敌人的生命来治疗自己。"},[4829002]={title="狂暴怒气",text="阿库麦尔陷入狂暴的怒火之中，提高其攻击速度和造成的伤害。"},[4829001]={title="毒云术",text="阿库麦尔喷出一团毒云，对其中的所有敌人造成持续的自然伤害。"},[6476]={title="咀嚼者",text="咀嚼者与格鲁比斯并肩作战。"},[4690]={title="打击",text="格鲁比斯对当前目标造成物理伤害。"},[4691]={title="毒性箭雨",text="粘性辐射尘射出一阵毒性箭雨，对45码范围内的所有玩家造成56点自然伤害，并在接下来的15秒内每3秒造成7点自然伤害。"},[4694]={title="闪电链",text="电刑器6000型用闪电箭攻击当前目标，其在击中目标后继续弹射向附近的3个目标，对每个目标造成自然伤害。"},[4693]={title="震击",text="电刑器6000型向当前目标射出一支闪电箭，造成自然伤害。"},[4692]={title="百万伏特",text="电刑器6000型对其面前的所有玩家造成自然伤害。"},[4672]={title="践踏",text="群体打击者9-60践踏10码范围内的玩家，造成物理伤害。"},[4671]={title="群体打击",text="群体打击者9-60拳击10码范围内的玩家，造成物理伤害，并打断其施法，持续5秒。"},[4670]={title="圆弧斩",text="群体打击者9-60划出一道致命的剑弧，对其面前的玩家造成物理伤害。"},[4700]={title="步行炸弹",text="机械师瑟玛普拉格激活了附近的一个炸弹套件，使其周期性地释放步行炸弹，随机攻击一名玩家。在激活炸弹套件另一侧的红色开关之前，它会不断发射步行炸弹。"},[4701]={title="爆炸",text="步行炸弹触及目标时会爆炸，对10码范围内的所有玩家造成200到300点火焰伤害。"},[4704]={title="烧灼电流",text="机械师瑟玛普拉格用烧灼电流冲击当前目标，造成250点自然伤害。"},[4703]={title="重击",text="机械师瑟玛普拉格重击其当前目标，造成物理伤害，并使其陷入迷惑。"},[4702]={title="蒸汽冲击",text="机械师瑟玛普拉格用蒸汽冲击当前目标，造成火焰伤害，并将其击退。"},[1696002]={title="狂怒",text="当生命值降至30%以下时，塔格尔会进入激怒状态，大幅提高其造成的伤害。"},[1696001]={title="痛击",text="塔格尔疯狂地痛击，获得额外的近战攻击。"},[1666001]={title="盾牌猛击",text="卡姆·深怒用盾牌猛击目标，造成物理伤害并使其短暂昏迷。"},[1717002]={title="嗜血术",text="哈姆霍克进入嗜血状态，提高其攻击速度。"},[1717001]={title="闪电链",text="哈姆霍克释放一道在附近敌人之间弹跳的闪电，造成自然伤害。"},[1716002]={title="战斗怒吼",text="巴基尔·斯瑞德发出战斗怒吼，提高附近盟友的攻击强度。"},[1716001]={title="烟雾弹",text="巴基尔·斯瑞德投掷一枚烟雾弹，令人窒息的烟雾使附近的敌人昏迷。"},[1663002]={title="破胆怒吼",text="迪克斯特·瓦德发出破胆怒吼，使附近的玩家因恐惧而逃跑。"},[1663001]={title="打击",text="迪克斯特·瓦德发动一次强力打击，造成额外的物理伤害。"},[6168002]={title="召唤地行者",text="鲁古格召唤一个地行者为其作战。"},[6168001]={title="闪电箭",text="鲁古格向目标投掷一支闪电箭，造成自然伤害。"},[4424003]={title="战斗怒吼",text="阿格姆以战斗怒吼鼓舞盟友，提高其攻击强度。"},[4424002]={title="召唤野猪之魂",text="阿格姆召唤一个野猪之魂协助他作战。"},[4424001]={title="治疗链",text="阿格姆召唤自然之力治疗自己和附近的盟友，治疗能量会在目标之间跳跃。"},[4428002]={title="暗影箭",text="亡语者贾格巴投掷一支暗影箭，造成暗影伤害。"},[4428001]={title="统御意志",text="亡语者贾格巴支配一名玩家的意志，控制该玩家并使其攻击自己的盟友。"},[4420002]={title="战斗怒吼",text="主宰拉姆塔斯以战斗怒吼激励他的战队，提高其攻击强度。"},[4420001]={title="雷霆一击",text="主宰拉姆塔斯猛击地面，对附近的敌人造成自然伤害并降低其攻击速度。"},[4422003]={title="狂怒",text="阿迦赛罗斯进入激怒状态，提高其造成的伤害。"},[4422002]={title="暴跳如雷",text="阿迦赛罗斯横冲直撞，以一连串沉重的物理打击猛击目标。"},[4422001]={title="急速冲锋",text="阿迦赛罗斯冲向远处的一名敌人，冲撞对方并造成物理伤害。"},[4421003]={title="法力之矛",text="当法力值不足时，卡尔加会对一名玩家释放一道能量尖刺，造成神圣伤害。"},[4421002]={title="恢复",text="卡尔加对自己或一名受伤的盟友施放恢复，持续恢复生命值。"},[4421001]={title="闪电链",text="卡尔加释放一道在附近敌人之间弹跳的闪电，造成自然伤害。"},[3983001]={title="献祭",text="审讯员韦沙斯用献祭灼烧他的受害者，使其被火焰吞没，持续受到火焰伤害。"},[4543002]={title="烈焰尖刺",text="血法师萨尔诺斯召唤出一道烈焰尖刺，对区域内的所有敌人造成火焰伤害。"},[4543001]={title="暗影箭雨",text="血法师萨尔诺斯释放一阵暗影箭雨，对附近的所有敌人造成暗影伤害。"},[3974002]={title="战斗怒吼",text="驯犬者洛克希以战斗怒吼激励他的猎犬，提高其攻击强度。"},[3974001]={title="嗜血术",text="驯犬者洛克希激发猎犬的嗜血之心，提高其攻击速度。"},[6487004]={title="魔爆术",text="奥法师杜安释放一股奥术能量，对附近的所有敌人造成奥术伤害。"},[6487003]={title="沉默",text="奥法师杜安使附近的施法者沉默，使其在数秒内无法施法。"},[6487002]={title="变形术",text="奥法师杜安将一名玩家变形为无害的生物，使其无法参与战斗，直到效果被打破。"},[6487001]={title="自爆",text="奥法师杜安用奥术护罩包围自己，并引导一次覆盖整个房间的强力爆炸，对所有人造成大量奥术伤害。躲到柱子后面才能幸存。"},[3975004]={title="狂乱",text="受伤后，赫洛德会陷入狂乱，大幅提高其攻击速度。"},[3975003]={title="顺劈斩",text="赫洛德对其前方的所有敌人发动顺劈斩，造成大量物理伤害。"},[3975002]={title="急速冲锋",text="赫洛德冲向远处的目标，迅速拉近距离并对其造成物理伤害。"},[3975001]={title="旋风斩",text="赫洛德旋转形成致命的旋风，对附近的所有敌人造成大量物理伤害。"},[3976002]={title="制裁之锤",text="莫格莱尼以正义之力重击目标，使其短暂昏迷。"},[3976001]={title="十字军打击",text="莫格莱尼用强力的十字军打击重击目标，造成大量神圣和物理伤害。"},[3977004]={title="圣光击",text="怀特迈恩以圣光之力惩击一名敌人，造成神圣伤害。"},[3977003]={title="治疗术",text="怀特迈恩引导一次强力的治疗，为自己或莫格莱尼恢复生命值。"},[3977002]={title="深度睡眠",text="怀特迈恩使整个小队陷入深度睡眠，趁他们失去行动能力时复活她倒下的指挥官。"},[3977001]={title="血色复活",text="当血色十字军指挥官莫格莱尼倒下时，怀特迈恩会复活他，让她的指挥官重返战斗并再次发起攻击。"},[4542005]={title="真言术：盾",text="当生命值低于25%时，法尔班克斯会用圣光护住自己，吸收部分受到的伤害。"},[4542004]={title="治疗术",text="当生命值低于30%时，法尔班克斯会引导一次强力的治疗来恢复自己的生命值。"},[4542003]={title="恐惧术",text="法尔班克斯使附近的玩家陷入恐惧，令其惊恐逃跑。"},[4542002]={title="催眠术",text="法尔班克斯使一名敌人陷入沉睡，使其失去行动能力，直到受到伤害为止。"},[4542001]={title="血之诅咒",text="法尔班克斯诅咒一名玩家的血液，使其受到的物理伤害提高。"},[4821]={title="闪电箭",text="鲁维罗什用闪电冲击当前目标，对其造成自然伤害。"},[4820]={title="闪电链",text="鲁维罗什用闪电箭攻击一名玩家，其在击中目标后继续弹射向附近玩家，对3个目标造成自然伤害。"},[4872]={title="奥拉夫",text="奥拉夫喜欢防御，用他的盾牌格挡。"},[4873]={title="盾牌猛击",text="奥拉夫猛击目标，造成物理伤害，并使其昏迷2秒。"},[4874]={title="迅捷的埃瑞克",text="埃瑞克喜欢速度，一马当前冲入战场。"},[4875]={title="急速冲锋",text="迅捷的埃瑞克向一名玩家冲锋，提高其下次攻击造成的伤害。"},[4869]={title="巴尔洛戈",text="巴尔洛戈喜欢战斗，用他的剑和弓发动攻击。"},[4871]={title="射击",text="巴尔洛戈向一名玩家射击，造成物理伤害。"},[4870]={title="打击",text="巴尔洛戈打击当前目标，造成物理伤害。"},[4878]={title="战争践踏",text="艾隆纳亚践踏大地，对5码范围内的所有敌人造成物理伤害，并使其昏迷5秒。"},[4877]={title="击退",text="艾隆纳亚对当前目标造成物理伤害，并将其击退。"},[4876]={title="圆弧斩",text="艾隆纳亚划出一道致命的剑弧，对其面前的所有敌人造成物理伤害。"},[4879]={title="沙尘风暴",text="远古巨石卫士召唤一阵沙尘风暴，向一名玩家移动，对5码范围内的所有玩家造成物理伤害并降低其移动速度。"},[4883]={title="暗炉地质学家",text="暗炉地质学家保护加加恩·火锤，并协助其战斗。"},[4885]={title="烈焰鞭笞",text="暗炉地质学家燃烧一名玩家，造成火焰伤害，并使其火焰抗性降低，持续45秒。该效果最多可叠加3次。"},[4884]={title="烈焰之刺",text="暗炉地质学家召唤一根火柱，对目标区域附近5码范围内的所有玩家造成火焰伤害，并在接下来的9秒内每3秒造成一次额外火焰伤害。"},[4882]={title="火焰增效",text="加加恩·火锤使当前目标受到的火焰伤害提高，持续30秒。"},[4881]={title="烈焰鞭笞",text="加加恩·火锤燃烧一名玩家，造成火焰伤害，并使其火焰抗性降低，持续45秒。该效果最多可叠加3次。"},[4880]={title="火焰新星",text="加加恩·火锤对10码范围内的所有玩家造成火焰伤害。"},[4891]={title="玉脊蜥蜴",text="格瑞姆洛克有宠物玉脊蜥蜴帮他战斗。"},[4893]={title="水晶沉睡",text="玉脊蜥蜴对一名玩家造成奥术伤害并使其昏迷15秒。"},[4892]={title="反射",text="玉脊蜥蜴的皮肤闪闪发光，使其有一定几率将有害法术反射回施法者身上，持续5秒。"},[4889]={title="缩小",text="格瑞姆洛克使5码范围内的所有玩家缩小，并使其力量和耐力降低，持续2分钟。"},[4888]={title="嗜血",text="格瑞姆洛克使一位盟友的攻击速度提高30%，持续30秒。"},[4887]={title="闪电箭",text="格瑞姆洛克用闪电冲击当前目标，对其造成自然伤害。"},[4886]={title="闪电链",text="格瑞姆洛克用闪电箭攻击目标，其在击中目标后继续弹射向附近玩家，对3个目标造成自然伤害。"},[4902]={title="大地震颤",text="阿扎达斯震撼大地，使20码范围内的所有敌人昏迷。"},[4899]={title="唤醒宝库护卫者",text="当阿扎达斯的生命值降至33%时，他将会唤醒2个宝库护卫者。"},[4900]={title="宝库护卫者"},[4901]={title="践踏",text="宝库护卫者对10码范围内的所有敌人造成物理伤害。"},[4896]={title="唤醒土灵守护者",text="当阿扎达斯的生命值降至66%时，他将唤醒6个土灵守护者。"},[4897]={title="土灵守护者"},[4898]={title="旋风斩",text="土灵守护者使用旋风斩，对8码范围内的所有敌人造成物理伤害。"},[4894]={title="唤醒土灵矮人",text="阿扎达斯每10秒唤醒一个土灵管理者协助其战斗。"},[4895]={title="土灵管理者",text="土灵管理者为阿扎达斯作战。"},[7355003]={title="恶性毒药",text="图特卡什的撕咬带有恶性毒药，造成持续的自然伤害。"},[7355002]={title="撒网",text="图特卡什向附近的敌人喷射蛛网，使其被定身在原地。"},[7355001]={title="图特卡什的诅咒",text="图特卡什诅咒一名玩家，降低其受到的治疗效果。"},[7357002]={title="火焰新星",text="莫德雷斯爆发出一圈火焰新星，对附近的所有敌人造成火焰伤害。"},[7357001]={title="火球术",text="莫德雷斯向目标投掷一枚火球，造成火焰伤害。"},[8567003]={title="狂乱",text="当生命值低于15%时，暴食者会陷入狂乱，攻击速度大幅提高。"},[8567002]={title="痛击",text="暴食者发动痛击，获得额外的近战攻击。"},[8567001]={title="疾病之云",text="暴食者散发出一团疾病之云，对附近的敌人造成持续的自然伤害。"},[7356002]={title="枯萎之触",text="普雷莫尔的触碰使受害者枯萎，吸取其法力值。"},[7356001]={title="腐烂恶臭",text="普雷莫尔散发出腐烂恶臭，用腐烂疾病削弱附近的敌人。"},[7354004]={title="治疗术",text="拉戈斯诺特引导一次治疗，治愈自己或一名盟友的伤口。"},[7354003]={title="暗言术：痛",text="拉戈斯诺特使一名玩家承受灼烧般的痛苦，造成持续的暗影伤害。"},[7354002]={title="暗影箭",text="拉戈斯诺特投掷一支暗影箭，造成暗影伤害。"},[7354001]={title="统御意志",text="拉戈斯诺特支配一名玩家的意志，在一段时间内控制该玩家。"},[7358003]={title="霜甲术",text="亚门纳尔以霜甲术环绕自身，冰冻并减速对其进行近战攻击的敌人。"},[7358002]={title="召唤冰霜亡魂",text="当生命值降至66%时，亚门纳尔会召唤两个冰霜亡魂攻击他的敌人。"},[7358001]={title="亚门纳尔之怒",text="亚门纳尔对一名敌人释放他的怒火，造成冰霜伤害。"},[4711]={title="召唤诺克赛恩产物",text="诺克赛恩的身体分裂成5个诺克赛恩产物，使其无法战斗，最多持续20秒。一旦5个诺克赛恩产物全部被杀死，诺克赛恩就会恢复原始形态。"},[4712]={title="诺克赛恩产物",text="诺克赛恩产物从诺克赛恩的主体上分裂出去。"},[4710]={title="上钩拳",text="诺克赛恩使用上钩拳攻击当前目标，造成物理伤害，并将其击退。"},[4709]={title="毒性箭雨",text="诺克赛恩射出一阵毒性箭雨，立即对45码范围内的所有玩家造成自然伤害，并在接下来的15秒内每3秒造成一次额外的自然伤害。"},[4715]={title="顺劈斩",text="锐刺鞭笞者发动顺劈斩，对当前目标及离其最近的盟友造成物理伤害。"},[4714]={title="痛击",text="锐刺鞭笞者痛击当前目标，额外发动2次攻击。"},[4713]={title="刺破",text="锐刺鞭笞者刺破当前目标，每2秒造成一次物理伤害，持续10秒。"},[4724]={title="射击",text="工匠吉兹洛克随机向一名玩家射击，造成物理伤害。"},[4723]={title="闪光炸弹",text="工匠吉兹洛克投掷一个闪光炸弹，使5码范围内的所有野兽逃跑。"},[4722]={title="地精龙枪",text="工匠吉兹洛克用地精龙枪射击，对面前的所有玩家造成140点火焰伤害，持续8秒。"},[4721]={title="炸弹",text="工匠吉兹洛克随机向一名玩家投掷炸弹，对5码范围内的所有玩家造成火焰伤害。"},[4733]={title="烟雾弹",text="维利塔恩投掷一个烟雾弹，使5码范围内的所有玩家昏迷。"},[4732]={title="闪现",text="维利塔恩将自己传送至正前方20码的位置。"},[4731]={title="多重射击",text="维利塔恩随机向一名玩家连续射击，对该玩家及其附近的盟友造成奥术伤害，最多可以影响5个目标。"},[4730]={title="射击",text="维利塔恩随机向一名玩家射击，造成物理伤害。"},[4748]={title="纠缠根须",text="被诅咒的塞雷布拉斯缠绕当前目标，使其无法移动，并在接下来的10秒内每3秒造成一次自然伤害。"},[4747]={title="愤怒",text="被诅咒的塞雷布拉斯向当前目标射出一支能量箭，造成自然伤害。"},[4746]={title="扭曲宁静",text="被诅咒的塞雷布拉斯对45码范围内的所有玩家造成自然伤害，使其移动速度降低70%，并使其攻击间隔延长300%。"},[4745]={title="腐化的自然之力",text="被诅咒的塞雷布拉斯召唤3个腐化的自然之力来协助自己作战，持续1分钟。"},[6459]={title="腐化的自然之力",text="腐化的自然之力在战斗中将保护被诅咒的塞雷布拉斯。"},[4750]={title="兰斯利德",text="兰斯利德使100码范围内的所有玩家昏迷8秒，并每2秒召唤一个瑟莱德丝碎片。"},[6460]={title="瑟莱德丝碎片"},[6461]={title="打击",text="瑟莱德丝碎片打击玩家，造成物理伤害。"},[4751]={title="践踏",text="兰斯利德践踏10码范围内的所有玩家，造成物理伤害。"},[4749]={title="击退",text="兰斯利德对当前目标造成物理伤害，并将其击退。"},[4758]={title="致命撕咬",text="洛特格里普撕咬当前目标，造成物理伤害，并为自己恢复生命值，数值相当于其两倍的伤害量。"},[4757]={title="刺破",text="洛特格里普穿刺当前目标，每2秒造成一次物理伤害，持续10秒。"},[4762]={title="灰尘力场",text="瑟莱德丝公主震动大地，对20码范围内的所有玩家造成自然伤害，并将其击退。"},[4761]={title="投石",text="瑟莱德丝公主随机向一名玩家投掷巨石，造成物理伤害，打断施法并使其昏迷2秒。"},[4760]={title="憎恨怒视",text="瑟莱德丝公主凝视当前目标，使8码范围内的所有玩家感到恐惧，持续8秒。"},[4759]={title="痛击",text="瑟莱德丝公主痛击对手，额外发动2次攻击。"},[29864]={title="殉难诅咒",text="塞卡诅咒一个随机目标，将其变成一只圣甲虫，并敲响残害丧钟，吸引附近圣甲虫的注意。"},[29863]={title="暗言术：痛",text="塞卡念诵黑暗的咒语，每3秒对敌人造成48点暗影伤害，持续18秒。"},[29862]={title="暗影箭雨",text="塞卡向附近敌人射出多支黑暗魔法箭，造成128到172点暗影伤害。"},[5006]={title="暗影变形",text="当生命值降至30%时，殉教者塞卡变形，物理和暗影抗性提高，持续30秒。"},[5005]={title="热疫",text="殉教者塞卡使一名玩家感染疾病，对其造成自然伤害，并在3分钟内每5秒造成额外伤害。"},[4980]={title="碎浪",text="水占师维蕾萨召唤一场台风，对自身前方所有玩家造成冰霜伤害，并将其击退。"},[4979]={title="水箭",text="水占师维蕾萨对一名玩家发射一枚水箭，造成冰霜伤害。"},[4978]={title="治疗波",text="水占师维蕾萨为一名盟友恢复694到806点生命值。"},[4992]={title="安图苏尔的仆从",text="当生命值降至75%和25%时，安图苏尔召唤一个安图苏尔的仆从协助自己作战。"},[4993]={title="石化",text="安图苏尔的仆从使一名玩家昏迷8秒，但使其护甲值提高30%。"},[4991]={title="安图苏尔的治疗波",text="当生命值降至25%时，安图苏尔会为自己恢复生命值。"},[4990]={title="闪电链",text="安图苏尔以闪电箭攻击一名敌人，闪电箭会弹射到附近其他玩家身上，造成185到215点自然伤害，最多可跳跃到附近的3名敌人身上。"},[4989]={title="大地震击",text="安图苏尔震击一名玩家，对其造成164到180点自然伤害，并打断施法，持续2秒。"},[4988]={title="陷地图腾",text="安图苏尔在身边召唤一个陷地图腾，持续存在30秒。陷地图腾每5秒使10码范围内的所有玩家无法移动，效果持续4秒，直到被摧毁。"},[4987]={title="治疗结界",text="安图苏尔在脚下召唤一个强效治疗结界，持续30秒。强效治疗结界每3秒为10码范围内安图苏尔的所有盟友恢复生命值，直到被摧毁。"},[4986]={title="治疗波",text="安图苏尔为盟友恢复694到806点生命值。"},[5017]={title="暗影箭雨",text="巫医祖穆拉恩投掷黑暗魔法飞弹，对30码内的所有玩家造成128到172点暗影伤害。"},[5016]={title="暗影箭",text="巫医祖穆拉恩向一名玩家发射一股黑暗魔法，造成128到172点暗影伤害。"},[5015]={title="治疗波",text="巫医祖穆拉恩为盟友恢复694到806点生命值。"},[5013]={title="祖穆拉恩结界",text="巫医祖穆拉恩在身边召唤一个祖穆拉恩结界，持续20秒。祖穆拉恩结界每5秒召唤一个祖穆拉恩骷髅。"},[5014]={title="祖穆拉恩骷髅",text="祖穆拉恩骷髅为巫医祖穆拉恩作战。"},[5011]={title="唤醒祖尔法拉克僵尸",text="巫医祖穆拉恩从附近坟墓里复活一个祖尔法拉克僵尸。"},[5012]={title="祖尔法拉克僵尸",text="祖尔法拉克僵尸从坟墓里复活，为巫医祖穆拉恩作战。"},[4983]={title="加兹瑞拉猛击",text="加兹瑞拉践踏地面，对20码内的所有玩家造成物理伤害并将其击飞。"},[4982]={title="冰霜凝固",text="加兹瑞拉冻结一名玩家，使其昏迷，并且每3秒对其造成冰霜伤害，持续10秒。"},[4981]={title="冰刺",text="加兹瑞拉发射一支寒冰箭，对一名随机玩家造成冰霜伤害，并使其移动速度降低50%，持续10秒。"},[5020]={title="暗影祭司塞瑟斯"},[5024]={title="治疗",text="暗影祭司塞瑟斯为盟友恢复590到684点生命值。"},[5023]={title="恢复",text="暗影祭司塞瑟斯对一个盟友施放恢复，每3秒为其恢复一部分生命值，持续20秒。"},[5022]={title="心灵尖啸",text="暗影祭司塞瑟斯发出一声心灵尖啸，使8码范围内的所有玩家逃跑，持续6秒。"},[5021]={title="暗影箭",text="暗影祭司塞瑟斯向一名玩家发射一股黑暗魔法，造成128到172点暗影伤害。"},[5019]={title="耐克鲁姆"},[29720]={title="顺劈斩",text="耐克鲁姆对其前方的敌人造成物理伤害。"},[5018]={title="热疫",text="耐克鲁姆使一名玩家感染疾病，对其造成自然伤害，并在3分钟内每5秒造成额外伤害。"},[29882]={title="卢兹鲁"},[29884]={title="激怒",text="当乌克兹酋长死亡时，卢兹鲁陷入狂怒，使其伤害输出和攻击速度提高。"},[29887]={title="顺劈斩",text="卢兹鲁对其前方最多2名敌人造成物理伤害。"},[29886]={title="斩杀",text="卢兹鲁试图终结一名受伤的敌人，他可对生命值低于20%的目标造成巨大的物理伤害。"},[29888]={title="乌克兹·沙顶"},[29885]={title="激怒",text="当卢兹鲁死亡时，乌克兹酋长陷入狂怒，使其伤害输出和攻击速度提高。"},[5027]={title="狂乱",text="乌克兹·沙顶进入狂乱状态，攻击速度提高，持续2分钟。"},[5026]={title="顺劈斩",text="乌克兹·沙顶对其前方的敌人造成物理伤害。"},[5025]={title="挥砍",text="乌克兹·沙顶对面前的所有玩家造成物理伤害。"},[10506003]={title="飞扑",text="基尔图诺斯向目标俯冲，造成物理伤害并使其短暂昏迷。"},[10506002]={title="龙翼攻击",text="基尔图诺斯用双翼拍击前方区域，造成物理伤害并击退玩家。"},[10506001]={title="眼之诅咒",text="基尔图诺斯对一名玩家施放眼之诅咒，将其变为幽灵形态，并在一段时间内使其无法使用技能。"},[10503003]={title="女妖哀嚎",text="詹迪斯对一名敌人发出女妖哀嚎，造成大量暗影伤害。"},[10503002]={title="血之诅咒",text="詹迪斯诅咒一名玩家的血液，使其受到的物理伤害提高。"},[10503001]={title="幻象",text="詹迪斯隐身并召唤出大量幻象分身。团队必须在其中找到并攻击真正的詹迪斯。"},[11622002]={title="战争践踏",text="血骨傀儡以碎骨之力践踏地面，使附近的所有玩家昏迷。"},[11622001]={title="顺劈斩",text="血骨傀儡用巨大的刀刃劈砍面前的所有敌人，造成巨额物理伤害。"},[10433003]={title="狂乱",text="马杜克陷入狂乱，提高其攻击速度和造成的伤害。"},[10433002]={title="顺劈斩",text="马杜克对其前方的所有敌人发动顺劈斩，造成大量物理伤害。"},[10433001]={title="旋风斩",text="黑衣卫士马杜克旋转形成旋风，对附近的所有玩家造成物理伤害。"},[10432002]={title="狂乱",text="维克图斯陷入狂乱，攻击速度大幅提高。"},[10432001]={title="火焰之盾",text="维克图斯用火焰之盾环绕自身，对任何对其进行近战攻击的敌人造成火焰伤害。"},[10508003]={title="恐惧术",text="莱斯·霜语使团队陷入恐惧，令附近的玩家惊恐逃跑。"},[10508002]={title="冰冻新星",text="莱斯·霜语释放一圈冰霜新星，对附近的玩家造成冰霜伤害并将其冻结在原地。"},[10508001]={title="寒冰箭",text="莱斯·霜语向目标投掷一支寒冰箭，造成冰霜伤害并使其减速。"},[10505004]={title="恢复",text="讲师玛丽希亚对自己或一名盟友施放恢复，持续恢复生命值。"},[10505003]={title="精神鞭笞",text="讲师玛丽希亚鞭笞一名玩家的精神，在引导期间造成暗影伤害并使其减速。"},[10505002]={title="痛苦诅咒",text="讲师玛丽希亚对一名玩家施放痛苦诅咒，造成逐渐增强的持续暗影伤害。"},[10505001]={title="快速治疗",text="讲师玛丽希亚施放快速的治疗，为自己或一名盟友恢复生命值。"},[11261004]={title="狂乱",text="卡斯迪诺夫陷入狂乱，以大幅提高的攻击速度屠戮团队。"},[11261003]={title="顺劈斩",text="卡斯迪诺夫对其前方的所有敌人发动顺劈斩，造成大量物理伤害。"},[11261002]={title="反手一击",text="卡斯迪诺夫反手一击，对目标造成物理伤害并使其短暂昏迷。"},[11261001]={title="撕裂",text="血色外科医生撕裂目标，造成物理伤害并使其持续流血。"},[10901002]={title="黑暗瘟疫",text="普克尔特使一名玩家感染黑暗瘟疫，这种疾病会不断恶化并造成持续的自然伤害。"},[10901001]={title="快速传染",text="普克尔特使一名玩家感染快速传染的疾病，造成持续的自然伤害。"},[10507003]={title="击倒",text="拉文尼亚将目标击倒在地，使其短暂昏迷。"},[10507002]={title="顺劈斩",text="拉文尼亚对其前方的所有敌人发动顺劈斩，造成大量物理伤害。"},[10507001]={title="践踏",text="拉文尼亚践踏周围的玩家，对附近的所有人造成物理伤害。"},[10504003]={title="暗影震击",text="阿雷克斯·巴罗夫以暗影能量冲击附近的敌人，造成暗影伤害。"},[10504002]={title="献祭",text="阿雷克斯·巴罗夫用火焰吞没一名敌人，立即造成火焰伤害，并在一段时间内造成额外的火焰伤害。"},[10504001]={title="暗影迷雾",text="阿雷克斯·巴罗夫用暗影之雾笼罩一名玩家，大幅降低其受到的治疗效果。"},[10502004]={title="暗影震击",text="伊露希亚·巴罗夫以暗影能量冲击附近的敌人，造成暗影伤害。"},[10502003]={title="恐惧术",text="伊露希亚·巴罗夫使团队陷入恐惧，令附近的玩家惊恐逃跑。"},[10502002]={title="沉默",text="伊露希亚·巴罗夫使附近的施法者沉默，使其在数秒内无法施法。"},[10502001]={title="痛苦诅咒",text="伊露希亚·巴罗夫对一名玩家施放痛苦诅咒，造成逐渐增强的持续暗影伤害。"},[1853004]={title="暗影之盾",text="加丁用暗影之盾包裹自身，对任何对其进行近战攻击的敌人造成暗影伤害。"},[1853003]={title="奥术飞弹",text="加丁向目标引导一连串奥术飞弹，造成奥术伤害。"},[1853002]={title="黑暗主宰诅咒",text="加丁诅咒一名玩家，用黑暗魔法削弱该玩家。"},[1853001]={title="暗影之门",text="黑暗院长加丁通过暗影之门将一名随机玩家放逐到旁边的一间教室中，并将其与一个召唤出的致命敌人关在一起，直到该敌人被消灭。"},[4633]={title="暗影之盾",text="审讯官格斯塔恩将自己包裹在黑暗之盾中，在30秒内吸收伤害。"},[4632]={title="暗言术：痛",text="审讯官格斯塔恩对一名玩家施放暗言术：痛。暗言术：痛每3秒造成一次暗影伤害，持续18秒。"},[4631]={title="心灵尖啸",text="审讯官格斯塔恩使8码范围内的所有玩家因恐惧而逃跑，持续6秒。"},[4630]={title="法力燃烧",text="审讯官格斯塔恩对一名玩家造成暗影伤害并吸取该玩家部分法力值。"},[4474]={title="烈焰震击",text="洛考尔对一名玩家造成火焰伤害。烈焰震击会在12秒内继续燃烧该玩家，每3秒造成一次火焰伤害。"},[4473]={title="大地震击",text="洛考尔对一名玩家造成自然伤害，并打断其施法。"},[4472]={title="大地震颤",text="洛考尔使周围20码范围内的所有玩家昏迷，持续2秒。"},[4629]={title="快跑！快跑！",text="当驯犬者格雷布玛尔的生命值降至15%时，他将逃跑。"},[6439]={title="嗜血",text="驯犬者格雷布玛尔让一个盟友进入狂乱状态，使其攻击速度提高30%，持续30秒。"},[4628]={title="拳击",text="驯犬者格雷布玛尔对一名玩家造成物理伤害，并打断其施法，持续5秒。"},[4627]={title="挫志怒吼",text="驯犬者格雷布玛尔使10码范围内所有玩家的攻击强度降低，持续30秒。"},[4626]={title="双武器",text="驯犬者格雷布玛尔双持武器。"},[4547]={title="你应该受到审判！",text="在秩序竞技场中，裁决者格里斯通判处玩家死刑。玩家必须面对随机选择的怪物，并且击败他们才能继续。"},[4567]={title="最后的审判！",text="裁决者格里斯通最后将放出一只怪兽与玩家决战。"},[4565]={title="修行者高罗什"},[4607]={title="致死打击",text="修行者高罗什对一名玩家造成物理伤害。所有受到致死打击影响的玩家受到的治疗量降低50%，持续5秒。"},[4606]={title="嗜血",text="修行者高罗什的近战攻击速度提高30%，持续30秒。"},[4605]={title="旋风斩",text="修行者高罗什对8码范围内的所有玩家造成物理伤害。"},[4604]={title="双武器",text="修行者高罗什双持武器。"},[4564]={title="爬行者赫杜姆"},[4616]={title="麻痹之毒",text="爬行者赫杜姆使一名玩家昏迷8秒。"},[4615]={title="癫狂",text="爬行者赫杜姆周期性地将当前目标的威胁值清零。"},[4614]={title="蛛网爆炸",text="爬行者赫杜姆使30码范围内的所有玩家无法移动，持续10秒。"},[4613]={title="祸害之毒",text="爬行者赫杜姆对一名玩家造成自然伤害。祸害之毒每5秒对该玩家造成一次自然伤害，持续2分钟。祸害之毒最多可叠加3次。"},[4563]={title="破坏者奥科索尔"},[4603]={title="变形术",text="破坏者奥科索尔将一名玩家变成羊，持续20秒。"},[4602]={title="减速术",text="破坏者奥科索尔降低20码范围内所有玩家的近战和远程攻击速度、施法速度、移动速度，持续10秒。攻击速度和施法速度降低54%。移动速度降低60%。"},[4601]={title="魔爆术",text="破坏者奥科索尔对30码范围内的所有玩家造成奥术伤害。"},[4600]={title="奥术之箭",text="破坏者奥科索尔对一名玩家造成奥术伤害。"},[4562]={title="腕眼者"},[4599]={title="暗影箭雨",text="剜眼者对30码范围内的所有玩家造成暗影伤害。"},[4598]={title="恶毒撕裂",text="剜眼者凶猛地撕裂一名玩家，每3秒造成一次物理伤害，持续15秒。"},[4597]={title="反魔法盾",text="剜眼者用反魔法盾包围住自己，可以防护所有法术攻击，持续10秒。"},[4561]={title="阿努希尔"},[4612]={title="虚弱诅咒",text="阿努希尔降低一名玩家造成的物理伤害，持续2分钟。"},[4611]={title="放逐术",text="阿努希尔将一名玩家放逐到虚空。放逐中的玩家免疫所有攻击和法术，但无法行动。"},[4610]={title="魔甲术",text="阿努希尔受恶魔能量保护。魔甲术增加阿努希尔的护甲值、暗影抗性和生命值恢复速度。"},[4609]={title="包围之网",text="阿努希尔将一名玩家困在蛛网中，持续8秒。受包围之网影响的玩家无法施法和移动，且近战攻击速度降低100%。"},[4608]={title="语言诅咒",text="阿努希尔强迫30码范围内的所有玩家使用恶魔语，使玩家施法速度降低50%，持续15秒。"},[4596]={title="暗影箭",text="阿努希尔对一名玩家造成暗影伤害。"},[4560]={title="格里兹尔"},[4595]={title="大地震颤",text="格里兹尔使20码范围内的所有玩家昏迷，持续2秒。"},[4594]={title="顺劈斩",text="格里兹尔对一名玩家及附近的玩家造成物理伤害。"},[4593]={title="狂乱",text="当格里兹尔的生命值降至50%时，他的近战攻击速度提高，持续2分钟。"},[4566]={title="序言",text="裁决者格里斯通首先在秩序竞技场中随机选择一只怪兽与玩家战斗。接下来会出现两波同类型的怪兽攻击玩家。有可能出现的怪兽见下。"},[4559]={title="洞穴爬行者"},[4592]={title="慢性中毒",text="洞穴爬行者使30码范围内的所有玩家慢性中毒，持续5分钟。受到该中毒效果影响的玩家所承受的物理伤害提高30%。"},[4591]={title="蛛网",text="洞穴爬行者使一名玩家在10秒内无法移动。"},[4590]={title="中毒",text="洞穴爬行者对受到其近战伤害的玩家下毒，毒药每3秒对玩家造成一次自然伤害，持续30秒。"},[4558]={title="掘泥虫"},[4583]={title="病弱",text="掘泥虫使30码范围内所有玩家的所有属性降低25%，持续5分钟。"},[4582]={title="中毒",text="掘泥虫每3秒对一名玩家造成一次自然伤害，持续30秒。"},[4581]={title="毒性喷吐",text="掘泥虫对一名玩家造成自然伤害。毒液喷吐每5秒对受到影响的玩家造成一次自然伤害，持续10秒。"},[4557]={title="黑暗尖啸者"},[4580]={title="听觉震荡",text="黑暗尖啸者使30码范围内所有玩家的施法速度降低35%，持续5分钟。"},[4579]={title="音爆",text="黑暗尖啸者对10码范围内的所有玩家造成物理伤害，并使其在10秒内不能施法。"},[4556]={title="深渊钉刺者"},[4578]={title="倒钩之刺",text="深渊钉刺者使30码范围内所有玩家的近战攻击速度降低54%，持续5分钟。"},[4577]={title="减速毒药",text="深渊钉刺者对受到其近战伤害的玩家施放减速毒药，毒药使玩家的近战攻击速度降低25%，并降低其移动速度，持续25秒。"},[4576]={title="顺劈斩",text="深渊钉刺者对一名玩家及其附近的目标造成物理伤害。"},[4555]={title="钻孔甲虫"},[4575]={title="腐烂蛋白",text="钻孔甲虫使30码范围内的玩家受到的自然伤害和暗影伤害提高50%，持续5分钟。"},[4574]={title="穿刺护甲",text="钻孔甲虫使一名玩家的护甲值降低50%，持续20秒。"},[4548]={title="洞穴雷霆蜥蜴"},[4551]={title="分离",text="洞穴雷霆蜥蜴对30码范围内的玩家造成分离。分离使玩家受到的火焰、冰霜及奥术伤害提高50%，持续5分钟。"},[4550]={title="雷霆一击",text="洞穴雷霆蜥蜴对10码范围内的所有玩家造成自然伤害。雷霆一击使玩家的近战攻击速度降低33%，移动速度降低55%，持续10秒。"},[4549]={title="蜥蜴之矢",text="洞穴雷霆蜥蜴对一名玩家造成自然伤害。"},[4500]={title="防护火焰结界",text="控火师罗格雷恩保护自己免受火焰伤害，持续1分钟或直到防护火焰结界因吸收过多火焰伤害而消失。"},[4499]={title="熔岩爆裂",text="控火师罗格雷恩对一名玩家造成火焰伤害。"},[4498]={title="烈焰震击",text="控火师罗格雷恩对一名玩家造成火焰伤害。烈焰震击随后每3秒对该玩家造成一次火焰伤害，持续12秒。"},[4496]={title="灼烧图腾",text="控火师罗格雷恩在身边召唤一个灼烧图腾，持续35秒，并攻击玩家。"},[4497]={title="灼烧",text="灼烧图腾对一名玩家造成火焰伤害。"},[4479]={title="元素领主的诅咒",text="伊森迪奥斯使45码范围内的所有玩家火焰抗性降低100点，持续1分钟。该效果最多可叠加3次。"},[4478]={title="全力一击",text="伊森迪奥斯对一名玩家造成物理伤害，并将其击退。"},[4477]={title="火焰爆发",text="伊森迪奥斯对直径为20码的指定区域内的所有玩家造成火焰伤害。"},[4476]={title="火焰风暴",text="伊森迪奥斯对直径为10码的指定区域内的所有玩家造成火焰伤害。火焰风暴每3秒对该区域内的所有玩家造成一次火焰伤害，持续30秒。"},[6455]={title="维雷克"},[6458]={title="激怒",text="当维雷克的生命值降低至25%时他会被激怒，造成的物理伤害和攻击速度提高，持续2分钟。"},[6457]={title="痛击",text="维雷克发动痛击，额外攻击两次。"},[6456]={title="血之诅咒",text="维雷克诅咒一名玩家，使其受到的所有物理伤害提高，持续10分钟。"},[4390]={title="防护冰霜结界",text="典狱官斯迪尔基斯保护自己不受冰霜伤害，持续1分钟或直到防护冰霜结界因吸收过多冰霜伤害而消失。"},[4388]={title="霜甲术",text="典狱官斯迪尔基斯将自己包裹在冰霜中，护甲值提高，对他发动近战攻击的攻击者会受到冰冻效果影响。"},[4389]={title="冰冻",text="霜甲术冰冻对典狱官斯迪尔基斯发动近战攻击的玩家。被冰冻的玩家移动速度降低30%，攻击速度降低25%。该效果持续5秒。"},[4387]={title="寒冰箭",text="典狱官斯迪尔基斯对一名玩家造成冰霜伤害。被寒冰箭击中的玩家移动速度降低50%，持续4秒。"},[4386]={title="冰霜新星",text="典狱官斯迪尔基斯对10码范围内的玩家造成冰霜伤害。受到冰霜新星伤害的玩家在8秒内无法移动。"},[4542]={title="清算圣印",text="弗诺斯·达克维尔为自己或一名盟友祈福，使其每次对一名玩家造成近战伤害时恢复生命值。清算圣印持续30秒。"},[4541]={title="脚踢",text="弗诺斯·达克维尔对一名玩家造成物理伤害，并打断其施法。"},[4540]={title="圣光术",text="弗诺斯·达克维尔治疗自己或一名盟友。"},[4539]={title="虔诚光环",text="虔诚光环使弗诺斯·达克维尔以及30码范围内的所有盟友的护甲值提高1080点。"},[4538]={title="神圣打击",text="弗诺斯·达克维尔对一名玩家造成神圣伤害。"},[4533]={title="召唤贝尔加的产物",text="贝尔加对随机区域内的所有玩家造成火焰伤害，并召唤贝尔加的产物来协助他作战。"},[4648]={title="贝尔加的产物",text="贝尔加的产物为贝尔加作战。"},[4532]={title="熔岩喷溅",text="近战攻击贝尔加的玩家每3秒受到一次火焰伤害，持续30秒。熔岩喷溅最多可叠加3次。"},[4511]={title="入侵警报！",text="当怒炉将军的生命值降至40%时，他将召唤铁怒预备兵和铁怒医师来协助他作战。"},[4517]={title="铁怒医师"},[4518]={title="快跑！",text="当铁怒医师的生命值降至15%时，他将逃跑。"},[4522]={title="真言术：韧",text="铁怒医师使一个盟友的耐力提高39点。"},[4521]={title="心灵震爆",text="铁怒医师对一名玩家造成暗影伤害。"},[4520]={title="治疗祷言",text="铁怒医师治疗30码范围内的所有盟友。"},[4519]={title="治疗",text="铁怒医师治疗一名盟友。"},[4512]={title="铁怒预备兵",text="铁怒预备兵协助怒炉将军作战。"},[4516]={title="战斗怒吼",text="铁怒预备兵使附近盟友的攻击强度提高208点，持续2分钟。"},[4515]={title="射击",text="铁怒预备兵对一名玩家进行远程攻击，造成物理伤害。"},[4514]={title="断筋",text="铁怒预备兵对一名玩家造成物理伤害，并使其移动速度降低60%，持续10秒。"},[4513]={title="打击",text="铁怒预备兵对一名玩家造成物理伤害。"},[4510]={title="激怒",text="怒炉将军受到近战攻击的爆击后会进入激怒状态。处于激怒状态时，怒炉将军造成的物理伤害提高55点，近战攻击速度提高30%。激怒效果持续5秒。"},[4509]={title="乱舞",text="怒炉将军每对玩家造成一次爆击，近战急速就会提高30%。乱舞效果最多可叠加3次，持续15秒。"},[4508]={title="破甲攻击",text="怒炉将军使一名玩家的护甲值降低，持续30秒，并增加玩家受到的物理伤害。"},[4503]={title="闪电之盾",text="傀儡统帅阿格曼奇将自己笼罩在3颗闪电球之中。闪电之盾有50%的几率对玩家发动的任何攻击进行反击。闪电之盾在反击过程中会造成自然伤害并消耗一颗闪电球。闪电之盾会一直持续到所有的闪电球都被消耗。"},[4502]={title="震击",text="傀儡统帅阿格曼奇对一名玩家造成自然伤害。"},[4501]={title="闪电链",text="傀儡统帅阿格曼奇对一名玩家造成自然伤害。闪电链将跳转到周围15码范围内的另一玩家身上并再次造成自然伤害。闪电链最多可攻击5个目标。"},[4495]={title="醉酒怒气",text="霍尔雷·黑须的攻击速度提高50%，物理伤害提高。该效果持续15秒。"},[4494]={title="烈焰吐息",text="霍尔雷·黑须对其前方锥形区域的所有玩家造成火焰伤害。"},[4506]={title="连珠火球",text="法拉克斯对周围20码范围内的所有玩家造成火焰伤害。"},[4505]={title="雷霆一击",text="法拉克斯对10码范围内的所有玩家造成自然伤害。受到雷霆一击影响的所有玩家的近战攻击速度降低33%，移动速度降低57%，持续10秒。"},[4504]={title="全力一击",text="法拉克斯对一名玩家造成物理伤害，并将其击退。"},[4490]={title="放逐术",text="普拉格把一名玩家放逐到虚空。被放逐的玩家无法行动，并免疫所有攻击和法术。"},[4489]={title="语言诅咒",text="普拉格诅咒一名玩家，强迫其使用恶魔语。受到语言诅咒的玩家的施法速度降低50%，持续15秒。"},[4488]={title="魔甲术",text="普拉格受恶魔能量保护。魔甲术提高普拉格的护甲值，暗影抗性和生命值恢复速度。"},[4487]={title="献祭",text="普拉格对一名玩家造成火焰伤害。献祭持续灼烧该玩家，每3秒对其造成一次火焰伤害，持续21秒。"},[4486]={title="暗影箭",text="普拉格对一名玩家造成暗影伤害。"},[4485]={title="黑铁酒吧老板",text="普拉格掌管黑铁酒吧的钥匙。如果玩家扒窃普拉格的口袋，普拉格将召唤他所有的顾客攻击玩家。这将使黑铁酒吧的所有酒客由中立变成敌对。"},[4484]={title="火焰冲击",text="弗莱拉斯大使的近战攻击对被命中的玩家造成220到260点火焰伤害。"},[4482]={title="燃灵术",text="当弗莱拉斯大使的房间周围出现7个烈焰符文时，将产生燃烧之灵。燃烧之灵将朝弗莱拉斯大使方向移动并施放燃灵术。"},[4483]={title="燃灵术",text="当燃烧之灵进入弗莱拉斯大使周围1码范围内时，他们将牺牲自己，使弗莱拉斯大使获得燃灵术。\n燃灵术使弗莱拉斯大使的伤害提高，体型增大。燃灵术最多可叠加50层。"},[4397]={title="杜姆雷尔"},[4434]={title="暗影箭雨",text="杜姆雷尔对周围30码内的所有玩家造成暗影伤害。"},[4433]={title="献祭",text="杜姆雷尔对一名玩家造成火焰伤害。献祭随后每3秒对该玩家造成一次火焰伤害，持续21秒。"},[4432]={title="魔甲术",text="杜姆雷尔受恶魔能量保护。魔甲术提高杜姆雷尔的护甲值，暗影抗性和生命值恢复速度。"},[6440]={title="虚弱诅咒",text="杜姆雷尔诅咒一名玩家，使其造成的物理伤害降低，持续2分钟。"},[4431]={title="放逐术",text="杜姆雷尔把一名玩家放逐到虚空。被放逐的玩家不能移动也无法行动，其他玩家和怪物也无法与其互动。放逐效果持续15秒。"},[4430]={title="虚空行者",text="杜姆雷尔召唤三名虚空行者协助其作战。"},[4396]={title="黑特雷尔"},[4429]={title="乱舞",text="黑特雷尔每对玩家造成一次爆击，近战急速就会提高30%。乱舞效果最多可叠加3次，持续15秒。"},[4428]={title="暗影之盾",text="黑特雷尔将自己包裹在黑暗之盾中，在30秒内吸收伤害。"},[4427]={title="打击",text="黑特雷尔用武器对一名玩家额外造成物理伤害。"},[4426]={title="暗影箭",text="黑特雷尔对一名玩家造成暗影伤害。"},[4395]={title="瓦勒雷尔"},[4425]={title="心灵震爆",text="瓦勒雷尔对一名玩家造成暗影伤害。"},[4424]={title="真言术：盾",text="瓦勒雷尔保护自己或一名盟友不再受到伤害。被保护目标的施法不会被打断。真言术：盾的效果持续30秒或在吸收过多伤害后消失。"},[4423]={title="治疗祷言",text="瓦勒雷尔为自己及周围30码范围内的所有盟友治疗。"},[4422]={title="治疗",text="瓦勒雷尔为自己或一名盟友治疗。"},[4394]={title="格鲁雷尔"},[4421]={title="鲁莽",text="格鲁雷尔在生命值降低至25%时获得鲁莽效果，持续15秒。\n鲁莽使格鲁雷尔造成爆击的几率提高100%。\n鲁莽使格鲁雷尔的护甲值降低35%。\n鲁莽使格鲁雷尔免疫恐惧效果。"},[4420]={title="癫狂",text="当格鲁雷尔的生命值依次降至66%及33%时，他都会将当前目标的威胁值清零。"},[4419]={title="断筋",text="格鲁雷尔使一名玩家的移动速度降低60%，持续10秒。"},[4418]={title="致死打击",text="格鲁雷尔对一名玩家造成物理伤害，并使其受到的治疗量降低50%，持续5秒。"},[4417]={title="顺劈斩",text="格鲁雷尔对他面前的玩家造成物理伤害。"},[4393]={title="多普雷尔"},[4416]={title="闪避",text="当普雷尔的生命值降至25%时，他将激活闪避技能。闪避技能使多普雷尔的躲闪几率提高50%，持续15秒。"},[4415]={title="割裂",text="多普雷尔使一名玩家流血，每2秒受到一次物理伤害，持续10秒。"},[4414]={title="凿击",text="多普雷尔凿击一名玩家使其瘫痪。多普雷尔只能在玩家对面着他时使用此技能。"},[4413]={title="背刺",text="多普雷尔从背后袭击一名玩家，对其造成大量的物理伤害。"},[4412]={title="影袭",text="多普雷尔对一名玩家造成额外的物理伤害。"},[4411]={title="双武器",text="多普雷尔双持匕首。"},[4392]={title="西斯雷尔"},[4410]={title="冰锥术",text="西斯雷尔对其前方锥形区域内的玩家造成冰霜伤害。被冰锥术击中玩家移动速度降低50%，持续8秒。"},[4409]={title="冰霜新星",text="西斯雷尔对10码内的所有玩家造成冰霜伤害。被冰霜新星击中的玩家在8秒内无法移动。"},[4408]={title="防护冰霜结界",text="西斯雷尔保护自己不受冰霜伤害，持续1分钟或直到防护冰霜结界因吸收过多冰霜伤害而消失。"},[4407]={title="寒冰箭",text="西斯雷尔对一名玩家造成冰霜伤害。被寒冰箭击中的玩家移动速度降低50%，持续4秒。"},[4406]={title="暴风雪",text="西斯雷尔制造一场暴风雪，持续10秒。暴风雪对陷入其中的所有玩家造成冰霜伤害。"},[4404]={title="霜甲术",text="西斯雷尔将自己包裹在冰霜中，护甲值提高，对她发动近战攻击的攻击者会受到冰冻效果影响。"},[4405]={title="冰冻",text="被冰冻的玩家移动速度降低30%，攻击速度降低25%，持续5秒。"},[4391]={title="安格雷尔"},[4403]={title="盾墙",text="当安格雷尔的生命值降至25%时，他将使用盾墙来增强防御，持续10秒。在盾墙激活时，安格雷尔受到的伤害减少75%。"},[4402]={title="破甲攻击",text="安格雷尔使一名玩家的护甲值降低。当护甲值降低时，玩家将额外受到伤害。该效果最多可叠加5次。"},[4401]={title="盾牌格挡",text="安格雷尔的格挡几率提高75%，持续5秒。"},[4400]={title="打击",text="安格雷尔使用武器对一名玩家造成物理伤害。"},[4398]={title="易怒",text="当受到玩家的近战爆击时，安格雷尔被激怒。"},[4399]={title="激怒",text="安格雷尔造成的伤害提高55点，攻击速度提高30%。激怒效果持续5秒。"},[4471]={title="七矮人",text="杜姆雷尔召唤他的矮人同伴的幽灵与玩家作战。幽灵将依次出现，每次一个。当其他六个幽灵被击败后，杜姆雷尔将亲自加入战斗。"},[4481]={title="火焰爆发",text="玛格姆斯对直径为20码的指定区域内的所有玩家造成火焰伤害。"},[4480]={title="战争践踏",text="玛格姆斯对周围5码范围内的所有玩家造成物理伤害，并将他们击退。被战争践踏击中的玩家昏迷8秒。"},[6441]={title="铁炉堡公主茉艾拉·铜须"},[6444]={title="心灵震爆",text="铁炉堡公主茉艾拉·铜须震爆一名玩家的心灵，造成暗影伤害。"},[6443]={title="恢复",text="铁炉堡公主茉艾拉·铜须对一个盟友施放恢复，每3秒为其恢复一定生命值，持续20秒。"},[6442]={title="治疗",text="铁炉堡公主茉艾拉·铜须召唤神圣魔法治疗一个盟友。"},[4647]={title="索瑞森之手",text="达格兰·索瑞森大帝对一名玩家造成火焰伤害，并使其昏迷5秒。"},[4646]={title="反对者",text="达格兰·索瑞森大帝带着一把强大的战锤——反对者。达格兰·索瑞森大帝的近战攻击有一定的几率额外发动3次攻击，并使他的爆击几率提高10%，持续5秒。"},[4645]={title="烈焰化身",text="达格兰·索瑞森大帝变成烈焰化身，持续10秒。烈焰化身免疫所有魔法，并在对玩家发动近战攻击时造成火焰伤害。"},[4905]={title="鞭笞",text="哈卡的化身鞭笞当前目标，使其昏迷2秒。此外，鞭笞有10%的几率使目标缴械。"},[4904]={title="语言诅咒",text="哈卡的化身诅咒一名玩家，使其施法速度降低50%，持续15秒。"},[4903]={title="导致疯狂",text="哈卡的化身将一名玩家逼疯，使其攻击自己的盟友，持续6秒。受到疯狂效果影响的玩家攻击速度提高50%，移动速度提高80%。"},[4938]={title="可悲的奥戈姆",text="可悲的奥戈姆协助预言者迦玛兰作战。"},[4941]={title="暗影箭",text="可悲的奥戈姆对一名玩家发射黑暗魔法箭，对其造成暗影伤害。"},[4940]={title="暗言术：痛",text="可悲的奥戈姆诵念黑暗的咒语，每3秒对一名玩家造成一次暗影伤害，持续18秒。"},[4939]={title="虚弱诅咒",text="可悲的奥戈姆诅咒一名玩家，使其造成的物理伤害降低。"},[4937]={title="迦玛兰的妖术",text="预言者迦玛兰对一名玩家施放妖术，使其造成的伤害提高400%，并使其变形且攻击自己的盟友。"},[4936]={title="陷地图腾",text="预言者迦玛兰在身边召唤一个陷地图腾，持续存在30秒。陷地图腾每5秒使10码范围内的所有玩家无法移动。"},[4935]={title="烈焰风暴",text="预言者迦玛兰召唤一根火柱，对目标区域附近5码范围内的所有玩家造成火焰伤害，并在接下来的8秒内每2秒造成一次额外的火焰伤害。"},[4934]={title="治疗波",text="预言者迦玛兰治疗一名盟友。"},[6114]={title="梦境守望者",text="德姆塞卡尔、德拉维沃尔、摩弗拉斯和哈扎斯誓死保卫伊兰尼库斯的阴影。"},[4943]={title="拍翼",text="梦境守望者拍打翅膀，将其面前的所有玩家击退。"},[4942]={title="酸息术",text="梦境守望者施放酸息术，立即对面前的所有玩家造成自然伤害，并在接下来的45秒内每5秒造成一次额外的自然伤害。"},[4953]={title="酸息术",text="伊兰尼库斯的阴影施放酸息术，立即对面前的所有玩家造成自然伤害，并在接下来的45秒内每5秒造成一次额外的自然伤害。"},[4952]={title="战争践踏",text="伊兰尼库斯的阴影践踏敌人，使5码范围内的所有玩家昏迷，持续5秒。"},[4951]={title="痛击",text="伊兰尼库斯的阴影痛击当前目标，额外发动2次攻击。"},[4950]={title="深度沉睡",text="伊兰尼库斯的阴影使一名玩家进入深度沉睡状态，使其昏迷15秒，并免疫所有伤害。"},[4524]={title="狂乱",text="当欧莫克大王的生命值降至50%时，他将进入狂乱状态，攻击速度提高。"},[4523]={title="击退",text="欧莫克大王对当前目标造成物理伤害，并将其击退。"},[4526]={title="血之诅咒",text="暗影猎手沃什加斯诅咒10码范围内的所有玩家，使其受到的物理伤害提高90点，持续10分钟。"},[4525]={title="妖术",text="暗影猎手沃什加斯随机将一名玩家变成青蛙，使其不能攻击或施法，持续10秒。"},[4534]={title="第三阶段：指挥官",text="当指挥官沃恩的生命值降至40%时，他将不顾一切地发起最后一波进攻。"},[4537]={title="拳击",text="指挥官沃恩随机拳击一名玩家，对其造成物理伤害，并打断其施法，持续5秒。"},[4536]={title="上钩拳",text="指挥官沃恩使用上钩拳攻击当前目标，对其造成物理伤害，并将其击退。"},[4535]={title="猛踢",text="指挥官沃恩猛踢当前目标，造成物理伤害，并使其昏迷2秒。"},[4529]={title="第二阶段：争斗者",text="当指挥官沃恩的生命值降至65%时，他将改变战斗姿态，发动更为猛烈的进攻。"},[4531]={title="致死打击",text="指挥官沃恩对当前目标造成物理伤害，使其受到的治疗效果降低50%，持续5秒。"},[4530]={title="顺劈斩",text="指挥官沃恩对当前目标及离其最近的盟友造成物理伤害，最多可影响3个目标。"},[4527]={title="第一阶段：痛击者",text="指挥官沃恩迅速进攻，给他的敌人迎头痛击。"},[6464]={title="掷斧",text="指挥官沃恩改变姿态时随机向一名玩家投掷巨大的斧头，造成1750点物理伤害，并使其昏迷2秒。"},[4528]={title="痛击",text="指挥官沃恩痛击当前目标，额外发动2次攻击。"},[4545]={title="召唤尖塔小蜘蛛",text="当烟网蛛后死亡时，它的尸体会释放出三只尖塔小蜘蛛。"},[4546]={title="尖塔小蜘蛛",text="孵化的烟网蜘蛛幼虫。"},[4544]={title="蛛后的乳汁",text="烟网蛛后随机使一名玩家及其周围30码范围内的所有盟友中毒，周期性地无法移动。"},[4543]={title="晶化",text="烟网蛛后使其面前的所有玩家昏迷6秒。"},[4554]={title="打击",text="尤洛克·暗嚎打击当前目标，造成物理伤害。"},[4553]={title="撕裂",text="尤洛克·暗嚎撕裂当前目标，每3秒对其造成一次的物理伤害。"},[4552]={title="破胆怒吼",text="尤洛克·暗嚎怒吼，使8码范围内的所有玩家因恐惧而逃跑，持续8秒。"},[4571]={title="射击",text="在当前目标处于近战攻击范围之外时，军需官兹格雷斯对其射击，造成物理伤害。"},[4570]={title="昏迷炸弹",text="军需官兹格雷斯随机向一名玩家投掷炸弹，对5码范围内的所有玩家造成火焰伤害，并使其昏迷5秒。"},[4569]={title="喝下治疗药水",text="军需官兹格雷斯使用治疗药水为自己治疗。"},[4568]={title="钩网",text="军需官兹格雷斯随机向一名玩家投网，对其造成物理伤害并使其无法移动，持续10秒。"},[4573]={title="撕裂",text="哈雷肯撕裂当前目标，每3秒对其造成一次物理伤害。"},[4572]={title="痛击",text="哈雷肯痛击当前目标，额外发动2次攻击。"},[4586]={title="感染撕咬",text="奴役者基兹鲁尔撕咬当前目标，每10秒对目标造成一次自然伤害并增加其受到的物理伤害。"},[4585]={title="致命撕咬",text="奴役者基兹鲁尔撕咬当前目标，造成物理伤害并吸取其生命值。基兹鲁尔恢复的生命值相当于所吸取生命值的两倍。"},[4584]={title="狂乱",text="奴役者基兹鲁尔进入狂乱状态，攻击速度提高，持续2分钟。"},[6465]={title="领主戒备",text="当维姆萨拉克的生命值降低至50%时，他召唤他的两个守卫来为他作战。"},[6472]={title="血斧精兵"},[6474]={title="拳击",text="血斧精兵拳击一名玩家，造成物理伤害，并打断其施法，持续5秒。"},[6473]={title="猛踢",text="血斧精兵脚踢一名玩家，造成物理伤害，并使其昏迷2秒。"},[6469]={title="燃棘狂战士"},[6471]={title="打击",text="燃棘狂战士打击一名玩家，造成物理伤害。"},[6470]={title="致死打击",text="燃棘狂战士对一名玩家造成重伤，造成物理伤害，并使其受到的所有治疗效果降低50%，持续5秒。"},[6466]={title="尖石军阀"},[6468]={title="狂暴",text="尖石军阀进入狂乱状态，攻击速度提高，持续2分钟。"},[6467]={title="强化意志",text="尖石军阀强化其盟友，驱散其身上的变形术、魅惑和瘫痪。"},[4589]={title="挫志怒吼",text="维姆萨拉克怒吼，使10码范围内所有玩家的近战攻击强度降低，持续30秒。"},[4588]={title="顺劈斩",text="维姆萨拉克对当前目标及离其最近的盟友造成物理伤害，最多可影响3个目标。"},[4587]={title="横扫猛击",text="维姆萨拉克对前方的所有玩家造成物理伤害并将其击退。"},[4920]={title="纠缠",text="特迪斯·扭木将一名玩家传送到他的身边并用根须将其缠住，每3秒对其造成25点自然伤害，并使其无法移动，持续10秒。"},[4919]={title="缠绕之藤",text="特迪斯·扭木对10码范围内的所有玩家造成525到675点物理伤害，将其击倒，并使其无法移动，持续10秒。"},[4918]={title="践踏",text="特迪斯·扭木对10码范围内的所有玩家造成物理伤害。"},[4913]={title="入侵警报！",text="当玩家开始战斗时，特迪斯·扭木召唤所有活着的埃隆巴克保护者来援助他。"},[4914]={title="埃隆巴克保护者"},[4917]={title="纠缠根须",text="埃隆巴克保护者用根须缠住玩家，使其每3秒受到40点自然伤害，并且无法移动，持续10秒。"},[4916]={title="击退",text="埃隆巴克保护者对一名玩家造成物理伤害并将其击退，使该玩家的威胁值降低50%。"},[4915]={title="践踏",text="埃隆巴克保护者对10码范围内的所有玩家造成物理伤害。"},[4912]={title="震荡射击",text="伊琳娜·暗木使一名玩家眩晕，使其移动速度降低50%，持续3秒。震荡射击有50%的几率使玩家昏迷3秒。"},[4911]={title="献祭陷阱",text="伊琳娜·暗木在身边放置一个献祭陷阱。献祭陷阱可持续存在1分钟或直到玩家踏入陷阱为止。\n\n献祭陷阱对触发陷阱的玩家造成火焰伤害。"},[4910]={title="箭雨",text="伊琳娜·暗木向一片区域内的所有玩家进行一轮乱射。乱射造成奥术伤害。"},[4909]={title="多重射击",text="伊琳娜·暗木对她面前最多10名玩家造成物理伤害。"},[4906]={title="费拉",text="费拉是伊琳娜·暗木忠诚的同伴，会陪她战斗到底。"},[4908]={title="重殴",text="费拉对一名玩家造成物理伤害。"},[4907]={title="冲锋",text="费拉向一名玩家发起冲锋，对其造成物理伤害，并使其昏迷2秒。"},[4840]={title="统御意志",text="卡雷迪斯镇长魅惑一名玩家。被魅惑的玩家会为卡雷迪斯镇长作战，但其近战攻击速度将降低100%。统御意志持续10秒。"},[4839]={title="心灵震爆",text="卡雷迪斯镇长对一名玩家造成暗影伤害。"},[4838]={title="精神鞭笞",text="卡雷迪斯镇长向一名玩家引导黑暗魔法，每1秒造成240点暗影伤害，持续3秒，并使目标移动速度降低50%。"},[4837]={title="暗言术：痛",text="卡雷迪斯镇长念诵黑暗的咒语，每3秒对一名敌人造成48点暗影伤害，持续18秒。"},[4836]={title="暗影形态",text="当卡雷迪斯镇长的生命值降至50%时，他将进入暗影形态。暗影形态使其受到的所有伤害降低，造成的暗影伤害提高40%，持续4分钟。"},[4827]={title="践踏",text="伊莫塔尔对10码范围内的所有玩家造成物理伤害。"},[4826]={title="狂乱",text="伊莫塔尔使自身攻击速度提高，持续2分钟。"},[4825]={title="感染撕咬",text="伊莫塔尔撕咬一名玩家及其最近的盟友，每10秒造成45点自然伤害，并使其受到的物理伤害提高，持续3分钟。"},[4824]={title="伊莫塔尔传送门",text="伊莫塔尔会周期性地将玩家召唤到其所在位置，并将其威胁值清零。"},[4822]={title="伊莫塔尔之眼",text="伊莫塔尔召唤伊莫塔尔之眼攻击一名随机玩家。"},[4823]={title="伊莫塔尔的凝视",text="伊莫塔尔之眼使玩家移动速度降低，急速降低，并造成暗影伤害，持续4秒。该效果可叠加。"},[29895]={title="奥术射击",text="托塞德林王子对一名远处的敌人造成奥术伤害。"},[29894]={title="召唤",text="当近战范围内没有敌人时，托塞德林王子会将一名敌人召唤到自己身边。"},[4756]={title="法术反制",text="托塞德林王子打断一名玩家的施法，并使其在15秒内无法继续施法。"},[4755]={title="旋风斩",text="托塞德林王子对8码范围内所有玩家造成物理伤害并将其击退。"},[4754]={title="奥术冲击",text="托塞德林王子对一名玩家造成875到1125点奥术伤害并将其击退。"},[5000]={title="匹姆吉布"},[5003]={title="烈焰打击",text="匹姆吉布对玩家造成火焰伤害，并使玩家受到的所有火焰伤害提高，持续20秒。该效果可叠加。"},[5002]={title="火球术",text="匹姆吉布对一名玩家造成火焰伤害。"},[5001]={title="冲击波",text="匹姆吉布对10码范围内的所有玩家造成122到140点火焰伤害，并使其移动速度降低50%，持续6秒。"},[29889]={title="蕾瑟塔蒂丝"},[4999]={title="巨化术",text="蕾瑟塔蒂丝使匹姆吉布变大，持续30秒。变大后，匹姆吉布造成的伤害提高，施法速度提高100%。"},[4998]={title="献祭",text="蕾瑟塔蒂丝对其当前目标造成火焰伤害。献祭随后在21秒内持续对敌人造成火焰伤害。"},[4997]={title="语言诅咒",text="蕾瑟塔蒂丝诅咒一名玩家，强迫其使用恶魔语，持续15秒。语言诅咒使施法速度降低50%。"},[4996]={title="荆棘诅咒",text="蕾瑟塔蒂丝使用荆棘诅咒诅咒一名玩家。荆棘诅咒有50%的几率使被诅咒的玩家每次发动近战攻击时，对自己造成暗影伤害。荆棘诅咒的效果持续3分钟。"},[4995]={title="暗影箭雨",text="蕾瑟塔蒂丝对30码范围内的所有玩家造成128到172点暗影伤害。"},[4994]={title="虚空箭",text="蕾瑟塔蒂丝对目标造成925到1075点暗影伤害。"},[5009]={title="水浪幼崽",text="当海多斯博恩在生命值降至66%和33%时，他将召唤2个水浪幼崽。"},[5010]={title="喷液",text="水浪幼崽在近身战斗中会有几率将一名玩家击退，并使其威胁值清零。"},[5008]={title="巨型喷泉",text="海多斯博恩召唤一个巨型喷泉，对10码范围内的所有玩家造成463到537点冰霜伤害，并将其击退。"},[5007]={title="激流",text="海多斯博恩对附近的所有玩家造成85到115点冰霜伤害，并将其击退。受激流影响的玩家将被缴械，持续4秒。"},[5004]={title="淹没",text="海多斯博恩使附近所有玩家的耐力降低，持续1分钟。该效果可叠加。"},[29563]={title="暗影箭雨",text="瑟雷姆·刺蹄射出多支黑暗魔法箭，对附近30码内的敌人造成128到172点暗影伤害。"},[4656]={title="牺牲",text="瑟雷姆·刺蹄将一名玩家传送到他的牺牲祭坛。牺牲使目标玩家昏迷，并且每1秒吸取其300点生命值，持续8秒。"},[4655]={title="剧烈痛楚",text="瑟雷姆·刺蹄每3秒对20码范围内的所有玩家造成200点暗影伤害，持续15秒。此效果可叠加。"},[4984]={title="来吧，爪牙！",text="当奥兹恩的生命值降至50%时，他将召唤数个小鬼爪牙来协助他。"},[4985]={title="奥兹恩的爪牙",text="每当奥兹恩的爪牙的近战攻击造成伤害时，都会将当前目标的威胁值清零。"},[4925]={title="恐狼形态",text="荒野变形者奥兹恩变形成恐狼，攻击速度提高75%，近战伤害提高50%，持续30秒。荒野变形者奥兹恩在恐狼形态下可以使用这些技能。"},[4928]={title="恶毒撕咬",text="荒野变形者奥兹恩对他面前最多2名玩家造成物理伤害。"},[29719]={title="痛击",text="荒野变形者奥兹恩在狼形态下获得额外攻击次数。"},[4929]={title="裂伤",text="荒野变形者奥兹恩撕裂一名玩家。裂伤使目标的移动速度降低50%，并且每2秒对目标造成200点物理伤害，持续20秒。"},[4926]={title="树形态",text="荒野变形者奥兹恩变形成一棵树，护甲提高，近战伤害提高25%，持续30秒。荒野变形者奥兹恩在树形态下会使用这些技能。"},[29976]={title="纠缠根须",text="荒野变形者奥兹恩用根须将一名玩家缠住10秒，使其无法移动，并每3秒对其造成40点自然伤害。"},[4931]={title="缴械",text="荒野变形者奥兹恩缴械一名玩家，持续6秒。"},[4932]={title="击退",text="荒野变形者奥兹恩对一名玩家造成物理伤害，并将其击退。受击退影响的玩家的威胁值将清零。"},[4933]={title="野性苏生",text="荒野变形者奥兹恩每2秒恢复生命值，持续20秒。"},[4921]={title="萨特形态",text="荒野变形者奥兹恩在萨特形态下使用以下技能。"},[4924]={title="荆棘术",text="荒野变形者奥兹恩用荆棘覆盖自己。荆棘对攻击荒野变形者奥兹恩的所有玩家造成自然伤害。"},[4923]={title="枯萎",text="荒野变形者奥兹恩对一名玩家造成740到860点自然伤害并使其感染恶疾，每3秒额外造成139到161点自然伤害，并使其力量、智力或敏捷降低，持续21秒。"},[4922]={title="弱化",text="荒野变形者奥兹恩吸收一名玩家的法力值，每1秒吸取200点，持续10秒。"},[4798]={title="多重射击",text="弗雷斯特恩对他面前最多10名玩家造成物理伤害。"},[4796]={title="灵体防御",text="弗雷斯特恩的躲闪几率提高50%。"},[4795]={title="挫志怒吼",text="弗雷斯特恩发出咆哮，使10码范围内的所有玩家的耐力和主要属性降低，持续30秒。"},[4794]={title="催眠曲",text="弗雷斯特恩催眠一名玩家，使其昏迷10秒，如果该玩家受到伤害，将解除该效果。"},[6217]={title="复仇的幻影",text="不可宽恕者由四个复仇的幻影陪伴。"},[6463]={title="冰霜震击",text="复仇的幻影用冰块震击玩家，造成89到95点冰霜伤害，并使其移动速度降低50%，持续8秒。"},[4833]={title="无限苦难",text="不可宽恕者向受害者引导一股痛苦和悲伤，使目标减速，并造成暗影伤害。"},[29845]={title="语言诅咒",text="邮差马龙强迫目标使用恶魔语，使其所有法术的施放时间延长50%，持续15秒。"},[29844]={title="反手一击",text="邮差马龙对敌人发动反手一击，使其昏迷2秒。"},[29843]={title="虚弱诅咒",text="邮差马龙使附近敌人造成的物理伤害降低，持续2分钟。"},[29842]={title="恐惧",text="邮差马龙使敌人因恐惧而逃跑，持续4秒。在同一时间内，只有一个目标会被恐惧。"},[29847]={title="邮件必达",text="邮差马龙会派遣亡灵邮差追捕任何乱动邮箱的人。乱动邮箱达到三次，邮差本人会亲自出马解决问题。"},[29848]={title="亡灵邮差"},[29851]={title="哀嚎死者",text="亡灵邮差的哀嚎使附近敌人的所有属性降低，持续6秒。"},[29850]={title="墓穴的召唤",text="亡灵邮差在60秒后对一名敌人造成暗影伤害。"},[29849]={title="虚体防御",text="亡灵邮差有额外50%的几率躲闪攻击。"},[4801]={title="激怒",text="当残忍的提米的生命值降至50%时，他将被激怒，造成的伤害和攻击速度提高30%。"},[4800]={title="困兽之爪",text="残忍的提米向前冲出，对其前方所有敌人造成925到1075点物理伤害，并为自身恢复所造成伤害100%的生命值。"},[4799]={title="痛击",text="残忍的提米痛击对手，额外发动2次攻击。"},[6454]={title="暗影箭雨",text="指挥官玛洛尔发射黑暗魔法箭，对30码范围内的所有玩家造成128到172点暗影伤害。"},[6453]={title="裂颅",text="指挥官玛洛尔使一名玩家的耐力降低，持续20秒。"},[6452]={title="大地粉碎",text="指挥官玛洛尔重击地面，对10码范围内的所有玩家造成96到128点物理伤害，使其昏迷3秒。"},[4804]={title="拳击",text="希望破坏者威利随机拳击一名玩家，造成45点物理伤害，并打断其施法，持续5秒。"},[4803]={title="射击",text="希望破坏者威利向当前目标射击，造成物理伤害。"},[4802]={title="击退",text="希望破坏者威利对当前目标造成物理伤害，并将其击退。"},[4807]={title="血色火炮",text="希望破坏者威利身旁的血色火炮可以装填炸弹并向来犯的复生的火枪手射击。"},[4805]={title="召唤复生的火枪手",text="希望破坏者威利每5秒召唤复生的火枪手来协助他作战。"},[4806]={title="复生的火枪手",text="复生的火枪手协助希望破坏者威利作战，随机向玩家射击，造成物理伤害。"},[4810]={title="燃烧之风",text="档案管理员加尔福特用燃火之风席卷当前目标，每1秒造成200点火焰伤害，并使其昏迷8秒。"},[4809]={title="炎爆术",text="档案管理员加尔福特对其当前目标造成火焰伤害。"},[4808]={title="火焰新星",text="档案管理员加尔福特释放一个火焰新星，对10码范围内的所有敌人造成197到227点火焰伤害。"},[4832]={title="心灵尖啸",text="巴纳扎尔发出一阵心灵尖啸，使8码范围内的所有玩家陷入惊骇，持续6秒。"},[4831]={title="昏睡",text="巴纳扎尔随机催眠一名玩家，使其昏迷，直到该玩家受到伤害。"},[4830]={title="支配",text="巴纳扎尔随机控制一名玩家，持续15秒。"},[4829]={title="暗影震击",text="巴纳扎尔对附近的所有玩家造成暗影伤害。"},[4828]={title="心灵震爆",text="巴纳扎尔对当前目标造成暗影伤害。"},[4743]={title="入侵警报！",text="卫兵摩尔达进入狂乱状态，并在生命值降至50%时呼救。"},[4744]={title="狂乱",text="卫兵摩尔达的攻击速度提高，持续2分钟。"},[4742]={title="打击",text="卫兵摩尔达对一名玩家造成物理伤害。"},[4741]={title="盾牌冲锋",text="卫兵摩尔达向一名玩家冲锋，将其击退，并对其造成物理伤害。"},[4740]={title="盾击",text="卫兵摩尔达对一名玩家造成物理伤害，并打断其施法，持续8秒。"},[4737]={title="你害我把酒都喷出来了！",text="当践踏者克雷格的生命值降至50%时，他将进入醉酒怒气状态和狂乱状态。"},[4739]={title="醉酒怒气",text="践踏者克雷格每次对一名玩家发动近战攻击，就会将当前目标的仇恨清零。醉酒怒气还使践踏者克雷格的移动速度提高100%，持续1分钟。"},[4738]={title="狂乱",text="践踏者克雷格的攻击速度提高，持续2分钟。"},[4736]={title="旋风斩",text="践踏者克雷格对8码范围内的所有玩家造成物理伤害。"},[4735]={title="战争践踏",text="践踏者克雷格击退5码范围内的所有玩家。"},[4734]={title="喷酒",text="践踏者克雷格向其面前锥形区域内的所有玩家喷酒。被喷酒命中的玩家的命中几率降低75%，并酩酊大醉，持续10秒。"},[4728]={title="入侵警报！",text="卫兵芬古斯进入狂乱状态，并在生命值降至50%时呼救。"},[4729]={title="狂乱",text="卫兵芬古斯的攻击速度提高，持续2分钟。"},[4727]={title="打击",text="卫兵芬古斯对一名玩家造成物理伤害。"},[4726]={title="盾牌冲锋",text="卫兵芬古斯向一名玩家冲锋，将其击退，并对其造成物理伤害。"},[4725]={title="盾击",text="卫兵芬古斯对一名玩家造成物理伤害，并打断其施法，持续8秒。"},[4719]={title="入侵警报！",text="卫兵斯里基克进入狂乱状态，并在生命值降至50%时呼救。"},[4720]={title="狂乱",text="卫兵斯里基克的攻击速度提高60%，持续2分钟。"},[4718]={title="打击",text="卫兵斯里基克对一名玩家造成物理伤害。"},[4717]={title="盾牌冲锋",text="卫兵斯里基克向一名玩家冲锋，将其击退，并对其造成物理伤害。"},[4716]={title="盾击",text="卫兵斯里基克对一名玩家造成物理伤害，并打断其施法，持续8秒。"},[4707]={title="放马过来！",text="当克罗卡斯的生命值降至25%时，他将激活反击风暴。"},[4708]={title="反击风暴",text="克罗卡斯反击对其发动近战攻击的所有玩家，持续15秒，造成物理伤害。"},[4695]={title="入侵警报！",text="当克罗卡斯的生命值降至50%时，他将召唤两个戈多克掠夺者来协助其作战。"},[4696]={title="戈多克掠夺者"},[4699]={title="致死打击",text="戈多克掠夺者对一名玩家造成物理伤害。受致死打击影响的玩家受到的治疗量减少50%，持续5秒。"},[4698]={title="破甲攻击",text="戈多克掠夺者使一名玩家的护甲值降低，其受到的物理伤害提高。破甲攻击最多可叠加5层，持续30秒。"},[4697]={title="顺劈斩",text="戈多克掠夺者对一名玩家及离其最近的一名玩家造成物理伤害。"},[4706]={title="致死顺劈",text="克罗卡斯对一名玩家及其附近的一名玩家造成物理伤害。受致死顺劈影响的玩家受到的治疗量降低50%，持续5秒。"},[4705]={title="破胆怒吼",text="克罗卡斯使8码范围内的所有玩家因恐惧而逃跑，持续8秒。"},[4673]={title="今天要做哪种食人魔呢？",text="观察者克鲁什刷新时可以选择成为一名牧师、萨满或法师。"},[4685]={title="法师克鲁什"},[4689]={title="冰霜新星",text="观察者克鲁什对10码范围内的所有玩家造成冰霜伤害。冰霜新星使受到影响的玩家无法移动，持续8秒。"},[4688]={title="火球术",text="观察者克鲁什对一名玩家造成火焰伤害。"},[4687]={title="嗜血",text="观察者克鲁什给自己或一名盟友施加嗜血效果。受影响者的近战攻击速度提高60%，持续30秒。"},[4686]={title="魔爆术",text="观察者克鲁什对附近的所有玩家造成奥术伤害。"},[4679]={title="萨满克鲁什"},[4684]={title="闪电箭",text="观察者克鲁什对一名玩家造成自然伤害。"},[4682]={title="地缚图腾",text="观察者克鲁什在身边召唤一个地缚图腾，持续存在30秒。"},[4683]={title="大地之缚",text="地缚图腾每5秒使10码范围内的所有玩家无法移动。"},[4681]={title="治疗波",text="观察者克鲁什为自己或一名盟友治疗。"},[4680]={title="闪电链",text="观察者克鲁什对一名玩家和附近最多2个目标造成自然伤害。"},[4674]={title="牧师克鲁什"},[4678]={title="心灵尖啸",text="观察者克鲁什使8码范围内的所有玩家因恐惧而逃跑，持续4秒。"},[4677]={title="真言术：盾",text="观察者克鲁什为自己或一名盟友附加一层神圣能量护盾，吸收伤害，并防止施法被打断。真言术：盾的效果持续30秒或在吸收过多伤害后消失。"},[4676]={title="心灵震爆",text="观察者克鲁什对一名玩家造成暗影伤害。"},[4675]={title="治疗",text="观察者克鲁什为自己或一名盟友治疗。"},[4669]={title="战争践踏",text="戈多克大王对5码范围内的所有玩家造成物理伤害，并使其昏迷5秒。"},[4668]={title="致死打击",text="戈多克大王对一名玩家造成物理伤害。致死打击使其受到的治疗量降低50%，持续5秒。"},[4667]={title="破甲攻击",text="戈多克大王使一名玩家的护甲值降低，其受到的物理伤害提高，持续30秒。破甲攻击最多可叠加5层。"},[4666]={title="狂暴冲锋",text="戈多克大王随机向一名玩家冲锋，将其击飞，并造成物理伤害。"},[4844]={title="女妖诅咒",text="安娜丝塔丽男爵夫人诅咒10码范围内的所有玩家，使其命中几率降低，持续12秒。"},[4843]={title="沉默",text="安娜丝塔丽男爵夫人使10码范围内的所有玩家沉默，使其无法施法，持续10秒。"},[4842]={title="女妖哀嚎",text="安娜丝塔丽男爵夫人发出痛苦的哀嚎，对当前目标造成128到172点暗影伤害。"},[4841]={title="占据",text="安娜丝塔丽男爵夫人随机控制一名玩家。控制期间，目标最大生命值和造成的伤害提高100%，但受到的治疗效果和护甲值降低。目标将被控制2分钟，或直到其生命值降至50%。"},[4850]={title="覆体之网",text="奈鲁布恩坎将一名玩家包裹在蛛网中，使其无法移动，并使其近战攻击间隔延长100%，持续6秒。"},[4849]={title="穿刺护甲",text="奈鲁布恩坎穿刺当前目标，使其护甲值降低50%，持续20秒。"},[4848]={title="地穴甲虫",text="奈鲁布恩坎向玩家释放圣甲虫，造成物理伤害。"},[4845]={title="复活亡灵甲虫",text="奈鲁布恩坎复活死亡的圣甲虫协助她作战。"},[4846]={title="亡灵甲虫",text="亡灵甲虫协助奈鲁布恩坎作战，使他们的目标中毒。"},[4847]={title="中毒",text="亡灵甲虫的近战攻击有一定的几率使当前目标中毒，每3秒造成24点自然伤害，持续30秒。"},[4854]={title="寒冰箭",text="苍白的玛勒基对当前目标造成48到64点冰霜伤害，使其移动速度降低50%，持续4秒。"},[4853]={title="寒冰之墓",text="苍白的玛勒基将当前目标冻结在寒冰中，使其昏迷10秒。"},[4852]={title="霜甲术",text="苍白的玛勒基将自己包裹在一层冰霜之中，使自身受到的物理伤害降低。近战攻击者将被冰冻，移动速度降低30%，急速降低25%。"},[4851]={title="吸取生命",text="苍白的玛勒基从当前目标身上吸取生命，每1秒造成暗影伤害，持续5秒，并对自己进行治疗，数值相当于其造成伤害值的100%。"},[4858]={title="吸血打击",text="巴瑟拉斯镇长的爆击会从其当前目标身上吸取250点生命值，并为自身恢复等量的生命值。"},[4856]={title="狂暴怒火",text="巴瑟拉斯镇长激怒，其造成的物理伤害和近战攻击速度提高4%，持续1分钟。该效果可叠加。"},[4857]={title="强力冲锋",text="巴瑟拉斯镇长朝一名随机目标冲锋，造成物理伤害并使其昏迷。"},[4855]={title="群体打击",text="巴瑟拉斯镇长拳击10码范围内的所有玩家，造成物理伤害，打断其施法，持续5秒，并将其击退。"},[4861]={title="乱舞",text="吞咽者拉姆斯登造成爆击之后的下3次攻击的攻击速度提高30%。"},[4860]={title="践踏",text="吞咽者拉姆斯登对10码范围内的所有玩家造成物理伤害。"},[4859]={title="击昏",text="吞咽者拉姆斯登对当前目标造成物理伤害，将其击退，并使其威胁值减半，昏迷6秒。"},[4868]={title="顺劈斩",text="奥里克斯·瑞文戴尔领主劈砍当前目标，对其及离其最近的盟友造成物理伤害。"},[4867]={title="致死打击",text="奥里克斯·瑞文戴尔领主打击当前目标，造成物理伤害，并使其受到的所有治疗效果降低50%，持续5秒。"},[4866]={title="暗影炸弹",text="奥里克斯·瑞文戴尔领主向一名玩家发射一大股黑暗魔法，造成288到388点暗影伤害。"},[29936]={title="暗影箭",text="奥里克斯·瑞文戴尔领主向一名玩家发射一股黑暗魔法，造成128到172点暗影伤害。"},[4865]={title="邪恶光环",text="奥里克斯·瑞文戴尔领主的邪恶光环每2秒对30码范围内的所有玩家造成150点暗影伤害。"},[4862]={title="亡者复生",text="奥里克斯·瑞文戴尔领主复活6个无脑的骷髅为他作战。"},[4864]={title="天灾契约",text="奥里克斯·瑞文戴尔领主将在12秒后牺牲所有剩余的无脑的骷髅，用其剩余的生命值为自己治疗。"},[4863]={title="无脑的骷髅",text="无脑的骷髅协助奥里克斯·瑞文戴尔领主作战。"},[12118003]={title="暗影震击",text="鲁西弗隆以暗影能量冲击附近的敌人，造成暗影伤害。"},[12118002]={title="鲁西弗隆的诅咒",text="鲁西弗隆诅咒整个团队，使其法术和技能的法力消耗大幅提高。"},[12118001]={title="末日降临",text="鲁西弗隆对一名玩家施加末日降临，数秒后爆发，造成大量暗影伤害。"},[11982004]={title="熔岩喷吐",text="玛格曼达向敌人喷吐熔岩，造成火焰伤害。"},[11982003]={title="熔岩炸弹",text="玛格曼达向远处的一名玩家投掷熔岩炸弹，形成一片火池，对站在其中的任何人造成大量火焰伤害。"},[11982002]={title="恐慌",text="玛格曼达发出一声恐怖的咆哮，使附近的玩家在熔岩地面上惊恐逃窜。"},[11982001]={title="狂乱",text="玛格曼达陷入狂乱，攻击速度大幅提高。猎人的宁神射击可以平息这种狂乱。"},[12259003]={title="暗影箭",text="基赫纳斯向目标投掷一支暗影箭，造成大量暗影伤害。"},[12259002]={title="火焰之雨",text="基赫纳斯召唤火焰之雨，对区域内的所有敌人造成持续的火焰伤害。"},[12259001]={title="基赫纳斯的诅咒",text="基赫纳斯诅咒整个团队，使其受到的所有治疗效果降低75%。"},[12057002]={title="熔岩镣铐",text="加尔用熔岩镣铐束缚附近的玩家，大幅降低其移动速度。"},[12057001]={title="反魔法脉冲",text="加尔释放反魔法脉冲，驱散附近玩家身上的有益魔法效果。"},[12264005]={title="衰减魔法",text="沙斯拉尔为自己施加护盾，降低其受到的魔法伤害。"},[12264004]={title="魔爆术",text="沙斯拉尔释放一股奥术能量，对附近的所有敌人造成大量奥术伤害。"},[12264003]={title="法术反制",text="沙斯拉尔反制一名敌人的法术，使该系法术在数秒内无法施放。"},[12264002]={title="沙斯拉尔之门",text="沙斯拉尔闪现到一名随机玩家身边，传送到团队中间，并重置他的威胁值列表。"},[12264001]={title="沙斯拉尔的诅咒",text="沙斯拉尔诅咒一名玩家，使其受到的魔法伤害提高。"},[12056004]={title="末日决战",text="濒死之时，迦顿男爵会释放末日决战，以毁灭性的火焰伤害重创整个团队。"},[12056003]={title="点燃法力",text="迦顿男爵点燃一名玩家的法力，在法力燃尽的过程中将其抽干并造成火焰伤害。"},[12056002]={title="地狱火",text="迦顿男爵爆发出地狱火，在数秒内对附近的所有玩家造成逐渐增强的脉冲火焰伤害。"},[12056001]={title="活化炸弹",text="迦顿男爵将一名玩家变成活动炸弹。数秒后该玩家会爆炸，对附近的所有人造成大量火焰伤害并将其击退。在爆炸前远离团队。"},[12098004]={title="击倒",text="萨弗隆将目标击倒，使其短暂昏迷。"},[12098003]={title="挫志怒吼",text="萨弗隆发出挫志怒吼，降低附近敌人的攻击强度。"},[12098002]={title="灵感",text="萨弗隆激励他的火妖祭司，提高其攻击速度和施法速度。"},[12098001]={title="拉格纳罗斯之手",text="萨弗隆用拉格纳罗斯之手猛击地面，对附近的玩家造成火焰伤害并将其击退。"},[11988003]={title="炎爆术",text="古雷曼格向远处的一名敌人投掷一枚巨大的炎爆术，造成大量火焰伤害。"},[11988002]={title="地震术",text="古雷曼格践踏地面，对附近的所有玩家造成物理伤害并使其短暂昏迷。"},[11988001]={title="熔岩喷溅",text="古雷曼格的攻击会将熔岩溅到目标身上，这一可叠加的负面效果会使其受到的火焰伤害提高。"},[12018003]={title="冲击波",text="管理者埃克索图斯释放火焰冲击波，对附近的玩家造成火焰伤害并使其减速。"},[12018002]={title="伤害反射护盾",text="管理者埃克索图斯用伤害反射护盾环绕自身，将部分近战伤害反射给攻击者。"},[12018001]={title="魔法反射",text="管理者埃克索图斯为自己和他的卫士施加护盾，将有害魔法反射回施法者。在护盾消失前停止施法。"},[11502005]={title="烈焰之子",text="拉格纳罗斯会不时潜入火焰之地，召唤他的烈焰之子攻击团队，然后再次现身。"},[11502004]={title="元素火焰",text="拉格纳罗斯用元素火焰灼烧目标，造成持续的火焰伤害。"},[11502003]={title="熔岩喷溅",text="拉格纳罗斯使熔岩从火焰之地喷涌而出，对位于其上方的任何玩家造成大量火焰伤害。"},[11502002]={title="拉格纳罗斯之手",text="拉格纳罗斯猛击熔岩地面，对附近的所有玩家造成火焰伤害并将其击退。"},[11502001]={title="拉格纳罗斯之怒",text="拉格纳罗斯以怒火打击一名玩家，造成火焰伤害并以巨大的力量将其击飞。"},[10184007]={title="奥妮克希亚雏龙",text="在空中阶段，奥妮克希亚会从洞穴边缘的龙蛋中召唤一波又一波的奥妮克希亚雏龙围攻团队。"},[10184006]={title="龙尾扫击",text="奥妮克希亚甩动尾巴，将站在她身后的玩家扫飞到洞穴另一头。"},[10184005]={title="龙翼攻击",text="奥妮克希亚用双翼拍击前方区域，造成物理伤害，击退玩家并降低其威胁值。"},[10184004]={title="火球术",text="在空中时，奥妮克希亚会向随机玩家投掷火球，造成大量火焰伤害。"},[10184003]={title="低沉咆哮",text="在最后阶段，奥妮克希亚会反复发出低沉咆哮，使整个团队惊恐逃窜。"},[10184002]={title="火息术",text="奥妮克希亚向前方喷出锥形火焰，对其中的所有敌人造成大量火焰伤害。"},[10184001]={title="深呼吸",text="奥妮克希亚深吸一口气，然后呼出一道横贯整个洞穴的火墙，对其路径上的任何人造成毁灭性的火焰伤害。"},[12435004]={title="顺劈斩",text="拉佐格尔对其前方的所有敌人发动顺劈斩，造成大量物理伤害。"},[12435003]={title="破胆咆哮",text="拉佐格尔发出破胆咆哮，使附近的玩家惊恐逃跑。"},[12435002]={title="连珠火球",text="拉佐格尔释放连珠火球，对多名敌人造成火焰伤害。"},[12435001]={title="燃烧",text="拉佐格尔对一名玩家施放燃烧，造成持续的火焰伤害，并使其在混乱中逃窜。"},[13020005]={title="龙尾扫击",text="瓦拉斯塔兹甩动尾巴，对其身后的敌人造成物理伤害并将其击退。"},[13020004]={title="顺劈斩",text="瓦拉斯塔兹对其面前的所有敌人发动顺劈斩，造成大量物理伤害。"},[13020003]={title="火息术",text="瓦拉斯塔兹喷出锥形火焰，对其前方的所有敌人造成大量火焰伤害。"},[13020002]={title="燃烧刺激",text="瓦拉斯塔兹使一名玩家受到燃烧刺激的影响；该玩家的施法将变为瞬发，但最终会发生致命的爆炸，对附近的所有人造成巨额火焰伤害。当前的坦克会周期性地受到该效果影响，并且无法幸存。"},[13020001]={title="红龙精华",text="瓦拉斯塔兹赐予团队红龙精华，为他们注满法力、怒气和能量，好让他们在燃烧刺激吞噬所有人之前将他击败。"},[12017004]={title="顺劈斩",text="勒什雷尔对其前方的所有敌人发动顺劈斩，造成大量物理伤害。"},[12017003]={title="冲击波",text="勒什雷尔释放火焰冲击波，对附近的玩家造成火焰伤害并将其击退。"},[12017002]={title="击飞",text="勒什雷尔将目标击退，造成物理伤害并大幅降低其威胁值。"},[12017001]={title="致死打击",text="勒什雷尔发动致死打击，造成大量物理伤害，并降低目标受到的治疗效果。"},[11983003]={title="龙翼打击",text="费尔默用双翼拍击前方区域，造成物理伤害，击退玩家并降低其威胁值。"},[11983002]={title="烈焰打击",text="费尔默以烈焰打击前方的敌人，这一可叠加的负面效果会使其受到的火焰伤害提高，直到他们脱离视线。"},[11983001]={title="暗影烈焰",text="费尔默喷出大范围锥形暗影烈焰，造成毁灭性的暗影伤害，并使受害者变得脆弱。"},[14601003]={title="龙翼打击",text="埃博诺克用双翼拍击前方区域，造成物理伤害，击退玩家并降低其威胁值。"},[14601002]={title="暗影烈焰",text="埃博诺克喷出大范围锥形暗影烈焰，造成毁灭性的暗影伤害，并使受害者变得脆弱。"},[14601001]={title="埃博诺克之影",text="埃博诺克用他的暗影诅咒目标，每次击中该目标时都会治疗自己。受影响的坦克必须换下，直到负面效果消失。"},[11981003]={title="龙翼打击",text="弗莱格尔用双翼拍击前方区域，造成物理伤害，击退玩家并降低其威胁值。"},[11981002]={title="暗影烈焰",text="弗莱格尔喷出大范围锥形暗影烈焰，造成毁灭性的暗影伤害，并使受害者变得脆弱。"},[11981001]={title="疯狂",text="弗莱格尔会周期性地进入狂乱状态，提高其攻击速度。猎人的宁神射击可以平息这种狂乱。"},[14020005]={title="疯狂",text="克洛玛古斯陷入狂乱，提高其攻击速度。猎人的宁神射击可以平息这种狂乱。"},[14020004]={title="腐蚀酸液",text="克洛玛古斯喷吐腐蚀酸液，造成持续的自然伤害，并降低被击中者的护甲值。"},[14020003]={title="焚烧",text="克洛玛古斯喷出一股烈焰洪流，对其面前的所有敌人造成大量火焰伤害。"},[14020002]={title="时间流逝",text="克洛玛古斯的时间流逝吐息造成奥术伤害，并扭曲受害者周围的时间，大幅降低其威胁值。"},[14020001]={title="龙血之痛",text="克洛玛古斯使团队承受五种颜色的龙血之痛。身负全部五种效果的玩家会变异为多彩龙兽，因此必须谨慎地分组处理并驱散这些负面效果。"},[11583005]={title="顺劈斩",text="奈法利安对其前方的所有敌人发动顺劈斩，造成大量物理伤害。"},[11583004]={title="龙尾扫击",text="奈法利安甩动尾巴，对站在他身后的敌人造成物理伤害并使其昏迷。"},[11583003]={title="低沉咆哮",text="奈法利安发出低沉咆哮，使整个团队惊恐逃窜。"},[11583002]={title="职业点名",text="在整个最后阶段，奈法利安会对特定职业发出嘲弄的命令——让战士陷入狂暴、使猎人的远程武器失效、将团队中的法师变形等等——每次都会使该职业在数秒内受到干扰。"},[11583001]={title="暗影烈焰",text="奈法利安喷出暗影烈焰，对其前方大范围弧形区域内的所有敌人造成毁灭性的暗影伤害。"},[14507004]={title="毒液喷吐",text="生命值较低时，温诺希斯会变形为一条巨大的眼镜蛇，喷吐毒液，造成持续的自然伤害并使团队中毒。"},[14507003]={title="恢复",text="温诺希斯对自己施放恢复，持续恢复生命值。"},[14507002]={title="神圣新星",text="温诺希斯释放一股神圣能量，对附近的所有敌人造成神圣伤害。"},[14507001]={title="神圣之火",text="温诺希斯用神圣之火吞没一名敌人，立即造成神圣伤害，并在一段时间内造成额外的神圣伤害。"},[14517005]={title="蝙蝠群",text="在整场战斗中，耶克里克会召唤成群的疯狂的觅血蝠骚扰团队。"},[14517004]={title="强效治疗术",text="耶克里克引导一次强力的治疗来恢复自己的生命值。打断它以保持压力。"},[14517003]={title="心灵尖啸",text="处于巨魔形态时，耶克里克会释放心灵尖啸，使附近的玩家惊恐逃跑。"},[14517002]={title="冲锋",text="耶克里克冲向远处的一名玩家，迅速拉近距离并使其短暂昏迷。"},[14517001]={title="音爆",text="处于蝙蝠形态时，耶克里克会释放音波爆破，造成大量物理伤害，并使被击中者沉默。"},[14510004]={title="激怒",text="濒死之时，玛尔里会进入激怒状态，提高其攻击速度和造成的伤害。"},[14510003]={title="冲锋",text="玛尔里冲向远处的一名玩家，迅速拉近距离并使其昏迷。"},[14510002]={title="玛尔里的爪牙",text="玛尔里变形为一只巨大的蜘蛛，并产下成群的玛尔里的爪牙，它们孵化后会成长为致命的幼体。"},[14510001]={title="毒箭之雨",text="玛尔里投掷一阵毒液箭雨，对团队造成自然伤害。"},[11382005]={title="奥根",text="曼多基尔骑着他的魔暴龙奥根投入战斗；一旦奥根被杀死，血领主就会徒步作战。"},[11382004]={title="旋风斩",text="曼多基尔旋转形成旋风，对附近的所有玩家造成物理伤害。"},[11382003]={title="冲锋",text="曼多基尔冲向远处的一名玩家，迅速拉近距离并对其造成物理伤害。"},[11382002]={title="血领主之怒",text="曼多基尔每杀死一名玩家就会变得更强，在接下来的战斗中体型增大，造成的伤害提高。"},[11382001]={title="威慑凝视",text="曼多基尔以威慑凝视盯住一名玩家。如果该玩家在被注视时移动或行动，他就会冲锋并将其击倒——在效果消失前保持不动。"},[15114003]={title="猛击",text="加兹兰卡猛击附近的一名玩家，造成大量物理伤害。"},[15114002]={title="冰息术",text="加兹兰卡喷出锥形冰霜，造成冰霜伤害并使被击中者减速。"},[15114001]={title="巨型喷泉",text="加兹兰卡在一名玩家脚下召唤巨型喷泉，将其高高抛向空中。"},[14509005]={title="狂乱",text="以猛虎形态复活后，塞卡尔会陷入狂乱，以迅猛残暴的攻击撕咬团队。"},[14509004]={title="嗜血",text="塞卡尔进入嗜血状态，提高其攻击速度。"},[14509003]={title="沉默",text="塞卡尔使附近的施法者沉默，使其在数秒内无法施法。"},[14509002]={title="致死顺劈",text="塞卡尔对目标发动致死顺劈，造成大量物理伤害并降低其受到的治疗效果。"},[14509001]={title="复活",text="塞卡尔和他的两名狂热者会互相复活，除非三者在很短的时间内相继被击败。"},[14515004]={title="暗言术：痛",text="娅尔罗使一名玩家承受灼烧般的痛苦，造成持续的暗影伤害。"},[14515003]={title="旋风斩",text="娅尔罗旋转形成旋风，对附近的所有玩家造成物理伤害。"},[14515002]={title="凿击",text="娅尔罗凿击目标，造成物理伤害并使其短暂失去行动能力。"},[14515001]={title="娅尔罗的印记",text="娅尔罗标记一名玩家后消失，并召唤成群的黑豹，它们会锁定并冲向被标记的目标。"},[11380004]={title="治疗结界",text="金度召唤一个治疗结界快速治疗自己；必须摧毁它才能继续推进战斗。"},[11380003]={title="金度之影",text="金度召唤出黑暗的金度之影，它们会追击团队中的施法者并吸取其法力值。"},[11380002]={title="强力妖术",text="金度对一名玩家施放妖术，将其变为一只无害的青蛙，使其无法使用技能，直到诅咒被移除。"},[11380001]={title="洗脑图腾",text="金度放置一个洗脑图腾，控制附近玩家的心智。迅速摧毁它。"},[14834004]={title="疯狂",text="哈卡使一名玩家陷入疯狂，使其在一段时间内攻击自己的盟友。"},[14834003]={title="堕落之血",text="哈卡使一名玩家感染堕落之血，这种剧毒的折磨会造成大量暗影伤害，并会传染给附近的任何人。"},[14834002]={title="酸性血液虹吸",text="哈卡虹吸团队的血液，吸取他们的生命来治疗自己。"},[14834001]={title="哈卡莱的守护",text="在每位高阶祭司被杀死之前，哈卡会使用他们的守护之力——耶克里克的蝙蝠、温诺希斯的恢复、玛尔里的毒药、塞卡尔的狂乱以及娅尔罗的凝视。先清除这些祭司可以剥夺这些力量。"},[15082003]={title="槌击",text="格里雷克用凶猛的双手重击槌击目标，造成大量物理伤害。"},[15082002]={title="大地震颤",text="格里雷克重击地面，对附近的玩家造成物理伤害并打断其施法。"},[15082001]={title="冲锋",text="格里雷克冲向远处的一名玩家，迅速拉近距离并对其造成大量物理伤害。"},[15083003]={title="梦魇幻象",text="哈扎拉尔召唤梦魇幻象攻击团队，同时将自己隐藏在其中。"},[15083002]={title="法力燃烧",text="哈扎拉尔燃烧一名玩家的法力，根据燃烧的法力值造成相应的暗影伤害。"},[15083001]={title="催眠术",text="哈扎拉尔使一名玩家陷入沉睡，使其失去行动能力，直到受到伤害为止。"},[15084003]={title="消失与伏击",text="雷纳塔基从视野中消失，然后出现在一名随机玩家身后，对其发动伏击，造成巨额物理伤害。"},[15084002]={title="凿击",text="雷纳塔基凿击目标，造成物理伤害并使其短暂失去行动能力。"},[15084001]={title="千刃",text="雷纳塔基以千刃之势攻击目标，迅速造成一连串大量物理伤害。"},[15085003]={title="战争践踏",text="乌苏雷践踏地面，使附近的所有玩家短暂昏迷。"},[15085002]={title="闪电链",text="乌苏雷投掷一道在附近玩家之间弹跳的闪电，造成自然伤害。"},[15085001]={title="落雷之云",text="乌苏雷在地面上空召唤一片闪电之云，对站在其下方的任何玩家造成自然伤害。"},[15348003]={title="激怒",text="在战斗过程中，库林纳克斯会逐渐被激怒，造成的伤害不断提高——必须在其变得致命之前将其杀死。"},[15348002]={title="沙漠陷阱",text="库林纳克斯在团队脚下召唤沙漠陷阱，陷阱受到触动时会爆发，造成大量自然伤害并将玩家抛向空中。"},[15348001]={title="重伤",text="库林纳克斯的攻击会造成重伤，这一可叠加的负面效果会降低目标受到的治疗效果。"},[15341003]={title="雷霆一击",text="拉贾克斯猛击地面，对附近的玩家造成自然伤害并降低其攻击速度。"},[15341002]={title="雷霆震裂",text="拉贾克斯释放雷霆震裂，造成自然伤害并使附近的所有玩家昏迷。"},[15341001]={title="召唤大军",text="在亲自投入战斗之前，拉贾克斯会指挥一波又一波由上尉率领的其拉大军进攻团队。"},[15340003]={title="召唤法力恶魔",text="莫阿姆召唤法力恶魔吸取团队的法力，并化为石头进行充能，直至能量充满。"},[15340002]={title="奥术爆发",text="一旦积满窃取的法力，莫阿姆就会爆发出奥术能量，对整个团队造成大量奥术伤害。"},[15340001]={title="吸取法力",text="莫阿姆吸取团队中施法者的法力，将其转化为奥术能量，不断积蓄直至毁灭性的释放。"},[15370003]={title="虫群瘟疫",text="当他的虫卵全部消失后，布鲁会使团队感染虫群瘟疫，造成逐渐增强的持续自然伤害。"},[15370002]={title="虫卵爆炸",text="在他的虫卵被摧毁之前，布鲁受到的伤害大幅降低。每个虫卵被打破时都会猛烈爆炸，削弱布鲁，但也会伤害团队。"},[15370001]={title="全速",text="布鲁会锁定一名玩家并全速追击，无视其他所有人。团队必须引着他在他的虫卵之间周旋。"},[15369003]={title="毒性钉刺",text="在空中时，阿亚米斯会向远处的一名玩家射出毒性钉刺，造成大量自然伤害。"},[15369002]={title="钉刺喷射",text="阿亚米斯喷射一阵钉刺，对她前方的玩家造成自然伤害。"},[15369001]={title="麻痹",text="阿亚米斯麻痹一名随机玩家，并使其漂浮到献祭祭坛上，除非团队出手干预，否则她的虫群会以该玩家为食。"},[15339003]={title="至尊模式",text="如果没有及时在水晶处削弱奥斯里安，他就会进入至尊模式，以压倒性的力量摧毁团队。"},[15339002]={title="沙尘风暴",text="沙之旋风横扫整个场地，将接触到的任何玩家高高抛向空中。"},[15339001]={title="奥斯里安之力",text="奥斯里安会获得一个可叠加的增益效果，使其伤害不断提高。只有将他引到散布在场地周围的水晶上，才能移除该效果。"},[15263004]={title="镜像",text="斯克拉姆会不时分裂出自己的幻象分身，每个分身都能施放他的法术。必须消灭这些镜像才能找到真正的预言者。"},[15263003]={title="地面震击",text="斯克拉姆对一名玩家施放地震术，造成自然伤害并打断其施法。"},[15263002]={title="魔爆术",text="斯克拉姆释放一股奥术能量，对附近的所有玩家造成大量奥术伤害。"},[15263001]={title="充实",text="斯克拉姆控制一名玩家的心智，使其在一段时间内攻击团队。"},[15511006]={title="亚尔基公主：恐惧",text="亚尔基公主使附近的玩家陷入恐惧并逃跑，并在死亡时召唤亚尔基的血脉。"},[15511005]={title="亚尔基公主：治疗",text="亚尔基公主会对她的兄弟引导强力的治疗，除非被打断，否则团队的进度将会白费。"},[15511004]={title="维姆之怒",text="如果维姆比他的兄妹先倒下，亚尔基公主和克里勋爵会在剩余的战斗中陷入激怒——必须最后杀死维姆。"},[15511003]={title="维姆：冲锋与击退",text="维姆在房间中来回冲锋并将目标击退，不断拉近距离又重新拉开。"},[15511002]={title="克里勋爵：毒性云雾",text="克里勋爵死亡时，他的尸体会爆发出一团持续存在的毒云，对停留在其中的任何人造成大量自然伤害。"},[15511001]={title="克里勋爵：毒性箭雨",text="克里勋爵射出一阵毒刺，造成自然伤害并使团队中毒。"},[15516004]={title="皇家卫兵",text="沙尔图拉与她的皇家卫兵并肩作战，这些卫兵也会使用旋风斩，团队必须对其进行控制。"},[15516003]={title="激怒",text="沙尔图拉进入激怒状态，提高其攻击速度和造成的伤害。"},[15516002]={title="破甲顺劈",text="沙尔图拉劈砍面前的所有敌人，造成大量物理伤害。"},[15516001]={title="旋风斩",text="沙尔图拉以无情的旋风斩旋转，对附近的所有玩家造成大量物理伤害，同时难以预测地移动。"},[15510003]={title="召唤爪牙",text="范克瑞斯将玩家传送到他的虫群之中，并召唤范克瑞斯的爪牙和维克尼雏虫来压倒团队。"},[15510002]={title="纠缠",text="范克瑞斯用蛛网缠住一名随机玩家，使其被定身在原地，并生成一只范克瑞斯的爪牙攻击该玩家。"},[15510001]={title="重伤",text="范克瑞斯的攻击会造成重伤，这一可叠加的负面效果会降低目标受到的治疗效果。"},[15299003]={title="剧毒",text="维希度斯用剧毒毒害攻击他的敌人，造成持续的自然伤害。"},[15299002]={title="毒箭之雨",text="维希度斯投掷一阵毒液箭雨，对团队造成自然伤害。"},[15299001]={title="冰霜易伤",text="维希度斯对冰霜伤害很脆弱。足够的冰霜伤害会使他减速，然后将其冻结，之后一连串的近战攻击会将他击碎成维希度斯水滴。"},[15509004]={title="翼龙钉刺",text="哈霍兰用钉刺攻击一名玩家，使其陷入中毒的昏睡，直到毒液效果结束。"},[15509003]={title="致命剧毒",text="哈霍兰喷射致命剧毒，对被击中者造成持续的自然伤害。"},[15509002]={title="狂暴",text="当生命值低于30%时，哈霍兰会进入狂暴状态，对整个团队释放不间断的毒液洪流，直到她倒下。"},[15509001]={title="疯狂",text="哈霍兰会周期性地进入狂乱状态，提高其攻击速度和施法速度。猎人的宁神射击可以平息这种狂乱。"},[15276006]={title="维克尼拉斯：上钩拳",text="维克尼拉斯大帝以一记强力的上钩拳将目标击飞到空中。"},[15276005]={title="维克尼拉斯：重压打击",text="维克尼拉斯大帝发动重压打击，造成大量物理伤害并降低目标的防御。"},[15276004]={title="维克洛尔：暴风雪",text="维克洛尔大帝召唤暴风雪，对大片区域造成冰霜伤害。"},[15276003]={title="维克洛尔：奥术爆裂",text="受到近战攻击时，维克洛尔大帝会释放奥术爆裂，造成大量奥术伤害并击退附近的玩家——必须在远处与他作战。"},[15276002]={title="维克洛尔：暗影箭",text="维克洛尔大帝从远处向团队投掷强力的暗影箭。"},[15276001]={title="双子传送与治疗",text="两位皇帝每三十秒交换一次位置，每当他们彼此靠近时，就会将对方完全治疗——必须将他们分开坦住，并让两人同时倒下。"},[15517004]={title="激怒",text="如果战斗持续时间过长，奥罗会进入激怒状态，造成的伤害大幅提高。"},[15517003]={title="潜地与召唤",text="奥罗会周期性地钻入沙中，召唤土堆和奥罗甲虫，然后再钻回地面。"},[15517002]={title="大地破裂",text="当奥罗从沙中钻出时，团队脚下的地面会破裂，造成物理伤害并击退玩家。"},[15517001]={title="沙尘爆裂",text="奥罗释放沙尘爆裂，对其前方的玩家造成巨额自然伤害。"},[15727004]={title="消化酸液",text="被吞入克苏恩胃中的玩家会浸泡在消化酸液中，持续受到自然伤害，直到他们逃出。"},[15727003]={title="血肉触须与胃袋",text="在身体阶段，克苏恩会将玩家整个吞入胃中，必须在胃中摧毁两条血肉触须才能使克苏恩变得脆弱。在此期间，巨钩触须和巨眼触须会不断从身体中钻出。"},[15727002]={title="眼棱",text="克苏恩的眼球发射绿色光束，在附近的玩家之间连锁弹跳，造成自然伤害。"},[15727001]={title="黑暗闪耀",text="在眼球阶段，克苏恩的巨眼会释放旋转的黑暗闪耀——一道横扫的光束，会立即杀死它触及的一切。躲到房间的柱子后面。"},[15956003]={title="死尸甲虫",text="被杀死的地穴卫士以及首领自己的尸体中会钻出死尸甲虫，蜂拥攻击团队。"},[15956002]={title="虫群风暴",text="阿努布雷坎召唤虫群风暴环绕自身，吸取附近玩家的生命并使其沉默。坦克必须引着他远离团队，直到效果结束。"},[15956001]={title="穿刺",text="阿努布雷坎从地面突刺出一排尖刺，造成大量物理伤害并将玩家抛向空中。"},[15953003]={title="狂乱",text="法琳娜会进入激怒状态，造成的伤害大幅提高。精神控制她的一名膜拜者并释放其黑女巫的拥抱，可以移除她的狂乱并使其沉默。"},[15953002]={title="火焰之雨",text="法琳娜召唤火焰之雨，对区域内的所有玩家造成火焰伤害。"},[15953001]={title="毒箭之雨",text="法琳娜射出一阵毒液箭雨，对团队造成大量自然伤害。"},[15952004]={title="狂乱",text="当生命值低于30%时，迈克斯纳会陷入狂乱，攻击速度大幅提高。"},[15952003]={title="死灵之毒",text="迈克斯纳的撕咬会注入死灵之毒，大幅降低目标受到的治疗效果。"},[15952002]={title="蛛网喷射",text="迈克斯纳向团队喷射蛛网，使所有人昏迷数秒。"},[15952001]={title="蛛网裹体",text="迈克斯纳将玩家甩到洞穴墙壁上，用蛛网将其包裹起来，直到他们被盟友救出。"},[15954003]={title="闪现与复活死者",text="诺斯会闪现脱离近战范围，并复活瘟疫勇士和瘟疫战士，还会周期性地传送到他的阳台上，派出骷髅攻击团队。"},[15954002]={title="残废术",text="诺斯对一名玩家施放残废术，降低其攻击速度和移动速度，并削弱其力量。"},[15954001]={title="瘟疫使者的诅咒",text="诺斯诅咒整个团队；数秒后诅咒会爆发，对仍受其影响的任何人造成大量暗影伤害。"},[15936003]={title="法术干扰",text="希尔盖干扰周围的魔法，使团队法术的法力消耗大幅提高。"},[15936002]={title="衰弱瘟疫",text="希尔盖使团队感染衰弱瘟疫，这种疾病会造成持续的自然伤害并降低最大生命值。"},[15936001]={title="爆发",text="希尔盖引导瘟疫爆发，依次横扫地面。玩家必须有节奏地穿过安全区域——也就是臭名昭著的“安全舞”——否则会被立即杀死。"},[16011003]={title="孢子",text="洛欧塞布会周期性地释放孢子；玩家需要分散开来吸收孢子，获得提高伤害所需的蘑菇花增益效果。"},[16011002]={title="必然的厄运",text="随着战斗的进行，洛欧塞布施放必然的厄运的间隔会越来越短，造成逐渐增强的暗影伤害，治疗者必须在死灵光环的间隙之间撑过这些伤害。"},[16011001]={title="死灵光环",text="洛欧塞布散发出死灵光环，阻止几乎所有的治疗。治疗只能在光环脉冲之间的短暂间隙中生效，需要精确把握冷却时间。"},[16061003]={title="瓦解怒吼",text="拉苏维奥斯发出瓦解怒吼，对他附近的所有人造成大量伤害。"},[16061002]={title="重压打击",text="拉苏维奥斯发动重压打击，造成大量物理伤害并降低目标的防御。"},[16061001]={title="见习死亡骑士",text="拉苏维奥斯只能由他的见习死亡骑士来抵挡，团队必须用服从水晶精神控制这些见习死亡骑士，并用它们来坦住他。"},[16060003]={title="收割灵魂",text="戈提克收割附近玩家的灵魂，造成暗影伤害。"},[16060002]={title="暗影箭",text="一旦降下来作战，戈提克就会向团队投掷暗影箭，造成大量暗影伤害。"},[16060001]={title="分裂领域",text="戈提克用一道大门将团队分隔为生者和死者两侧，并派出一波又一波亡灵，这些亡灵被杀死后会跨越到另一侧。在所有增援被消灭之前，无法接近他。"},[16065005]={title="枯萎凋零",text="瑞文戴尔男爵在地面上施放枯萎凋零，对停留在其中的任何人造成持续的暗影伤害。"},[16065004]={title="神圣之怒",text="瑟里耶克爵士违背自己的意愿作战，向团队释放神圣愤怒和连锁的神圣闪电。"},[16065003]={title="虚空地带",text="女公爵布劳缪克丝在地面上召唤暗影虚空地带，对站在其中的任何人造成大量伤害。"},[16065002]={title="流星",text="库尔塔兹领主投掷炽热的流星，造成巨额火焰伤害，由附近的玩家分摊。"},[16065001]={title="骑士的印记",text="每位骑士都会为其目标烙上印记，印记会不断叠加，带来越来越强的痛苦。坦克和团队必须在房间的四个角落之间轮换，以防叠加层数变得致命。"},[16028002]={title="激怒",text="当生命值低于5%时，帕奇维克会进入激怒状态，大幅提高攻击速度，进行疯狂的最后冲击。"},[16028001]={title="仇恨打击",text="帕奇维克用仇恨打击猛击近战范围内生命值最高的玩家，造成巨额物理伤害。副坦克必须贴近站位来承受这些攻击。"},[15931003]={title="软泥喷射",text="格罗布鲁斯喷射锥形软泥，造成自然伤害并生成一个辐射软泥怪。"},[15931002]={title="毒性云雾",text="格罗布鲁斯在移动时会留下毒气云，毒气云会扩散并造成逐渐增强的自然伤害——团队必须保持地面清洁。"},[15931001]={title="变异注射",text="格罗布鲁斯对一名玩家注射变异药剂。当效果结束或被驱散时，它会爆发出持续存在的毒性云雾，因此受影响的玩家必须将其带到房间边缘。"},[15932004]={title="肉用僵尸",text="源源不断的肉用僵尸会蹒跚着走向格拉斯；任何抵达他身边的僵尸都会为他恢复大量生命值。"},[15932003]={title="恐吓咆哮",text="格拉斯发出一声恐吓咆哮，使附近的玩家惊恐逃跑。"},[15932002]={title="重伤",text="格拉斯的撕咬会造成重伤，这一可叠加的负面效果会降低坦克受到的治疗效果。"},[15932001]={title="残杀",text="格拉斯对团队和他的肉用僵尸施放屠杀，使所有人的生命值降到所剩无几。必须在僵尸抵达并治疗他之前将其消灭。"},[15928003]={title="斯塔拉格与费尔根",text="塔迪乌斯由构造体斯塔拉格和费尔根守护，必须在数秒之内相继杀死它们；在两者都倒下之前，它们的能量涌动和静止力场会不断惩罚团队。"},[15928002]={title="闪电链",text="塔迪乌斯释放闪电链，在团队中弹跳，对被击中的所有人造成自然伤害。"},[15928001]={title="极性转化",text="塔迪乌斯为每名玩家赋予正能量电荷或负能量电荷。同性电荷会相互增强；异性电荷接触时会造成致命伤害——团队必须立即按极性分开站位。"},[15989005]={title="暴风雪",text="萨菲隆召唤四处移动的暴风雪，对其中的任何人造成大量冰霜伤害。"},[15989004]={title="生命吸取",text="萨菲隆同时吸取数名玩家的生命，按造成的伤害为自己恢复生命值。"},[15989003]={title="寒冰箭",text="在飞行阶段，萨菲隆会将玩家冻结在冰块中，这些冰块随后可以作为抵挡其冰息术的掩体。"},[15989002]={title="冰息术",text="萨菲隆在空中向整个房间呼出毁灭性的冰息术。只有躲在冰块后面的玩家才能幸存。"},[15989001]={title="冰霜光环",text="萨菲隆散发出冰霜光环，对整个团队造成持续的冰霜伤害——冰霜抗性至关重要。"},[15990006]={title="法力爆炸",text="克尔苏加德引爆团队中施法者的法力，根据被摧毁的法力值造成奥术伤害。"},[15990005]={title="连发寒冰箭",text="克尔苏加德射出连发寒冰箭，对附近的所有玩家造成冰霜伤害。"},[15990004]={title="暗影裂隙",text="克尔苏加德在团队脚下打开暗影裂隙；裂隙爆发时仍站在其上方的任何玩家都会被杀死。"},[15990003]={title="克尔苏加德锁链",text="克尔苏加德用暗影锁链奴役数名玩家，使其攻击团队，直到锁链被打破。"},[15990002]={title="冰霜冲击",text="克尔苏加德用冰霜包裹一名玩家，将其冻结，并将致命的寒冷扩散给站在其附近的任何人。"},[15990001]={title="冰霜箭",text="克尔苏加德向团队投掷一支巨大的寒冰箭，造成大量冰霜伤害。"}},
