MUI_MountDB:Localize(loadstring([=[return {
[22719]={name="黑色作战陆行鸟",lore="适当加速的侏儒将成为战场上一道美丽的风景线。——大工匠梅卡托克",vendor="卡特尔中尉"},
[26656]={name="黑色其拉作战坦克",lore="虽然如今在安其拉的废墟中仍能见到其拉作战坦克的许多变种，但最黑暗邪恶的品种只能在甲虫之锣被敲响时才能见到。"},
[470]={name="黑马",lore="传说因其黑色的毛皮，这种坐骑成为了军情七处执行夜间任务时的专用坐骑。",vendor="凯蒂·亨特"},
[22718]={name="黑色作战科多兽",lore="由库卡隆的兽栏管理员驯养而成，黑色作战科多兽的性情暴躁且难以预料，它们的嘶鸣声预示着血腥的战斗即将打响。",vendor="狼骑兵波尔克"},
[22720]={name="黑色战羊",lore="由于其英勇无畏地冲向战场的表现，矮人非常珍视他们的山羊伙伴。",vendor="卡特尔中尉"},
[22721]={name="黑色作战迅猛龙",lore="与奥根出自同一个邪恶的迅猛龙家族，曾为古拉巴什帝国带来无数胜利。",vendor="狼骑兵波尔克"},
[22717]={name="黑色战驹",lore="训练有素，能适应最残酷的战场上野蛮的徒手搏斗。",vendor="卡特尔中尉"},
[22723]={name="黑色战虎",lore="和它们的夜刃豹远亲一样，老虎以锋利的爪子，惊人的敏捷和喜欢被人挠耳朵而著称。",vendor="卡特尔中尉"},
[22724]={name="黑色战狼",lore="以其敏锐的嗅觉而广受奥格瑞玛守卫的欢迎。",vendor="狼骑兵波尔克"},
[10969]={name="蓝色机械陆行鸟",lore="“地形动态输出仪与液压成像技术及平衡增强器的完美结合……”——宾吉·羽哨",vendor="米利·羽哨"},
[25953]={name="蓝色其拉作战坦克",lore="这头（相对）驯服的异种蝎只生活在安其拉的大沙漠中。"},
[17463]={name="蓝色骸骨军马",lore="被遗忘者们相信，如果没有明确的目标，就连驮兽都会因无法安息而痛苦。",vendor="撒迦利亚·普斯特"},
[458]={name="棕马",lore="因其耐心和坚韧而成为暴风城守卫的最爱。",vendor="凯蒂·亨特"},
[18990]={name="棕色科多兽",lore="“科多兽是我们人民的脊梁。无论部落走到哪里——不管因为生意、定居还是战争——你都能看到强大的科多兽。”——哈布·爪蹄",vendor="哈布·爪蹄"},
[6899]={name="棕山羊",lore="雄性山羊经常互相抵角长达几个小时，以此来吸引雌性的注意。在这一点上，它们和矮人很像。",vendor="维隆·冻石"},
[17464]={name="棕色骸骨军马",lore="被遗忘者们相信，如果没有明确的目标，就连驮兽都会因无法安息而痛苦。",vendor="撒迦利亚·普斯特"},
[6654]={name="棕狼",lore="嗥叫声非常响亮，几里外都能听见。",vendor="奥古纳罗"},
[23214]={name="军马",lore="无怨无悔的献身，必将得到圣光的救赎。"},
[6648]={name="栗色马",lore="坚韧不拔：“建造了暴风城的马。”",vendor="凯蒂·亨特"},
[6653]={name="恐狼",lore="曾被认为在遥远的北地以外的地方已经灭绝了。对那些准备过冬的人来说是无价之宝。",vendor="奥古纳罗"},
[23161]={name="恐惧战马",lore="警告：它只吸收邪能，不吃苹果。它讨厌吐核。"},
[8395]={name="绿色迅猛龙",lore="由最凶猛的先祖繁殖而来，保证绝（不）对（会）不（咬）会（得）咬（太）人（狠）。",vendor="祖尼尔"},
[5784]={name="地狱战马",lore="被恶魔能量腐蚀，并曾被迫为暗影议会效劳。"},
[23509]={name="霜狼嗥叫者",lore="由奥特兰克山脉的霜狼氏族驯养而成。",vendor="格伦达·狼心"},
[18989]={name="灰色科多兽",lore="“科多兽是我们人民的脊梁。无论部落走到哪里——不管因为生意、定居还是战争——你都能看到强大的科多兽。”——哈布·爪蹄",vendor="哈布·爪蹄"},
