[23249]={name="大型棕色科多兽",lore="作为兽群的头领，这头科多兽很好地代表了这种威震北贫瘠之地的强大生物。",vendor="哈布·爪蹄"},
[23248]={name="大型灰色科多兽",lore="作为兽群的头领，这头科多兽很好地代表了这种威震凄凉之地的强大生物。",vendor="哈布·爪蹄"},
[23247]={name="大型白色科多兽",lore="罕见的白色科多兽，首见于凄凉之地。半人马认为白色的科多兽是末日的使者。",vendor="哈布·爪蹄"},
