[10789]={name="斑点霜刃豹",lore="这头健壮的坐骑有着旺盛的食欲，以至于在暗夜精灵语中赢得了一个“龙胃”的昵称。",vendor="莱兰奈"},
[23510]={name="雷矛军用坐骑",lore="雷矛氏族的坐骑训练师有一个传统，就是将他们的名字刻在自己所驯养的每一头战羊的左角上。",vendor="盖尔丁"},
