[10793]={name="条纹夜刃豹",lore="这些敏捷的野兽被认为是艾泽拉斯最完美的掠食者之一，能够悄无声息地穿越茂密的森林。",vendor="莱兰奈"},
[23241]={name="迅捷蓝色迅猛龙",lore="作为巨魔由来已久的伙伴，这些丛林猎手与它们的主人形成了特殊的感情。它们不仅是坐骑，也是守护者和朋友。",vendor="祖尼尔"},
[23238]={name="迅捷棕山羊",lore="巴拉克托山羊结实的头骨和巨大的羊角使其成为冲向大群重甲敌人时最理想的坐骑。",vendor="维隆·冻石"},
